#[test]
fn aem_node_json_round_trips() {
    use crate::{AemNode, AemOption, OptionAlignment};
    use uuid::Uuid;

    let root = AemNode::Root {
        title: "Test Form".into(),
        children: vec![AemNode::Panel {
            uuid: Uuid::nil(),
            name: "p1".into(),
            title: "Panel 1".into(),
            children: vec![
                AemNode::TextField {
                    attrs: crate::AemAttrs::default(),
                    uuid: Uuid::nil(),
                    name: "tf".into(),
                    label: "Name".into(),
                    mandatory: true,
                    visible: true,
                    max_chars: Some(50),
                    colspan: 6,
                    dor_colspan: None,
                    bind_ref: None,
                    kind: crate::aem::TextFieldKind::Plain,
                },
                AemNode::RadioButton {
                    attrs: crate::AemAttrs::default(),
                    uuid: Uuid::nil(),
                    name: "rb".into(),
                    label: "Type".into(),
                    options: vec![AemOption {
                        label: "A".into(),
                        value: "a".into(),
                    }],
                    alignment: OptionAlignment::Vertical,
                    mandatory: false,
                    visible: true,
                    colspan: 12,
                    dor_colspan: None,
                    field_id: None,
                    conditions: vec![],
                    bind_ref: None,
                },
            ],
            is_page: true,
            attrs: crate::AemAttrs::default(),
            visible: true,
            is_conditional: false,
            dor_num_cols: None,
            colspan: 12,
            dor_colspan: None,
            bind_ref: None,
            frag_ref: None,
        }],
    };

    let json = serde_json::to_string(&root).expect("serialize AemNode");
    let back: AemNode = serde_json::from_str(&json).expect("deserialize AemNode");
    assert_eq!(
        json,
        serde_json::to_string(&back).expect("re-serialize AemNode"),
        "AemNode JSON should round-trip"
    );
}

#[test]
fn load_aem_connection_none_when_absent() {
    // The UBS profile ships its [connection] block commented out.
    let conn = crate::load_aem_connection("ubs").expect("load_aem_connection ok");
    assert!(conn.is_none(), "UBS profile has no active [connection]");
}

#[test]
fn structured_schema_is_object_with_defs() {
    let schema = crate::structured_schema();
    let obj = schema.as_object().expect("schema is a JSON object");
    let defs = obj
        .get("$defs")
        .and_then(|d| d.as_object())
        .expect("schema has $defs");
    assert!(
        defs.contains_key("StructuredNode"),
        "$defs has StructuredNode"
    );

    // FieldId is annotated `#[schemars(with = "String")]`, so the FieldNode
    // `name` property must be a plain string schema (not an object/ref).
    let name = defs
        .get("FieldNode")
        .and_then(|n| n.get("properties"))
        .and_then(|p| p.get("name"))
        .expect("FieldNode.name property exists");
    assert_eq!(name.get("type").and_then(|t| t.as_str()), Some("string"));
}

#[test]
fn deserialize_ai_nodes_with_non_uuid_field_names() {
    use crate::StructuredNode;

    // A representative slice of AI-generated output: meaningful (non-UUID)
    // field names, a select with options, a conditional referencing a field by
    // name, and a repeatable grid. This must deserialize — field names are
    // hashed into deterministic FieldIds rather than requiring canonical UUIDs.
    let json = r#"[
        {"type":"field","name":"CL_ClientType","inputType":{"type":"select","options":[
            {"name":{"de":"Firma"},"value":{"type":"text","value":"Firma"}},
            {"name":"GbR","value":{"type":"text","value":"GbR"}}
        ]},"label":{"de":[{"type":"text","content":"Adressat"}]},"value":{"type":"text","value":"Firma"}},
        {"type":"conditional","condition":{"fieldName":"CL_ClientType","value":{"type":"text","value":"Firma"}},
         "content":{"type":"paragraph","content":{"en":[{"type":"strong","content":{"type":"text","content":"X"}}]}}},
        {"type":"repeatable","minOccurrences":1,"maxOccurrences":null,"item":{"type":"gridLayout","columns":2,"elements":[
            {"span":1,"node":{"type":"field","name":"TF_FamilyName","inputType":{"type":"text"},"label":null}},
            {"span":1,"node":{"type":"field","name":"Depot","inputType":{"type":"text","max_length":3,"regex":"^[0-9]+$"},"label":{"en":[{"type":"text","content":"Depot Nr."}]}}}
        ]}}
    ]"#;

    let nodes: Vec<StructuredNode> =
        serde_json::from_str(json).expect("AI node slice deserializes");
    assert_eq!(nodes.len(), 3);
}

