#[test]
fn test_aaai_section_bind_ref_client_not_under_signature() {
    // The heading "Client" appears both as an H2 section (directly under
    // the main H1) and as a sub-heading under "Signature(s)".
    // The sections map should map "Client" to the top-level path
    // (/form/.../client), not to the nested path (/form/.../signature_s/client).
    use crate::run_exhaustive_to_merged;
    use crate::xsd::compute_bind_refs;

    let nodes =
        run_exhaustive_to_merged(input_path("AAAI_019_EN.pdf")).expect("Failed to process AAAI EN");
    let config = helpers::load_ubs_xsd_config().with_master_language("en");
    let maps = compute_bind_refs(&nodes, &config);

    let client_path = maps
        .sections
        .get("Client")
        .expect("sections map should contain 'Client'");

    // "Client" is a direct child of the H1 heading, so its path should be
    // /form/<h1_slug>/Client — NOT /form/<h1_slug>/SignatureS/Client.
    assert!(
        !client_path.contains("/SignatureS/"),
        "Client section bind_ref should NOT be under SignatureS. Got: {}",
        client_path
    );
    assert!(
        client_path.ends_with("/Client"),
        "Client section bind_ref should end with /Client. Got: {}",
        client_path
    );
}

#[test]
fn test_aaai_has_address_and_individual_fragments() {
    // AAAI has an "Authorized Representative(s)" section under "Client"
    // whose fields span two XSD types: IndividualBasicType (LastName,
    // FirstName) and AddressType (Street, StreetNumber, PostalCode, City,
    // Country).  The fragment replacement logic should insert Fragment
    // nodes for each matched type as children of the wrapping panel,
    // rather than replacing the wrapping panel itself.
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAAI_019_EN.pdf")).expect("Failed to load AAAI_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    let xsd_config = helpers::load_ubs_xsd_config().with_master_language("en");
    config.xsd_config = Some(xsd_config);

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);
    config.use_fragments = true;

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    let fragment_refs = helpers::collect_aem_fragment_refs(&root);

    // Should have at least 6 fragments: 2 Signature + 3 Address + 1 IndividualBasic
    let address_frags: Vec<_> = fragment_refs
        .iter()
        .filter(|(fr, _)| fr.contains("Address"))
        .collect();
    let individual_frags: Vec<_> = fragment_refs
        .iter()
        .filter(|(fr, _)| fr.contains("IndividualBasic"))
        .collect();

    assert!(
        !address_frags.is_empty(),
        "Should have at least one Address fragment. All fragments: {:?}",
        fragment_refs
    );
    assert!(
        !individual_frags.is_empty(),
        "Should have at least one IndividualBasic fragment. All fragments: {:?}",
        fragment_refs
    );

    // The IndividualBasic fragment is bound under its enclosing section.
    //
    // The schema is derived from the AEM tree, where only page panels nest —
    // an H3 sub-heading such as "Authorized representative" becomes a sibling
    // TitleDraw, not a container — so the path names the page ("Client"), not
    // the sub-heading. The bind path and the XSD element still agree, which is
    // what `aem_bind_refs_are_exact_xsd_paths` enforces.
    for (_, bind_ref) in &individual_frags {
        let br = bind_ref.as_deref().unwrap_or("");
        assert!(
            br.ends_with("/IndividualBasic") && br.matches('/').count() >= 3,
            "IndividualBasic fragment should be bound under its section. Got: {}",
            br
        );
    }

    // The Client panel should still exist (not be replaced)
    let mut client_panel_exists = false;
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let AemNode::Panel { title, .. } = node {
            if title.to_lowercase() == "client" {
                client_panel_exists = true;
            }
        }
    });
    assert!(
        client_panel_exists,
        "Client panel should still exist and not be replaced by a fragment"
    );
}

#[test]
fn test_fragments_work_without_bind_to_xsd() {
    // use_fragments should work independently of bind_to_xsd.
    // When bind_to_xsd=false but use_fragments=true, fragment nodes should
    // still be produced, and non-fragment nodes should have no bind_ref.
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAAI_019_EN.pdf")).expect("Failed to load AAAI_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    // Explicitly disable bind_to_xsd but enable fragments
    config.bind_to_xsd = false;
    config.use_fragments = true;
    config.xsd_config = Some(helpers::load_ubs_xsd_config().with_master_language("en"));

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    // Fragments should still be produced
    let fragment_refs = helpers::collect_aem_fragment_refs(&root);
    assert!(
        fragment_refs.len() >= 2,
        "Expected at least 2 fragment nodes with bind_to_xsd=false, found {}.\nFragments: {:?}",
        fragment_refs.len(),
        fragment_refs
    );

    // Fragment nodes should retain their bind_ref
    for (frag_ref, bind_ref) in &fragment_refs {
        assert!(
            bind_ref.is_some(),
            "Fragment '{}' should have a bind_ref even when bind_to_xsd=false",
            frag_ref
        );
    }

    // Non-fragment nodes should have no bind_ref
    helpers::walk_aem_nodes(&root, &mut |node| match node {
        AemNode::Panel { bind_ref, name, .. } => {
            assert!(
                bind_ref.is_none(),
                "Panel '{}' should have no bind_ref when bind_to_xsd=false",
                name
            );
        }
        AemNode::TextField { bind_ref, name, .. } => {
            assert!(
                bind_ref.is_none(),
                "TextField '{}' should have no bind_ref when bind_to_xsd=false",
                name
            );
        }
        _ => {}
    });
}

#[test]
fn test_aaha_de_nachname_label_is_not_contaminated_with_agreement_text() {
    // Regression test: the "Nachname" field in AAHA_019_DE should have the label
    // "Nachname" only. The agreement text ("Hiermit erkläre ich...") belongs to a
    // separate paragraph and must NOT be concatenated into that label.
    use crate::run_exhaustive_to_merged;

    let structured = run_exhaustive_to_merged(input_path("AAHA_019_DE.pdf"))
        .expect("Failed to process AAHA_019_DE.pdf");

    let field_labels = collect_field_labels_trimmed(&structured);

    println!("\n=== AAHA_019_DE field labels ===");
    for label in &field_labels {
        println!("  - '{}'", &label[..label.len().min(120)]);
    }

    // The "Nachname" label must not contain the agreement text
    let contaminated = field_labels
        .iter()
        .find(|l| l.contains("Nachname") && l.contains("Hiermit erkläre"));
    assert!(
        contaminated.is_none(),
        "Nachname field label should not include agreement text, but got: '{}'",
        contaminated.map(|s| &s[..s.len().min(200)]).unwrap_or("")
    );

    // The "Nachname" label must be present with a clean value
    let nachname_label = field_labels.iter().find(|l| l.contains("Nachname"));
    assert!(
        nachname_label.is_some(),
        "Expected a field with label containing 'Nachname', but found none. Labels: {:?}",
        field_labels
            .iter()
            .map(|l| &l[..l.len().min(60)])
            .collect::<Vec<_>>()
    );

    println!(
        "\n✓ AAHA_019_DE Nachname label is clean: '{}'",
        nachname_label.unwrap()
    );
}

#[test]
fn test_aaha_de_has_one_repeatable_with_nachname_vorname() {
    // AAHA DE should have exactly one repeatable section containing "Nachname" and
    // "Vorname(n)" fields. The signature section should NOT be a repeatable (it has
    // no add/remove buttons).
    use crate::structured::StructuredNode;

    let merged = crate::run_exhaustive_to_merged(input_path("AAHA_019_DE.pdf"))
        .expect("Failed to process AAHA_019_DE.pdf");

    fn collect_repeatables(nodes: &[StructuredNode]) -> Vec<Vec<String>> {
        let mut result = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::Repeatable(rep) => {
                    let mut labels = Vec::new();
                    collect_labels(std::slice::from_ref(rep.item.as_ref()), &mut labels);
                    result.push(labels);
                    // Also check for nested repeatables
                    result.extend(collect_repeatables(std::slice::from_ref(rep.item.as_ref())));
                }
                StructuredNode::Group(g) => result.extend(collect_repeatables(&g.children)),
                StructuredNode::Conditional(c) => {
                    result.extend(collect_repeatables(std::slice::from_ref(
                        c.content.as_ref(),
                    )));
                }
                _ => {}
            }
        }
        result
    }

    fn collect_labels(nodes: &[StructuredNode], out: &mut Vec<String>) {
        for node in nodes {
            match node {
                StructuredNode::Field(f) => {
                    if let Some(label) = &f.label {
                        let t = label.as_plain_text();
                        if !t.is_empty() {
                            out.push(t);
                        }
                    }
                }
                StructuredNode::Group(g) => collect_labels(&g.children, out),
                StructuredNode::GridLayout(grid) => {
                    for element in &grid.elements {
                        collect_labels(std::slice::from_ref(&element.node), out);
                    }
                }
                StructuredNode::Repeatable(rep) => {
                    collect_labels(std::slice::from_ref(rep.item.as_ref()), out);
                }
                StructuredNode::Conditional(c) => {
                    collect_labels(std::slice::from_ref(c.content.as_ref()), out);
                }
                _ => {}
            }
        }
    }

    let repeatables = collect_repeatables(&merged);

    assert_eq!(
        repeatables.len(),
        1,
        "AAHA DE should have exactly 1 repeatable section, found {}: {:?}",
        repeatables.len(),
        repeatables
    );

    let labels = &repeatables[0];
    assert!(
        labels.iter().any(|l| l.contains("Nachname")),
        "Repeatable should contain 'Nachname', got: {:?}",
        labels
    );
    assert!(
        labels.iter().any(|l| l.contains("Vorname")),
        "Repeatable should contain 'Vorname(n)', got: {:?}",
        labels
    );
}

#[test]
fn test_aagx_en_has_repeatable_with_lastname_firstnames() {
    // AAGX EN should contain a repeatable section with person-name fields.
    use crate::structured::StructuredNode;

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("AAGX_019_EN.pdf"))
        .expect("Failed to run exhaustive merge on AAGX_019_EN.pdf");

    let target_labels = ["Last name", "First name(s)"];
    let mut found = false;

    walk_structured_nodes(&structured_nodes, &mut |node| {
        if found {
            return;
        }
        if let StructuredNode::Repeatable(rep) = node {
            let labels = collect_field_labels_trimmed(std::slice::from_ref(rep.item.as_ref()));
            found = target_labels
                .iter()
                .all(|target| labels.iter().any(|label| label.contains(target)));
        }
    });

    assert!(
        found,
        "Expected to find a repeatable section containing fields with labels 'Last name' and 'First name(s)'"
    );
}

#[test]
fn test_aagx_en_repeatable_not_replaced_by_fragment() {
    // The repeatable section in AAGX EN (containing "Last name" / "First name(s)")
    // must remain a Repeatable node in the AEM output and NOT be replaced by a Fragment.
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAGX_019_EN.pdf")).expect("Failed to load AAGX_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    let xsd_config = helpers::load_ubs_xsd_config().with_master_language("en");
    config.xsd_config = Some(xsd_config);

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);
    config.use_fragments = true;

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    // There must be at least one Repeatable in the AEM output
    let mut has_repeatable = false;
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let AemNode::Repeatable { .. } = node {
            has_repeatable = true;
        }
    });

    assert!(
        has_repeatable,
        "AAGX EN AEM output should contain a Repeatable node (not replaced by a fragment)"
    );

    // Additionally verify no Fragment replaced the repeatable's fields
    let mut fragment_contains_person_fields = false;
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let AemNode::Fragment { frag_ref, .. } = node {
            let frag_lower = frag_ref.to_lowercase();
            if frag_lower.contains("last")
                || frag_lower.contains("first")
                || frag_lower.contains("name")
            {
                fragment_contains_person_fields = true;
            }
        }
    });

    assert!(
        !fragment_contains_person_fields,
        "AAGX EN: the person-name repeatable should NOT be replaced by a fragment"
    );
}

#[test]
fn test_aaed_de_has_two_repeatables_not_replaced_by_fragments_in_aem() {
    // Regression guard for AAED DE:
    // 1) merged structured output must contain exactly two repeatables
    // 2) AEM conversion must preserve those as repeatables (not fragment replacements)
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem, generate_aem_xml};
    use crate::structured::StructuredNode;
    use std::collections::HashSet;

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("AAED_019_DE.pdf"))
        .expect("Failed to run exhaustive merge on AAED_019_DE.pdf");

    let mut structured_repeatable_count = 0usize;
    helpers::walk_structured_nodes(&structured_nodes, &mut |node| {
        if matches!(node, StructuredNode::Repeatable(_)) {
            structured_repeatable_count += 1;
        }
    });

    assert_eq!(
        structured_repeatable_count, 2,
        "AAED should have exactly 2 repeatables in merged structured output, found {}",
        structured_repeatable_count
    );

    let mut bp =
        Blueprint::from_pdf(input_path("AAED_019_DE.pdf")).expect("Failed to load AAED_019_DE.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    let xsd_config = helpers::load_ubs_xsd_config().with_master_language("de");
    config.xsd_config = Some(xsd_config);

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);
    config.use_fragments = true;

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);
    let xml = generate_aem_xml(&root, &config);

    let mut aem_repeatable_count = 0usize;
    let mut repeatable_bind_refs: HashSet<String> = HashSet::new();
    let mut fragment_bind_refs: HashSet<String> = HashSet::new();

    helpers::walk_aem_nodes(&root, &mut |node| match node {
        AemNode::Repeatable { bind_ref, .. } => {
            aem_repeatable_count += 1;
            if let Some(bind_ref) = bind_ref {
                repeatable_bind_refs.insert(bind_ref.clone());
            }
        }
        AemNode::Fragment { bind_ref, .. } => {
            if let Some(bind_ref) = bind_ref {
                fragment_bind_refs.insert(bind_ref.clone());
            }
        }
        _ => {}
    });

    assert_eq!(
        aem_repeatable_count, 2,
        "AAED should have exactly 2 repeatables in AEM tree, found {}",
        aem_repeatable_count
    );

    assert!(
        repeatable_bind_refs.is_disjoint(&fragment_bind_refs),
        "AAED repeatable bindRefs must not appear on fragments; repeatable_bind_refs={:?}, fragment_bind_refs={:?}",
        repeatable_bind_refs,
        fragment_bind_refs
    );

    let xml_repeatable_count = xml.matches("<repeatableInner").count();
    assert_eq!(
        xml_repeatable_count, 2,
        "AAED AEM XML should contain exactly 2 repeatableInner blocks, found {}",
        xml_repeatable_count
    );
}

#[test]
fn test_aaaq_de_field_row_ordering() {
    // In AAAQ DE, the fields under the first section should be on separate rows:
    //   Row 1: Nachname, Vorname(n)
    //   Row 2: Bankbeziehung, Zusätzliche Objekte
    //   Row 3: Auszuschließende Objekte
    //
    // A bug in the XFA flattening caused heightless subforms inside areas
    // to not advance the y-cursor in positioned layout, making Nachname
    // overlap with Bankbeziehung and Vorname(n) overlap with Zusätzliche Objekte.
    use rust_decimal::Decimal;
    use std::str::FromStr;

    let mut bp =
        Blueprint::from_pdf(input_path("AAAQ_019_DE.pdf")).expect("Failed to load AAAQ_019_DE.pdf");
    let states = bp.states().expect("Failed to get form states");
    let state = states
        .iter()
        .next()
        .expect("Expected at least one form state");

    // Collect field label → y-coordinate from the flattened output
    let field_positions: Vec<(String, Decimal)> = state
        .flattened
        .iter_nodes()
        .filter_map(|node| {
            if let FlattenedNodeKind::Field { ref label, .. } = node.kind {
                let trimmed = label.trim().to_string();
                if !trimmed.is_empty() {
                    Some((trimmed, node.y))
                } else {
                    None
                }
            } else {
                None
            }
        })
        .collect();

    let find_y = |name: &str| -> Decimal {
        field_positions
            .iter()
            .find(|(label, _)| label == name)
            .unwrap_or_else(|| panic!("Field '{}' not found in flattened output", name))
            .1
    };

    let y_familyname = find_y("TF_FamilyName");
    let y_firstname = find_y("TF_FirstName");
    let y_account = find_y("AccountNumber");
    let y_zusaetzliche = find_y("Zusatzliche_Objekte");
    let y_auszuschliessende = find_y("Auszuschlie");

    // Row 1: TF_FamilyName (Nachname) and TF_FirstName (Vorname) should share the same row
    let tolerance = Decimal::from_str("5.0").unwrap();
    assert!(
        (y_familyname - y_firstname).abs() <= tolerance,
        "Nachname (y={}) and Vorname (y={}) should be on the same row",
        y_familyname,
        y_firstname
    );

    // Row 2: AccountNumber (Bankbeziehung) and Zusätzliche Objekte should share the same row
    assert!(
        (y_account - y_zusaetzliche).abs() <= tolerance,
        "Bankbeziehung (y={}) and Zusätzliche Objekte (y={}) should be on the same row",
        y_account,
        y_zusaetzliche
    );

    // Row 1 must be ABOVE Row 2 (lower y value) with meaningful separation
    assert!(
        y_account > y_familyname + tolerance,
        "Row 2 (Bankbeziehung y={}) must be below Row 1 (Nachname y={}) — fields should not overlap",
        y_account,
        y_familyname
    );

    // Row 3: Auszuschließende Objekte must be below Row 2
    assert!(
        y_auszuschliessende > y_account + tolerance,
        "Row 3 (Auszuschließende Objekte y={}) must be below Row 2 (Bankbeziehung y={})",
        y_auszuschliessende,
        y_account
    );
}

#[test]
fn test_aagg_debug_edb_structure() {
    use crate::structured::StructuredNode;
    use helpers::walk_structured_nodes;

    let de = crate::run_exhaustive_to_envelope(input_path("AAGG_019_DE.pdf"), "de").expect("DE");
    let en = crate::run_exhaustive_to_envelope(input_path("AAGG_019_EN.pdf"), "en").expect("EN");
    let sp = crate::run_exhaustive_to_envelope(input_path("AAGG_019_SP.pdf"), "sp").expect("SP");

    // Dump ALL text nodes (paragraph/heading/conditional) per language for analysis
    for (lang_name, envelope) in [("DE", &de), ("EN", &en), ("SP", &sp)] {
        println!("\n=== {} ALL TEXT NODES ===", lang_name);
        let mut node_idx = 0usize;
        walk_structured_nodes(&envelope.content, &mut |node| {
            let text = match node {
                StructuredNode::Paragraph(p) => Some(("P", p.content.as_plain_text())),
                StructuredNode::Heading(h) => Some(("H", h.content.as_plain_text())),
                StructuredNode::Conditional(c) => match c.content.as_ref() {
                    StructuredNode::Paragraph(p) => Some(("CP", p.content.as_plain_text())),
                    _ => Some((
                        "C?",
                        format!("{:?}", std::mem::discriminant(c.content.as_ref())),
                    )),
                },
                StructuredNode::Field(f) => {
                    let label = f
                        .label
                        .as_ref()
                        .map(|l| l.as_plain_text())
                        .unwrap_or_default();
                    Some(("F", label))
                }
                StructuredNode::Group(_) => Some(("G", String::new())),
                _ => None,
            };
            if let Some((kind, text)) = text {
                if !text.is_empty() {
                    let t = &text[..text.len().min(120)];
                    println!("  [{}#{:>3}] {}: {}", lang_name, node_idx, kind, t);
                }
            }
            node_idx += 1;
        });
    }
}

/// Master page background elements (like footnotes placed on the pageArea) must not
/// appear in structured output. In AAGG, the 'LastPageOnly' subform contains footnotes
/// and bank-internal fields positioned on the master page that overlap the contentArea.
/// These should be classified as Background and excluded.
#[test]
fn test_aagg_master_page_background_excluded_from_structured() {
    use crate::structured::StructuredNode;
    use helpers::walk_structured_nodes;

    let de = crate::run_exhaustive_to_envelope(input_path("AAGG_019_DE.pdf"), "de").expect("DE");

    // "ForInternalBankUse" and "SignatureVerified" are fields inside the LastPageOnly
    // master page subform. They should NOT appear in structured output.
    let mut found_internal_bank_use = false;
    let mut found_signature_verified = false;

    walk_structured_nodes(&de.content, &mut |node| {
        if let StructuredNode::Field(f) = node {
            let label_text = f
                .label
                .as_ref()
                .map(|l| l.as_plain_text())
                .unwrap_or_default();
            let field_name = f.som_path_str();
            if label_text.contains("For Internal Bank Use")
                || label_text.contains("For internal bank use")
                || field_name.contains("ForInternalBankUse")
            {
                found_internal_bank_use = true;
            }
            if label_text.contains("Signature Verified")
                || label_text.contains("signature verified")
                || field_name.contains("SignatureVerified")
            {
                found_signature_verified = true;
            }
        }
    });

    assert!(
        !found_internal_bank_use,
        "Master page 'ForInternalBankUse' field should not appear in structured output"
    );
    assert!(
        !found_signature_verified,
        "Master page 'SignatureVerified' field should not appear in structured output"
    );
}

/// Regression: AAAQ heading contains "Vollmachten".
/// The parenthetical instruction "(Auszufüllen durch Antragsteller)" is rendered
/// non-bold (CSS font-weight:normal overrides XFA font weight) and should NOT be
/// part of the heading.
#[test]
fn test_aaaq_vollmachten_heading_has_space_before_parenthesis() {
    use crate::run_exhaustive_to_merged;
    use crate::structured::StructuredNode;

    let structured = run_exhaustive_to_merged(input_path("AAAQ_019_DE.pdf"))
        .expect("Failed to process AAAQ PDF");

    fn find_vollmachten_text(nodes: &[StructuredNode]) -> Option<String> {
        for node in nodes {
            match node {
                StructuredNode::Heading(h) => {
                    let text = h.content.as_plain_text();
                    if text.contains("Vollmachten") {
                        return Some(text);
                    }
                }
                StructuredNode::Paragraph(p) => {
                    let text = p.content.as_plain_text();
                    if text.contains("Vollmachten") {
                        return Some(text);
                    }
                }
                StructuredNode::Group(g) => {
                    if let Some(t) = find_vollmachten_text(&g.children) {
                        return Some(t);
                    }
                }
                StructuredNode::Conditional(c) => {
                    if let Some(t) = find_vollmachten_text(std::slice::from_ref(c.content.as_ref()))
                    {
                        return Some(t);
                    }
                }
                StructuredNode::Repeatable(r) => {
                    if let Some(t) = find_vollmachten_text(std::slice::from_ref(r.item.as_ref())) {
                        return Some(t);
                    }
                }
                StructuredNode::GridLayout(g) => {
                    for el in &g.elements {
                        if let Some(t) = find_vollmachten_text(std::slice::from_ref(&el.node)) {
                            return Some(t);
                        }
                    }
                }
                _ => {}
            }
        }
        None
    }

    let text =
        find_vollmachten_text(&structured).expect("Expected to find text containing 'Vollmachten'");

    // "Vollmachten" is the bold heading; the non-bold parenthetical instruction
    // is correctly a separate paragraph, not part of the heading.
    assert!(
        text.contains("Vollmachten"),
        "Expected heading containing 'Vollmachten', but got: {:?}",
        text
    );
}

/// Regression: AACC EN label "RelationshipDescribe the current relationship..."
/// was missing a space between "Relationship" and "Describe".  The space must
/// be preserved when orphan paragraphs are absorbed during translation merge.
#[test]
fn test_aacc_relationship_label_has_space() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::{self, StructuredNode};

    let de = run_exhaustive_to_envelope(input_path("AACC_019_DE.pdf"), "de")
        .expect("Failed to process AACC DE");
    let en = run_exhaustive_to_envelope(input_path("AACC_019_EN.pdf"), "en")
        .expect("Failed to process AACC EN");

    let merged = structured::merge_translations(vec![de, en], None)
        .expect("Merging AACC DE/EN should succeed");

    fn find_relationship_label(nodes: &[StructuredNode], lang: &str) -> Option<String> {
        for node in nodes {
            match node {
                StructuredNode::Field(f) => {
                    if let Some(label) = &f.label {
                        let text = label.plain_text_in(lang);
                        if text.contains("Relationship") || text.contains("relationship") {
                            return Some(text);
                        }
                    }
                }
                StructuredNode::Paragraph(p) => {
                    let text = p.content.plain_text_in(lang);
                    if text.contains("Relationship") || text.contains("relationship") {
                        return Some(text);
                    }
                }
                StructuredNode::Heading(h) => {
                    let text = h.content.plain_text_in(lang);
                    if text.contains("Relationship") || text.contains("relationship") {
                        return Some(text);
                    }
                }
                StructuredNode::Group(g) => {
                    if let Some(t) = find_relationship_label(&g.children, lang) {
                        return Some(t);
                    }
                }
                StructuredNode::Conditional(c) => {
                    if let Some(t) =
                        find_relationship_label(std::slice::from_ref(c.content.as_ref()), lang)
                    {
                        return Some(t);
                    }
                }
                StructuredNode::Repeatable(r) => {
                    if let Some(t) =
                        find_relationship_label(std::slice::from_ref(r.item.as_ref()), lang)
                    {
                        return Some(t);
                    }
                }
                StructuredNode::GridLayout(g) => {
                    for el in &g.elements {
                        if let Some(t) =
                            find_relationship_label(std::slice::from_ref(&el.node), lang)
                        {
                            return Some(t);
                        }
                    }
                }
                _ => {}
            }
        }
        None
    }

    let text = find_relationship_label(&merged.content, "en")
        .expect("Expected to find text containing 'Relationship' in EN");

    // "Relationship" is the bold label; "Describe the current relationship..."
    // is rendered non-bold (CSS font-weight:normal) and is correctly a separate
    // paragraph, not part of the label text.
    assert!(
        text.contains("Relationship"),
        "Expected label containing 'Relationship', but got: {:?}",
        text
    );
}

#[test]
fn test_aaaq_radio_button_groups() {
    use crate::run_exhaustive_to_merged;
    use crate::structured::FieldType;

    let structured = run_exhaustive_to_merged(input_path("AAAQ_019_DE.pdf"))
        .expect("Failed to process AAAQ PDF");

    let radios = collect_radio_fields(&structured);

    // First radio group: FIM = Financial Intermediaries, I = Interne Kunden
    let customer_type_radio = radios
        .iter()
        .find(|field| {
            let FieldType::Radio { options } = &field.input_type else {
                return false;
            };
            options.iter().any(|o| o.name.as_str() == "FIM")
                || options
                    .iter()
                    .any(|o| o.name.as_str().contains("Financial Internediaries"))
                || options
                    .iter()
                    .any(|o| o.name.as_str().contains("Interne Kunden"))
        })
        .expect("Expected radio group with FIM / Financial Internediaries and I / Interne Kunden");

    let FieldType::Radio { options } = &customer_type_radio.input_type else {
        unreachable!()
    };

    assert_eq!(
        options.len(),
        2,
        "Expected exactly 2 options in FIM/I radio group, got: {:?}",
        options.iter().map(|o| o.name.as_str()).collect::<Vec<_>>()
    );
    let option_names: Vec<&str> = options.iter().map(|o| o.name.as_str()).collect();
    assert!(
        option_names
            .iter()
            .any(|n| n.contains("Financial Internediaries") || n.contains("FIM")),
        "Expected option for 'Financial Internediaries' / 'FIM', got: {:?}",
        option_names
    );
    assert!(
        option_names
            .iter()
            .any(|n| n.contains("Interne Kunden") || *n == "I"),
        "Expected option for 'Interne Kunden' / 'I', got: {:?}",
        option_names
    );

    // Second radio group: EAM, MFO, BBI, PLF, KVG
    let category_radio = radios
        .iter()
        .find(|field| {
            let FieldType::Radio { options } = &field.input_type else {
                return false;
            };
            options.iter().any(|o| o.name.as_str().contains("EAM"))
                && options.iter().any(|o| o.name.as_str().contains("MFO"))
        })
        .expect("Expected radio group with EAM, MFO, BBI, PLF, KVG options");

    let FieldType::Radio { options } = &category_radio.input_type else {
        unreachable!()
    };

    assert_eq!(
        options.len(),
        5,
        "Expected exactly 5 options in EAM/MFO/BBI/PLF/KVG radio group, got: {:?}",
        options.iter().map(|o| o.name.as_str()).collect::<Vec<_>>()
    );
    let option_names: Vec<&str> = options.iter().map(|o| o.name.as_str()).collect();
    for expected in &["EAM", "MFO", "BBI", "PLF", "KVG"] {
        assert!(
            option_names.iter().any(|n| n.contains(expected)),
            "Expected option containing '{}', got: {:?}",
            expected,
            option_names
        );
    }
}

#[test]
fn test_aaaq_selection_inline_fields() {
    use crate::document::modules::run_analysis_pipeline;
    use crate::document::{Document, GroupKind};

    let pdf_path = input_path("AAAQ_019_DE.pdf");
    let mut bp = crate::Blueprint::from_pdf(&pdf_path).expect("Failed to parse PDF");
    let states = bp.states().expect("Failed to get states");
    let first_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &first_state.flattened;

    let mut doc = Document::from_flattened(flattened);
    run_analysis_pipeline(&mut doc);

    // Collect all SelectionInlineField groups
    let selection_inline_fields =
        doc.find_groups(|k| matches!(k, GroupKind::SelectionInlineField { .. }));

    // Extract label texts from the detected selection inline fields
    let mut labels: Vec<String> = selection_inline_fields
        .iter()
        .filter_map(|&idx| {
            let group = doc.get_group(idx)?;
            if let GroupKind::SelectionInlineField { label_text, .. } = &group.kind {
                Some(label_text.clone())
            } else {
                None
            }
        })
        .collect();
    labels.sort();

    // Assert the four expected elements are detected:
    // 1. Checkbox "Aufschalten wie Vertrag" + field
    assert!(
        labels.iter().any(|l| l.contains("Aufschalten wie Vertrag")),
        "Expected SelectionInlineField for 'Aufschalten wie Vertrag', found: {:?}",
        labels
    );

    // 2. Checkbox "Neuer Benutzer" + field
    assert!(
        labels.iter().any(|l| l.contains("Neuer Benutzer")),
        "Expected SelectionInlineField for 'Neuer Benutzer', found: {:?}",
        labels
    );

    // 3. Radio button "Für alle Benutzer" + field
    assert!(
        labels.iter().any(|l| l.contains("Für alle Benutzer")),
        "Expected SelectionInlineField for 'Für alle Benutzer', found: {:?}",
        labels
    );

    // 4. Radio button "Nur für Benutzer Nr." + field
    assert!(
        labels.iter().any(|l| l.contains("Nur für Benutzer")),
        "Expected SelectionInlineField for 'Nur für Benutzer', found: {:?}",
        labels
    );

    // Verify the SelectionInlineField groups have correct condition types:
    // Checkboxes should have option_field_name = None
    // Radio buttons should have option_field_name = Some(...)
    for &idx in &selection_inline_fields {
        let group = doc.get_group(idx).unwrap();
        if let GroupKind::SelectionInlineField {
            option_field_name,
            label_text,
            ..
        } = &group.kind
        {
            if label_text.contains("Aufschalten wie Vertrag")
                || label_text.contains("Neuer Benutzer")
            {
                assert!(
                    option_field_name.is_none(),
                    "Checkbox SelectionInlineField '{}' should have option_field_name=None",
                    label_text
                );
            }
            if label_text.contains("Für alle Benutzer") || label_text.contains("Nur für Benutzer")
            {
                assert!(
                    option_field_name.is_some(),
                    "Radio SelectionInlineField '{}' should have option_field_name=Some(..)",
                    label_text
                );
            }
        }
    }
}

#[test]
