#[test]
fn test_aabk_checkboxes() {
    // Verify the two key checkboxes:
    // 1. Handelsregisterauszug — label: "Beigefügt und geprüft"
    // 2. Wurde der FIM besucht — label: "Ja, wann:"
    use crate::run_exhaustive_to_merged;
    use crate::structured::FieldType;

    let structured = run_exhaustive_to_merged(input_path("AABK_019_DE.pdf"))
        .expect("Failed to process AABK PDF");

    let fields = collect_fields(&structured);

    // Handelsregisterauszug checkbox
    let handelsregister = fields
        .iter()
        .find(|f| {
            matches!(f.input_type, FieldType::Bool)
                && f.som_path_str().contains("CB_Beigefugt_Und_Gepruft")
        })
        .expect("Expected to find Handelsregisterauszug checkbox (CB_Beigefugt_Und_Gepruft)");

    let label = handelsregister
        .label
        .as_ref()
        .map(|l| l.as_plain_text())
        .unwrap_or_default();
    assert!(
        label.contains("Beigefügt und geprüft"),
        "Handelsregisterauszug checkbox label should contain 'Beigefügt und geprüft', got: '{}'",
        label
    );

    // Wurde der FIM besucht checkbox
    let fim_besucht = fields
        .iter()
        .find(|f| {
            matches!(f.input_type, FieldType::Bool)
                && f.som_path_str().contains("CB_Ja_Wurde_Der_FIM")
        })
        .expect("Expected to find FIM besucht checkbox (CB_Ja_Wurde_Der_FIM)");

    let label = fim_besucht
        .label
        .as_ref()
        .map(|l| l.as_plain_text())
        .unwrap_or_default();
    assert!(
        label.contains("Ja, wann"),
        "FIM besucht checkbox label should contain 'Ja, wann', got: '{}'",
        label
    );
}

#[test]
fn test_aabk_conditional_fields() {
    // Verify conditional fields attached to radio buttons for the following labels:
    // - "Andere Lizenz (Nachweis beifügen)"
    // - "Ja, wann:" (from checkbox)
    // - "Ja (Falls "Ja": Es gelten Enhanced Due Diligence...)"
    // - "Ja: Angabe der Änderung"
    // - "Ja, welche:"
    // - "Ja, Beschreibung der Änderungen:"
    // - "Ja, Beschreibung:"
    // - "Ja, aber Konditionenanpassung erforderlich (Beschreibung und Frist):"
    // - "Nein, weiteres Vorgehen:"
    use crate::run_exhaustive_to_merged;
    use crate::structured::{FieldType, InputValue, StructuredNode};

    let structured = run_exhaustive_to_merged(input_path("AABK_019_DE.pdf"))
        .expect("Failed to process AABK PDF");

    let conditionals = collect_conditionals(&structured);
    let fields = collect_fields(&structured);

    // 1. "Andere Lizenz (Nachweis beifügen)" — from Lizenzüberprüfung radio
    let lizenz_radio = fields
        .iter()
        .find(|f| f.som_path_str().contains("RB_Group_Lizenzuberprufung"))
        .expect("Expected Lizenzüberprüfung radio field");
    let options = match &lizenz_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type for Lizenzüberprüfung"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Andere Lizenz")),
        "Expected 'Andere Lizenz (Nachweis beifügen)' option in Lizenzüberprüfung radio"
    );

    // 2. "Ja, wann:" — conditional Date field from checkbox CB_Ja_Wurde_Der_FIM
    assert!(
        conditionals.iter().any(|c| {
            c.condition.value == InputValue::Bool(true)
                && match c.content.as_ref() {
                    StructuredNode::Field(f) => {
                        f.label
                            .as_ref()
                            .map(|l| l.as_plain_text().contains("Ja, wann"))
                            .unwrap_or(false)
                            && matches!(f.input_type, FieldType::Date)
                    }
                    _ => false,
                }
        }),
        "Expected conditional Date field labeled 'Ja, wann:' gated on checkbox"
    );

    // 3. "Ja (Falls "Ja": Es gelten Enhanced Due Diligence...)" — from Klassifizierung radio
    let klassifizierung_radio = fields
        .iter()
        .find(|f| f.som_path_str().contains("RB_Group_Klassifizierung"))
        .expect("Expected Klassifizierung radio field");
    let options = match &klassifizierung_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type for Klassifizierung"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Enhanced Due Diligence")),
        "Expected option containing 'Enhanced Due Diligence' in Klassifizierung radio"
    );

    // 4. "Ja: Angabe der Änderung" — from Veranderungen_Hauptaktionare radio
    let hauptaktionare_radio = fields
        .iter()
        .find(|f| {
            f.som_path_str()
                .contains("RB_Group_Veranderungen_Hauptaktionare")
        })
        .expect("Expected Veranderungen_Hauptaktionare radio field");
    let options = match &hauptaktionare_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Angabe der Änderung")),
        "Expected option 'Ja: Angabe der Änderung' in Veranderungen_Hauptaktionare radio"
    );

    // 5. "Ja, welche:" — from Besonderheiten radio
    let besonderheiten_radio = fields
        .iter()
        .find(|f| f.som_path_str().contains("RB_Group_Besonderheiten"))
        .expect("Expected Besonderheiten radio field");
    let options = match &besonderheiten_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Ja, welche")),
        "Expected option 'Ja, welche:' in Besonderheiten radio"
    );

    // 6. "Ja, Beschreibung der Änderungen:" — from Geschaftsstrategie_Des_FIM radio
    let strategie_radio = fields
        .iter()
        .find(|f| {
            f.som_path_str()
                .contains("RB_Group_Geschaftsstrategie_Des_FIM")
        })
        .expect("Expected Geschaftsstrategie_Des_FIM radio field");
    let options = match &strategie_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Beschreibung der Änderungen")),
        "Expected option 'Ja, Beschreibung der Änderungen:' in Geschaftsstrategie radio"
    );

    // 7. "Ja, Beschreibung:" — from Interessenkonflikte radio
    let konflikte_radio = fields
        .iter()
        .find(|f| f.som_path_str().contains("RB_Group_Interessenkonflikte"))
        .expect("Expected Interessenkonflikte radio field");
    let options = match &konflikte_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type"),
    };
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Ja, Beschreibung")),
        "Expected option 'Ja, Beschreibung:' in Interessenkonflikte radio"
    );

    // 8. "Ja, aber Konditionenanpassung erforderlich (Beschreibung und Frist):"
    //    — from Geschaftsbeziehung_Fortgesetzt radio, conditional text field
    let fortgesetzt_radio = fields
        .iter()
        .find(|f| {
            f.som_path_str()
                .contains("RB_Group_Geschaftsbeziehung_Fortgesetzt")
        })
        .expect("Expected Geschaftsbeziehung_Fortgesetzt radio field");
    let options = match &fortgesetzt_radio.input_type {
        FieldType::Radio { options } => options,
        _ => panic!("Expected radio type"),
    };
    assert!(
        options.iter().any(|o| o
            .name
            .to_string()
            .contains("Konditionenanpassung erforderlich")),
        "Expected option containing 'Konditionenanpassung erforderlich'"
    );

    // Verify the conditional text field for "Ja, aber Konditionenanpassung..."
    // Derive the value from the radio option rather than hardcoding
    let ja_aber_value = &options
        .iter()
        .find(|o| o.name.to_string().contains("Konditionenanpassung"))
        .unwrap()
        .value;
    assert!(
        conditionals
            .iter()
            .any(|c| c.condition.field_name == fortgesetzt_radio.name
                && &c.condition.value == ja_aber_value),
        "Expected conditional content gated on Konditionenanpassung option"
    );

    // 9. "Nein, weiteres Vorgehen:" — from Geschaftsbeziehung_Fortgesetzt radio
    assert!(
        options
            .iter()
            .any(|o| o.name.to_string().contains("Nein, weiteres Vorgehen")),
        "Expected option 'Nein, weiteres Vorgehen:'"
    );

    // Verify the conditional text field for "Nein, weiteres Vorgehen:"
    let nein_value = &options
        .iter()
        .find(|o| o.name.to_string().contains("Nein, weiteres Vorgehen"))
        .unwrap()
        .value;
    assert!(
        conditionals
            .iter()
            .any(|c| c.condition.field_name == fortgesetzt_radio.name
                && &c.condition.value == nein_value),
        "Expected conditional content gated on 'Nein, weiteres Vorgehen'"
    );
}

/// Test AAIS_019 translation merge produces correct multilingual content.
///
/// Verifies:
/// 1. "Client Details" heading has correct translations in all 3 languages
/// 2. "Company" field has correct label in all 3 languages
/// 3. No German text contains Spanish content
/// 4. States are correctly merged based on "Formular adressat" and "Fall" dropdowns
#[test]
fn test_aais_019_translation_merge_content() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured;

    // Load all three language envelopes
    let de = run_exhaustive_to_envelope(input_path("AAIS_019_DE.pdf"), "de")
        .expect("Failed to process AAIS_019_DE");
    let en = run_exhaustive_to_envelope(input_path("AAIS_019_EN.pdf"), "en")
        .expect("Failed to process AAIS_019_EN");
    let sp = run_exhaustive_to_envelope(input_path("AAIS_019_SP.pdf"), "es")
        .expect("Failed to process AAIS_019_SP");

    // All three should produce the same number of states (9)
    assert_eq!(de.state_count, 9, "DE should have 9 states");
    assert_eq!(en.state_count, 9, "EN should have 9 states");
    assert_eq!(sp.state_count, 9, "SP should have 9 states");

    // Merge all three languages
    let merged =
        structured::merge_translations(vec![de, en, sp], None).expect("Merge should succeed");

    // === 1. "Client Details" heading should have correct translations ===
    let mut client_details_found = false;
    helpers::walk_structured_nodes(&merged.content, &mut |node| {
        if let structured::StructuredNode::Heading(h) = node {
            if h.level.as_u8() == 2 {
                let en_text = h.content.plain_text_in("en");
                if en_text.trim().eq_ignore_ascii_case("Client details") {
                    client_details_found = true;
                    let de_text = h.content.plain_text_in("de");
                    let es_text = h.content.plain_text_in("es");
                    assert_eq!(
                        de_text.trim(),
                        "Kundendaten",
                        "Client Details heading DE should be 'Kundendaten', got '{}'",
                        de_text
                    );
                    assert_eq!(
                        es_text.trim(),
                        "Datos del cliente",
                        "Client Details heading ES should be 'Datos del cliente', got '{}'",
                        es_text
                    );
                }
            }
        }
    });
    assert!(
        client_details_found,
        "Should find at least one 'Client Details' heading"
    );

    // === 2. "Company" field should have correct label in all languages ===
    let mut company_field_count = 0;
    helpers::walk_structured_nodes(&merged.content, &mut |node| {
        if let structured::StructuredNode::Field(f) = node {
            if f.som_path_str().contains("Company.Company") {
                company_field_count += 1;
                let label = f.label.as_ref().expect("Company field should have a label");
                let de_text = label.plain_text_in("de");
                let en_text = label.plain_text_in("en");
                let es_text = label.plain_text_in("es");
                assert_eq!(
                    de_text.trim(),
                    "Firma",
                    "Company field DE label should be 'Firma'"
                );
                assert_eq!(
                    en_text.trim(),
                    "Company",
                    "Company field EN label should be 'Company'"
                );
                assert_eq!(
                    es_text.trim(),
                    "Razón social",
                    "Company field ES label should be 'Razón social'"
                );
            }
        }
    });
    assert!(
        company_field_count > 0,
        "Should find at least one Company field"
    );

    // === 3. No German text should contain Spanish content ===
    let spanish_words = [
        "Datos del cliente",
        "Razón social",
        "Formulario destinatario",
    ];
    helpers::walk_structured_nodes(&merged.content, &mut |node| {
        let de_text = match node {
            structured::StructuredNode::Heading(h) => h.content.plain_text_in("de"),
            structured::StructuredNode::Field(f) => f
                .label
                .as_ref()
                .map_or(String::new(), |l| l.plain_text_in("de")),
            _ => return,
        };
        for phrase in &spanish_words {
            assert!(
                !de_text.contains(phrase),
                "German text should not contain Spanish phrase '{}', found in: '{}'",
                phrase,
                de_text
            );
        }
    });

    // === 4. States based on "Formular adressat" (CL_ClientType) and "Fall" ===
    // The merged output should have conditionals for both dropdowns.
    let conditionals = collect_conditionals(&merged.content);

    // CL_ClientType conditions (bbe42e19-...)
    let client_type_conditions: Vec<_> = conditionals
        .iter()
        .filter(|c| c.condition.field_name.to_string().contains("bbe42e19"))
        .collect();
    let client_type_values: Vec<String> = client_type_conditions
        .iter()
        .map(|c| match &c.condition.value {
            structured::InputValue::Text(v) => v.clone(),
            other => format!("{:?}", other),
        })
        .collect();
    assert!(
        client_type_values.contains(&"Firma".to_string()),
        "Should have 'Firma' condition, got: {:?}",
        client_type_values
    );
    assert!(
        client_type_values.contains(&"Private Person".to_string()),
        "Should have 'Private Person' condition, got: {:?}",
        client_type_values
    );
    assert!(
        client_type_values.contains(&"GbR".to_string()),
        "Should have 'GbR' condition, got: {:?}",
        client_type_values
    );
    assert!(
        client_type_values.contains(&"Minderjährige".to_string()),
        "Should have 'Minderjährige' condition, got: {:?}",
        client_type_values
    );

    // Fall conditions (16c1f4fd-...)
    let fall_conditions: Vec<_> = conditionals
        .iter()
        .filter(|c| c.condition.field_name.to_string().contains("16c1f4fd"))
        .collect();
    let fall_values: Vec<String> = fall_conditions
        .iter()
        .map(|c| match &c.condition.value {
            structured::InputValue::Text(v) => v.clone(),
            other => format!("{:?}", other),
        })
        .collect();
    assert!(
        fall_values.contains(
            &"Normalfall (Kunde akzeptiert Einbehalt der Vertriebsprovisionen)".to_string()
        ),
        "Should have 'Normalfall' condition, got: {:?}",
        fall_values
    );
    assert!(
        fall_values
            .contains(&"Komplette Auskehrung von Vertriebsprovisionen an Kunden".to_string()),
        "Should have 'Komplette Auskehrung' condition, got: {:?}",
        fall_values
    );
    assert!(
        fall_values
            .contains(&"Teilweise Auskehrung von Vertriebsprovisionen an Kunden".to_string()),
        "Should have 'Teilweise Auskehrung' condition, got: {:?}",
        fall_values
    );

    // Each CL_ClientType condition should NOT contain Fall sub-conditions
    // after hoisting: since Fall conditionals are identical across all
    // CL_ClientType siblings, they get hoisted to the same level.
    for ct_cond in &client_type_conditions {
        let inner_conditionals =
            collect_conditionals(std::slice::from_ref(ct_cond.content.as_ref()));
        let inner_fall: Vec<_> = inner_conditionals
            .iter()
            .filter(|c| c.condition.field_name.to_string().contains("16c1f4fd"))
            .collect();
        assert_eq!(
            inner_fall.len(),
            0,
            "CL_ClientType condition '{}' should have 0 Fall sub-conditions after hoisting, got {}",
            match &ct_cond.condition.value {
                structured::InputValue::Text(v) => v.as_str(),
                _ => "?",
            },
            inner_fall.len()
        );
    }
}

/// Test that the "Company" field is recognized with a label in each language
/// variant of AAIS_019 *before* translation merging.
///
/// Regression test for a bug where `apply_presence_by_name` would set ALL
/// nodes named "Company" to hidden — including the Company *field* inside the
/// Company *subform* — when an init script changed only the subform's presence.
#[test]
fn test_aais_019_company_field_recognized_per_language() {
    use crate::run_exhaustive_to_envelope;

    for (file, lang, expected_label) in [
        ("AAIS_019_DE.pdf", "de", "Firma"),
        ("AAIS_019_EN.pdf", "en", "Company"),
        ("AAIS_019_SP.pdf", "es", "Razón social"),
    ] {
        let envelope = run_exhaustive_to_envelope(input_path(file), lang)
            .unwrap_or_else(|e| panic!("Failed to process {file}: {e}"));

        let all_fields = collect_fields(&envelope.content);

        // Find all Company fields
        let company_fields: Vec<_> = all_fields
            .into_iter()
            .filter(|f| f.som_path_str().contains("Company.Company"))
            .collect();

        assert!(
            !company_fields.is_empty(),
            "{file} ({lang}): should have at least one Company.Company field"
        );

        for field in &company_fields {
            let label = field
                .label
                .as_ref()
                .unwrap_or_else(|| {
                    panic!(
                        "{file} ({lang}): Company field should have a label, but has none. \
                         The label text '{expected_label}' is likely a standalone Paragraph instead.",
                    )
                });
            let label_text = label.as_plain_text();
            assert_eq!(
                label_text.trim(),
                expected_label,
                "{file} ({lang}): Company field label should be '{expected_label}'"
            );
        }
    }
}

/// Test that the AAIS_019 fee list is recognized as a single unordered list
/// with 10 items and that all three translations (EN, DE, ES) are correct.
#[test]
fn test_aais_019_fee_list_recognized_and_translated() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured;

    // Load all three language envelopes
    let de = run_exhaustive_to_envelope(input_path("AAIS_019_DE.pdf"), "de")
        .expect("Failed to process AAIS_019_DE");
    let en = run_exhaustive_to_envelope(input_path("AAIS_019_EN.pdf"), "en")
        .expect("Failed to process AAIS_019_EN");
    let sp = run_exhaustive_to_envelope(input_path("AAIS_019_SP.pdf"), "es")
        .expect("Failed to process AAIS_019_SP");

    // Merge all three languages
    let merged = structured::merge_translations(vec![de, en, sp], None)
        .expect("AAIS_019 three-language merge should succeed");

    // Collect all lists from the merged output
    let lists = helpers::collect_lists(&merged.content);

    let expected_en = [
        "One-time placement fee of up to 2.50%,",
        "One-time placement fee from the underlying fund manager of up to 2.0%,",
        "Annual additional commitment fee of up to 0.50% p.a.,",
        "Annual management fee of up to 0.60% p.a.,",
        "Annual administration fee or servicing fee of up to 0.06% p.a.,",
        "Annual Depository Fee of up to 0.02% p.a. based on the Net Asset Value (NAV),",
        "Annual Alternative Investment Fund Manager Fee of up to 0.02% p.a. based on the NAV,",
        "Annual Advisory Fee of up to 1.05% p.a.,",
        "Management Revenues, which can be paid by the management of the target investment in an individual amount specified in the respective product documentation,",
        "performance fee in an individual percentage amount shown in the respective product documentation",
    ];

    let expected_es = [
        "comisión de colocación única de hasta un 2,50%,",
        "comisión de colocación única del gestor subyacente del fondo de hasta un 2,0%,",
        "comisión de compromiso adicional anual de hasta un 0,5% anual,",
        "comisión de gestión anual de hasta un 0,6% anual,",
        "comisión de administración anual o comisión de servicio de hasta un 0,06% anual,",
        "comisión de custodia anual de hasta un 0,02% anual en relación con el valor neto de los activos,",
        "comisión de gestor de fondo de inversiones alternativas de hasta un 0,02% anual en relación con el valor neto de los activos,",
        "comisión de asesoramiento anual de hasta el 1,05% anual,",
        "Rentas de gestión, las cuales se pueden abonar por la gestión de la inversión objetivo en el importe individual especificado en la documentación del producto correspondiente,",
        "Comisión de rentabilidad en un importe porcentual particular que figura en la documentación del producto correspondiente.",
    ];

    let expected_de = [
        "Einmalige Placement Fee in Höhe von bis zu 2,50%,",
        "Einmalige Placement Fee vom zugrundeliegenden Fondsverwalter (Underlying Manager) in Höhe bis zu 2,0%,",
        "Jährliche zusätzliche Additional Commitment Fee von bis zu 0,50% p.a.,",
        "Jährliche Management Fee von bis zu 0,60% p.a.,",
        "Jährliche Administrations Fee oder Servicing Fee von bis zu 0,06% p.a.,",
        "Jährliche Depository Fee von bis zu 0,02% p.a. bezogen auf den Nettoinventarwert (NAV),",
        "Jährliche Alternative Investment Fund Manager-Fee von bis zu 0,02% p.a. bezogen auf den NAV,",
        "Jährliche Advisory Fee von bis zu 1,05% p.a.,",
        "Management Revenues, die in individueller in der jeweiligen Produktdokumentation aufgezeigten Höhe seitens des Managements des Zielinvestments gezahlt werden können,",
        "Erfolgsabhängige Performance Fee in individueller prozentualer in der jeweiligen Produktdokumentation aufgezeigten Höhe.",
    ];

    // Find the fee list: an unordered list with 10 items
    let fee_list = lists
        .iter()
        .find(|l| !l.list_style.is_ordered() && l.items.len() == 10)
        .unwrap_or_else(|| {
            // Print diagnostic info about all lists found
            for (i, l) in lists.iter().enumerate() {
                eprintln!(
                    "List {}: style={:?}, items={}",
                    i,
                    l.list_style,
                    l.items.len()
                );
                for (j, item) in l.items.iter().enumerate() {
                    eprintln!("  [{j}] EN: {}", item.plain_text_in("en"));
                    eprintln!("      DE: {}", item.plain_text_in("de"));
                    eprintln!("      ES: {}", item.plain_text_in("es"));
                }
            }
            panic!(
                "AAIS_019 should have an unordered list with 10 fee items, found lists: {:?}",
                lists
                    .iter()
                    .map(|l| (l.list_style, l.items.len()))
                    .collect::<Vec<_>>()
            );
        });

    // Verify English items
    for (i, expected) in expected_en.iter().enumerate() {
        let text = fee_list.items[i].plain_text_in("en");
        assert_eq!(text.trim(), *expected, "EN fee list item {} mismatch", i);
    }

    // Verify Spanish items
    for (i, expected) in expected_es.iter().enumerate() {
        let text = fee_list.items[i].plain_text_in("es");
        assert_eq!(text.trim(), *expected, "ES fee list item {} mismatch", i);
    }

    // Verify German items
    for (i, expected) in expected_de.iter().enumerate() {
        let text = fee_list.items[i].plain_text_in("de");
        assert_eq!(text.trim(), *expected, "DE fee list item {} mismatch", i);
    }
}

/// Test that hyphenation produces correct paragraph heights for the AAIS_019_DE fee section.
/// The T_Left draw element in STP_CloseFund contains a paragraph starting with
/// "Für die Vermittlung von Investitionen" that requires hyphenation of long German
/// compound words (e.g. "Unternehmensinvestitionen") to fit within the available width.
/// Without hyphenation, long words overflow and lines wrap incorrectly, producing
/// taller paragraphs. With hyphenation, the text fits into the expected number of lines.
#[test]
fn test_aais_019_hyphenation_paragraph_height() {
    use crate::flattened::FlattenedNodeKind;
    use crate::xfa::num;

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Find the node whose text contains "Für die Vermittlung"
    let vermittlung_node = flattened
        .iter_nodes()
        .find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("Für die Vermittlung")
            } else {
                false
            }
        })
        .expect("Should find a node containing 'Für die Vermittlung'");

    // This paragraph should be 6 lines at 9pt line height = 54pt.
    // Without hyphenation, "Unternehmensinvestitionen" and other long compound words
    // don't break, causing extra line wraps and a taller paragraph (~63pt = 7 lines).
    let expected_height = num(54.0);
    let tolerance = num(1.0); // Allow small rounding tolerance

    assert!(
        (vermittlung_node.height - expected_height).abs() <= tolerance,
        "Paragraph with 'Für die Vermittlung' should be ~54pt (6 lines × 9pt) with hyphenation, \
         but got {}pt. This suggests hyphenation is not breaking long German compound words correctly.",
        vermittlung_node.height,
    );
}

#[test]
fn test_aais_019_fee_table_pairs_are_side_by_side_in_flattened() {
    use crate::flattened::{FlattenedNode, FlattenedNodeKind};

    fn has_visible_bottom_border(node: &FlattenedNode) -> bool {
        node.style
            .border
            .as_ref()
            .and_then(|b| b.get_edge(2))
            .map(|e| e.presence == "visible" && e.thickness.is_some())
            .unwrap_or(false)
    }

    fn find_text_node<'a>(
        nodes: impl Iterator<Item = &'a FlattenedNode>,
        needles: &[&str],
    ) -> &'a FlattenedNode {
        nodes
            .filter(|n| matches!(n.kind, FlattenedNodeKind::Text { .. }))
            .find(|n| {
                if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                    needles.iter().all(|needle| content.contains(needle))
                } else {
                    false
                }
            })
            .unwrap_or_else(|| panic!("missing text node containing {:?}", needles))
    }

    fn find_all_text_nodes<'a>(
        nodes: impl Iterator<Item = &'a FlattenedNode>,
        needles: &[&str],
    ) -> Vec<&'a FlattenedNode> {
        nodes
            .filter(|n| matches!(n.kind, FlattenedNodeKind::Text { .. }))
            .filter(|n| {
                if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                    needles.iter().all(|needle| content.contains(needle))
                } else {
                    false
                }
            })
            .collect()
    }

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_EN.pdf")).expect("load AAIS_019_EN");
    let states = bp.states().expect("compute states");
    let flattened = &states
        .iter()
        .next()
        .expect("default state must exist")
        .flattened;

    let n1_left = find_text_node(flattened.iter_nodes(), &["For money market funds"]);
    let n1_right = find_text_node(flattened.iter_nodes(), &["up to max. 1.0% p.a."]);
    let n2_left = find_text_node(flattened.iter_nodes(), &["For open-end real estate funds"]);
    let n2_right = find_text_node(flattened.iter_nodes(), &["up to 2.0% p.a. (in addition"]);
    let n3_left = find_text_node(
        flattened.iter_nodes(),
        &[
            "For hedge funds, which qualify as",
            "KAGB (hedge fund AIF):",
        ],
    );
    let n3_right = find_text_node(flattened.iter_nodes(), &["up to 2,2% p.a. (in addition"]);

    // Continuation chunk that must stay in the right column for both affected rows.
    let continuation_nodes = find_all_text_nodes(
        flattened.iter_nodes(),
        &["company of up to max. 2.0% of the full subscription amount"],
    );
    assert!(
        continuation_nodes.len() >= 2,
        "Expected at least two continuation nodes in AAIS fee table right column"
    );

    for (left, right, label) in [
        (n1_left, n1_right, "money market row"),
        (n2_left, n2_right, "open-end real estate row"),
        (n3_left, n3_right, "hedge fund AIF row"),
    ] {
        let dy = (left.y - right.y).abs();
        assert!(
            dy <= crate::xfa::num(2.0),
            "{} should be side-by-side (same row): left.y={} right.y={} dy={}",
            label,
            left.y,
            right.y,
            dy
        );
        assert!(
            left.x < right.x,
            "{} should have left cell before right cell: left.x={} right.x={}",
            label,
            left.x,
            right.x
        );

        if label != "money market row" {
            let continuation = continuation_nodes
                .iter()
                .copied()
                .filter(|n| n.y >= right.y)
                .min_by(|a, b| {
                    let da = (a.y - right.y).abs();
                    let db = (b.y - right.y).abs();
                    da.cmp(&db)
                })
                .expect("continuation node should exist near right-column paragraph");

            assert!(
                continuation.x >= right.x - crate::xfa::num(2.0),
                "{} continuation chunk must remain in right column: continuation.x={} right.x={}",
                label,
                continuation.x,
                right.x
            );
            assert!(
                continuation.x > left.x + left.width / crate::xfa::num(2.0),
                "{} continuation chunk should not drift into left column: continuation.x={} left.x={} left.w={}",
                label,
                continuation.x,
                left.x,
                left.width
            );
        }

        assert!(
            has_visible_bottom_border(left) || has_visible_bottom_border(right),
            "{} should keep a visible row separator (bottom border on at least one cell)",
            label
        );
    }
}

#[test]
fn test_aais_019_de_real_estate_aif_continuation_stays_in_right_column() {
    use crate::flattened::FlattenedNodeKind;

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_DE.pdf")).expect("load AAIS_019_DE");
    let states = bp.states().expect("compute states");
    let flattened = &states
        .iter()
        .next()
        .expect("default state must exist")
        .flattened;

    let left = flattened
        .iter_nodes()
        .find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("Bei offenen Immobilienfonds")
                    && content.contains("Immobilien-AIF")
            } else {
                false
            }
        })
        .expect("left real-estate AIF row text node");

    let right_start = flattened
        .iter_nodes()
        .find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("bis max. 2,0% p.a.")
            } else {
                false
            }
        })
        .expect("right real-estate AIF row start node");

    let right_continuation = flattened
        .iter_nodes()
        .find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("zugrundeliegenden Verwaltungsgesellschaft")
            } else {
                false
            }
        })
        .expect("right real-estate AIF continuation node");

    assert!(
        (left.y - right_start.y).abs() <= crate::xfa::num(2.0),
        "DE real-estate AIF row start must stay side-by-side: left.y={} right_start.y={}",
        left.y,
        right_start.y
    );
    assert!(
        right_start.x > left.x + left.width / crate::xfa::num(2.0),
        "DE row-start node must be in right column: left=(x={},w={}) right_start.x={}",
        left.x,
        left.width,
        right_start.x
    );
    // Some templates keep the continuation phrase in the same text node as the row start.
    // When split into a separate node, it must be rendered on a following line.
    if !std::ptr::eq(right_continuation, right_start) {
        assert!(
            right_continuation.y > left.y + crate::xfa::num(2.0),
            "DE continuation split node must be rendered on a following line: left.y={} continuation.y={}",
            left.y,
            right_continuation.y
        );
    }
    assert!(
        right_continuation.x >= right_start.x - crate::xfa::num(2.0),
        "DE continuation must remain anchored to right column: right_start.x={} continuation.x={}",
        right_start.x,
        right_continuation.x
    );
    assert!(
        right_continuation.x > left.x + left.width / crate::xfa::num(2.0),
        "DE continuation node must stay in right column: left=(x={},w={}) continuation.x={}",
        left.x,
        left.width,
        right_continuation.x
    );
}

