/// Test that dash markers (–) in T_LeftIndent align vertically with the corresponding
/// fee description items in T_Left for the AAIS_019_DE fee list.
/// This test verifies that hyphenation improves alignment between the two overlapping
/// draw elements by ensuring paragraph heights are computed correctly.
#[test]
fn test_aais_019_dash_markers_alignment() {
    use crate::flattened::FlattenedNodeKind;
    use crate::xfa::num;

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Find all fee description nodes (contain fee-related text)
    let fee_keywords = [
        "Placement Fee",
        "Commitment Fee",
        "Administrations Fee",
        "Depository Fee",
        "Performance Fee",
        "Fund Manager-Fee",
        "Management Revenues",
    ];

    let fee_descriptions: Vec<_> = flattened
        .iter_nodes()
        .filter(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                fee_keywords.iter().any(|kw| content.contains(kw))
            } else {
                false
            }
        })
        .collect();

    // Find dash marker nodes: short text with just "–" (en-dash)
    let dash_nodes: Vec<_> = flattened
        .iter_nodes()
        .filter(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                let trimmed = content.trim();
                trimmed == "–" || trimmed == "-" || trimmed == "—"
            } else {
                false
            }
        })
        .collect();

    // We expect some fee descriptions and some dash markers
    assert!(
        !fee_descriptions.is_empty(),
        "Expected fee description nodes in AAIS_019_DE"
    );

    assert!(
        !dash_nodes.is_empty(),
        "Expected dash marker nodes in AAIS_019_DE, found none"
    );

    assert!(
        fee_descriptions.len() >= 8,
        "Expected at least 8 fee descriptions, found {}",
        fee_descriptions.len()
    );

    assert_eq!(dash_nodes.len(), 10, "Expected exactly 10 dash markers");

    // Verify at least one fee item is close to the first dash marker.
    // Use nearest-neighbor matching instead of absolute y-thresholds so the
    // test remains robust when upstream layout improvements shift sections.
    let first_dash_y = dash_nodes[0].y;
    let first_fee_y = fee_descriptions
        .iter()
        .map(|n| n.y)
        .min_by_key(|y| (*y - first_dash_y).abs())
        .expect("at least one fee description")
        .to_owned();
    let offset = (first_dash_y - first_fee_y).abs();
    assert!(
        offset < num(90.0),
        "First dash marker y ({}) should be within 90pt of first fee item y ({}), offset={}",
        first_dash_y,
        first_fee_y,
        offset,
    );
}

/// Test that list markers ("1.", "a.") in T_LeftIndent align vertically with
/// their corresponding headings ("Open-end products", "Open-end investment funds")
/// in T_Left for the AAIS_019_EN form.
///
/// The XFA form uses two overlapping draw elements positioned at the same (x=0, y=0):
/// - T_Left: rich text with paragraphs, some with CSS margin-left:25.512pt
/// - T_LeftIndent: plain text "I.          1.    a.      " with U+2029 paragraph
///   separators creating aligned markers
///
/// Per XFA spec: both draws have lineHeight="9pt", so paragraph heights must match
/// for list markers to align with their headings.
#[test]
fn test_aais_019_en_list_marker_paragraph_alignment() {
    use crate::flattened::FlattenedNodeKind;
    use rust_decimal::Decimal;
    use std::str::FromStr;

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_EN.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Collect all T_Left paragraphs with their y-positions and content
    let t_left_paragraphs: Vec<(String, Decimal)> = flattened
        .iter_nodes()
        .filter_map(|n| {
            if let FlattenedNodeKind::Text {
                source_name,
                content,
                ..
            } = &n.kind
            {
                if source_name.as_ref().map(|s| s == "T_Left").unwrap_or(false) {
                    let trimmed = content.trim();
                    if !trimmed.is_empty() {
                        return Some((trimmed.to_string(), n.y));
                    }
                }
            }
            None
        })
        .collect();

    // Collect all T_LeftIndent paragraphs with their y-positions and content
    let t_left_indent_paragraphs: Vec<(String, Decimal)> = flattened
        .iter_nodes()
        .filter_map(|n| {
            if let FlattenedNodeKind::Text {
                source_name,
                content,
                ..
            } = &n.kind
            {
                if source_name
                    .as_ref()
                    .map(|s| s == "T_LeftIndent")
                    .unwrap_or(false)
                {
                    let trimmed = content.trim();
                    if !trimmed.is_empty() {
                        return Some((trimmed.to_string(), n.y));
                    }
                }
            }
            None
        })
        .collect();

    println!("\n=== T_Left paragraphs ===");
    for (text, y) in &t_left_paragraphs {
        let preview: String = text.chars().take(60).collect();
        println!("  y={:.3}: '{}'", y, preview);
    }

    println!("\n=== T_LeftIndent paragraphs ===");
    for (text, y) in &t_left_indent_paragraphs {
        println!("  y={:.3}: '{}'", y, text);
    }

    // Find "1." marker and "Open-end products" heading
    let marker_1 = t_left_indent_paragraphs
        .iter()
        .find(|(text, _)| text == "1.")
        .expect("T_LeftIndent should have a paragraph with '1.'");

    let open_end_products = t_left_paragraphs
        .iter()
        .find(|(text, _)| text == "Open-end products")
        .expect("T_Left should have a paragraph with 'Open-end products'");

    // Find "a." marker and "Open-end investment funds" heading
    let marker_a = t_left_indent_paragraphs
        .iter()
        .find(|(text, _)| text == "a.")
        .expect("T_LeftIndent should have a paragraph with 'a.'");

    let open_end_funds = t_left_paragraphs
        .iter()
        .find(|(text, _)| text == "Open-end investment funds")
        .expect("T_Left should have a paragraph with 'Open-end investment funds'");

    // Verify alignments (within 0.1pt tolerance for rounding)
    let tolerance = Decimal::from_str("0.1").unwrap();

    let diff_1 = (marker_1.1 - open_end_products.1).abs();
    assert!(
        diff_1 < tolerance,
        "'1.' (y={:.3}) should be aligned with 'Open-end products' (y={:.3}), diff={:.3}pt. \
         This means the list marker '1.' should appear on the SAME LINE as 'Open-end products', not above or below.",
        marker_1.1,
        open_end_products.1,
        diff_1
    );
    println!(
        "ok '1.' aligned with 'Open-end products' at y={:.3}",
        marker_1.1
    );

    let diff_a = (marker_a.1 - open_end_funds.1).abs();
    assert!(
        diff_a < tolerance,
        "'a.' (y={:.3}) should be aligned with 'Open-end investment funds' (y={:.3}), diff={:.3}pt. \
         This means the list marker 'a.' should appear on the SAME LINE as 'Open-end investment funds', not above or below.",
        marker_a.1,
        open_end_funds.1,
        diff_a
    );
    println!(
        "ok 'a.' aligned with 'Open-end investment funds' at y={:.3}",
        marker_a.1
    );

    println!("\nok All AAIS list markers properly aligned!");
}

/// Diagnostic test – dump AAIS_019_EN text blocks to understand merger behaviour
#[test]
fn test_aais_019_en_text_block_merger_paragraph_separation() {
    use crate::document::Document;
    use crate::document::modules::AnalysisModule;
    use crate::document::modules::{
        CheckboxContentDetector, CheckboxDetector, DateFieldDetector, FieldGrouper,
        InlineFieldDatePicker, ListDetector, MasterPageDetector, NoPrintDetector,
        PlaceholderFilter, RadioButtonContentDetector, RadioButtonDetector, RadioButtonGrouper,
        SelectionInlineFieldDetector, StandaloneMarkerMerger, TextBlockGrouper, TextBlockMerger,
    };

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_EN.pdf")).unwrap();
    let states = bp.states().unwrap();
    let first_state = states.iter().next().unwrap();
    let flattened = &first_state.flattened;

    // Run pipeline up to (but NOT including) TextBlockMerger
    let mut doc = Document::from_flattened(flattened);
    NoPrintDetector::new().process(&mut doc);
    MasterPageDetector::new().process(&mut doc);
    TextBlockGrouper::new().process(&mut doc);
    PlaceholderFilter::new().process(&mut doc);
    FieldGrouper::new().process(&mut doc);
    DateFieldDetector::new().process(&mut doc);
    InlineFieldDatePicker::new().process(&mut doc);
    StandaloneMarkerMerger::new().process(&mut doc);
    RadioButtonDetector::new().process(&mut doc);
    CheckboxDetector::new().process(&mut doc);
    ListDetector::new().process(&mut doc);
    RadioButtonGrouper::new().process(&mut doc);
    SelectionInlineFieldDetector::new().process(&mut doc);
    RadioButtonContentDetector::new().process(&mut doc);
    CheckboxContentDetector::new().process(&mut doc);

    // Snapshot text blocks BEFORE the TextBlockMerger
    let pre_merge_tbs = doc.root_text_blocks();
    let search_terms = [
        "management fee it charges to investors",
        "retrocession",
        "portfolio commissions",
        "brokering investments",
        "sales compensation",
        "amounts to up to 5%",
        "Structured products",
        "Closed-end products",
        "inside fee",
        "one-off fee",
    ];

    eprintln!(
        "\n=== BEFORE TextBlockMerger ({} root text blocks) ===",
        pre_merge_tbs.len()
    );
    let mut pre_relevant: Vec<(usize, String)> = Vec::new();
    for &idx in &pre_merge_tbs {
        let text = doc.get_text_content(idx);
        if search_terms.iter().any(|t| text.contains(t)) {
            let bounds = doc.get_bounds(idx);
            eprintln!("  TB idx={idx} bounds={bounds:?}");
            eprintln!("    text: \"{}\"", &text[..text.len().min(120)]);
            pre_relevant.push((idx, text));
        }
    }

    // Now run TextBlockMerger
    TextBlockMerger::new().process(&mut doc);

    let post_merge_tbs = doc.root_text_blocks();
    eprintln!(
        "\n=== AFTER TextBlockMerger ({} root text blocks) ===",
        post_merge_tbs.len()
    );
    for &idx in &post_merge_tbs {
        let text = doc.get_text_content(idx);
        if search_terms.iter().any(|t| text.contains(t)) {
            let bounds = doc.get_bounds(idx);
            eprintln!("  TB idx={idx} bounds={bounds:?}");
            eprintln!("    text: \"{}\"", &text[..text.len().min(120)]);
        }
    }

    // These phrases should each be in SEPARATE text blocks (separate paragraphs):
    let separate_paragraphs = [
        "management fee it charges to investors",
        "The amount of the retroce",
        "Furthermore, recurring portfolio commissions",
        "brokering investments",
        "Details of the sales compensation",
    ];

    // Find which text block each phrase is in
    let mut block_for_phrase: Vec<Option<usize>> = vec![None; separate_paragraphs.len()];
    for &idx in &post_merge_tbs {
        let text = doc.get_text_content(idx);
        for (i, phrase) in separate_paragraphs.iter().enumerate() {
            if text.contains(phrase) {
                block_for_phrase[i] = Some(idx);
            }
        }
    }

    // All phrases must be found
    for (i, phrase) in separate_paragraphs.iter().enumerate() {
        assert!(
            block_for_phrase[i].is_some(),
            "Phrase not found in any text block: \"{phrase}\""
        );
    }

    // Each phrase should be in a DIFFERENT text block (separate paragraphs)
    for i in 0..separate_paragraphs.len() {
        for j in (i + 1)..separate_paragraphs.len() {
            assert_ne!(
                block_for_phrase[i], block_for_phrase[j],
                "Phrases should be in separate paragraphs but are merged into the same text block:\n  \
                 [{i}] \"{}\"\n  [{j}] \"{}\"",
                separate_paragraphs[i], separate_paragraphs[j],
            );
        }
    }
}

