/// Diagnostic: check container height vs estimated content height for text blocks.
#[test]
fn debug_aais_container_vs_content_height() {
    use crate::document::Document;
    use crate::document::modules::AnalysisModule;
    use crate::document::modules::{
        CheckboxContentDetector, CheckboxDetector, DateFieldDetector, FieldGrouper,
        InlineFieldDatePicker, ListDetector, MasterPageDetector, NoPrintDetector,
        PlaceholderFilter, RadioButtonContentDetector, RadioButtonDetector, RadioButtonGrouper,
        SelectionInlineFieldDetector, StandaloneMarkerMerger, TextBlockGrouper,
    };
    use crate::flattened::FlattenedNodeKind;

    // Check AAIS
    for (label, filename, search) in [
        (
            "AAIS_019_EN",
            "AAIS_019_EN.pdf",
            vec![
                "Structured products",
                "portfolio commissions",
                "brokering investments",
                "amounts to up to 5%",
                "inside fee",
                "one-off fee",
                "management fee it charges",
                "retrocession",
                "sales compensation",
                "Closed-end products",
            ],
        ),
        (
            "AACJ_019_DE",
            "AACJ_019_DE.pdf",
            vec![
                "Aufgrund",
                "Bitte füllen",
                "Einzelkontoinhaber",
                "Ich bestätige",
                "steuerpflichtig",
                "vorstehend",
            ],
        ),
        (
            "AACJ_019_EN",
            "AACJ_019_EN.pdf",
            vec![
                "Common Reporting",
                "Please fill",
                "individual account",
                "I confirm",
                "tax resident",
                "indicated above",
            ],
        ),
    ] {
        let mut bp = Blueprint::from_pdf(input_path(filename)).unwrap();
        let states = bp.states().unwrap();
        let first_state = states.iter().next().unwrap();
        let flattened = &first_state.flattened;

        let mut doc = Document::from_flattened(flattened);
        NoPrintDetector::new().process(&mut doc);
        MasterPageDetector::new().process(&mut doc);
        TextBlockGrouper::new().process(&mut doc);
        PlaceholderFilter::new().process(&mut doc);
        FieldGrouper::new().process(&mut doc);
        DateFieldDetector::new().process(&mut doc);
        InlineFieldDatePicker::new().process(&mut doc);
        StandaloneMarkerMerger::new().process(&mut doc);
        RadioButtonDetector::new().process(&mut doc);
        CheckboxDetector::new().process(&mut doc);
        ListDetector::new().process(&mut doc);
        RadioButtonGrouper::new().process(&mut doc);
        SelectionInlineFieldDetector::new().process(&mut doc);
        RadioButtonContentDetector::new().process(&mut doc);
        CheckboxContentDetector::new().process(&mut doc);

        let root_tbs = doc.root_text_blocks();
        eprintln!("\n=== {label}: container vs content height ===");
        let mut prev_bottom: Option<rust_decimal::Decimal> = None;
        for &idx in &root_tbs {
            let text = doc.get_text_content(idx);
            if !search.iter().any(|s| text.contains(s)) {
                continue;
            }
            let bounds = doc.get_bounds(idx).unwrap();
            let nodes = doc.collect_nodes(idx);
            let gap = prev_bottom.map(|pb| bounds.y - pb);
            for node in &nodes {
                if let FlattenedNodeKind::Text {
                    font_size, content, ..
                } = &node.kind
                {
                    if content.trim().is_empty() {
                        continue;
                    }
                    let est_lines = (node.height / *font_size).to_f64().unwrap_or(0.0);
                    let content_h =
                        *font_size * rust_decimal::Decimal::from(est_lines.round() as u32);
                    let truncated: String = content.chars().take(55).collect();
                    eprintln!(
                        "  Node: y={:.1} h={} fs={} est_lines={:.1} content_h={} | \"{}\"",
                        node.y.to_f64().unwrap_or(0.0),
                        node.height,
                        font_size,
                        est_lines,
                        content_h,
                        truncated
                    );
                }
            }
            let truncated: String = text.chars().take(70).collect();
            eprintln!(
                "  GROUP idx={idx}: y={:.1} h={} gap_from_prev={:?} | \"{}\"\n",
                bounds.y.to_f64().unwrap_or(0.0),
                bounds.height,
                gap.map(|g| g.to_f64().unwrap_or(0.0)),
                truncated
            );
            prev_bottom = Some(bounds.bottom());
        }
    }
}

/// Diagnostic: dump TextBlock structure around "Bitte füllen Sie" / "Please fill" for all AACJ langs
#[test]
fn debug_aacj_snippets_structure() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::{self, StructuredNode};
    use helpers::walk_structured_nodes;

    let de_envelope = run_exhaustive_to_envelope(input_path("AACJ_019_DE.pdf"), "de")
        .expect("Failed to process AACJ_019_DE");
    let en_envelope = run_exhaustive_to_envelope(input_path("AACJ_019_EN.pdf"), "en")
        .expect("Failed to process AACJ_019_EN");
    let sp_envelope = run_exhaustive_to_envelope(input_path("AACJ_019_SP.pdf"), "sp")
        .expect("Failed to process AACJ_019_SP");

    // Dump ALL nodes in a window around "Aufgrund"/"Based on" for each language
    for (label, envelope) in [
        ("DE", &de_envelope),
        ("EN", &en_envelope),
        ("SP", &sp_envelope),
    ] {
        eprintln!("\n=== {label} structured nodes (around target text) ===");
        let mut idx = 0;
        let mut found_target_at: Option<usize> = None;
        walk_structured_nodes(&envelope.content, &mut |node| {
            let (kind, text) = match node {
                StructuredNode::Paragraph(p) => ("P", p.content.as_plain_text()),
                StructuredNode::Heading(h) => ("H", h.content.as_plain_text()),
                StructuredNode::Field(f) => {
                    let t = f
                        .label
                        .as_ref()
                        .map(|l| l.as_plain_text())
                        .unwrap_or_default();
                    ("F", t)
                }
                StructuredNode::Group(_) => ("G", String::new()),
                StructuredNode::Conditional(_) => ("C", String::new()),
                _ => ("?", String::new()),
            };
            if text.contains("Aufgrund")
                || text.contains("Based on the OECD")
                || text.contains("Conforme a la Norma")
            {
                found_target_at = Some(idx);
            }
            if let Some(target_idx) = found_target_at {
                if idx <= target_idx + 12 {
                    let trunc: String = text.chars().take(140).collect();
                    eprintln!("  {kind}[{idx}]: \"{}\"", trunc);
                }
            }
            idx += 1;
        });
    }

    // Now merge and show the merged tree around the snippets
    let merged =
        structured::merge_translations(vec![de_envelope, en_envelope, sp_envelope], None).unwrap();

    eprintln!("\n=== MERGED structured nodes (paragraphs 0-15) ===");
    let mut count = 0;
    walk_structured_nodes(&merged.content, &mut |node| {
        if count >= 15 {
            return;
        }
        match node {
            StructuredNode::Paragraph(p) => {
                let de_text = p.content.plain_text_in("de");
                let en_text = p.content.plain_text_in("en");
                let sp_text = p.content.plain_text_in("sp");
                let de_t: String = de_text.chars().take(120).collect();
                let en_t: String = en_text.chars().take(120).collect();
                let sp_t: String = sp_text.chars().take(120).collect();
                eprintln!("  P[{count}] DE: \"{}\"", de_t);
                eprintln!("         EN: \"{}\"", en_t);
                eprintln!("         SP: \"{}\"", sp_t);
                count += 1;
            }
            StructuredNode::Heading(h) => {
                let text = h.content.as_plain_text();
                let trunc: String = text.chars().take(80).collect();
                eprintln!("  H[{count}]: \"{}\"", trunc);
                count += 1;
            }
            _ => {}
        }
    });
}

/// Test AAIS_019 state-dependent visibility of commission-related text blocks
/// and the Company field based on form addressee.
///
/// Verifies for AAIS_019_EN (9 states = 3 Fall × 3 client-type groups):
///
/// **In all states:**
/// - "UBS Europe SE may receive benefits from investment fund providers…" is visible
/// - "UBS Europe SE may pay success fees to third parties who introduce clients…" is visible
///
/// **For Fall "Normalfall (Kunde akzeptiert Einbehalt der Vertriebsprovisionen)":**
/// - "Waiver of Right to receive Commission" is visible
/// - standalone "Auskehrung an Kunden setzt Approval gemäß Kompetenzordnung voraus" is NOT visible
/// - "UBS Europe SE will refund to you the full amount less expenses…" is NOT visible
/// - "UBS Europe SE will refund to you % of any sales commissions…" is NOT visible
///
/// **For Fall "Komplette Auskehrung von Vertriebsprovisionen an Kunden":**
/// - "UBS Europe SE will refund to you the full amount less expenses…" is visible
/// - standalone "Auskehrung an Kunden setzt Approval gemäß Kompetenzordnung voraus" is visible
/// - "Waiver of Right to receive Commission" is NOT visible
/// - "UBS Europe SE will refund to you % of any sales commissions…" is NOT visible
///
/// **For Fall "Teilweise Auskehrung von Vertriebsprovisionen an Kunden":**
/// - "UBS Europe SE will refund to you % of any sales commissions…" is visible
/// - standalone "Auskehrung an Kunden setzt Approval gemäß Kompetenzordnung voraus" is visible
/// - "Waiver of Right to receive Commission" is NOT visible
/// - "UBS Europe SE will refund to you the full amount less expenses…" is NOT visible
///
/// **Company field visibility based on form addressee:**
/// - Visible for Firma / GbR
/// - Not visible for Minderjährige / Private Person
#[test]
fn test_aais_019_state_commission_visibility() {
    use crate::flattened::FlattenedNodeKind;

    // ── text fragment constants ───────────────────────────────────────────────
    const BENEFITS_TEXT: &str = "UBS Europe SE may receive benefits from investment fund providers and issuers of structured products";
    const SUCCESS_FEES_TEXT: &str =
        "UBS Europe SE may pay success fees to third parties who introduce clients";
    const WAIVER_TEXT: &str = "Waiver of Right to receive Commission";
    // The form header also starts with this phrase but continues with "Dieses Dokument …";
    // the "standalone" version used in Modes-of-payment section does NOT contain that continuation.
    const AUSKEHRUNG_TEXT: &str =
        "Auskehrung an Kunden setzt Approval gemäß Kompetenzordnung voraus";
    const AUSKEHRUNG_HEADER_CONTINUATION: &str = "Dieses Dokument";
    const FULL_REFUND_TEXT: &str = "UBS Europe SE will refund to you the full amount less expenses";
    // The partial-refund text has an inline field between "to you" and "%", so we
    // match the "% of any sales commissions" fragment that follows the field.
    const PARTIAL_REFUND_TEXT: &str = "% of any sales commissions";

    // ── helpers ───────────────────────────────────────────────────────────────
    fn has_text(state: &crate::FormState, pattern: &str) -> bool {
        state.flattened.iter_nodes().any(|n| {
            matches!(&n.kind, FlattenedNodeKind::Text { content, .. } if content.contains(pattern))
        })
    }

    /// Returns true when a text node contains AUSKEHRUNG_TEXT but is NOT the
    /// form-header node (which continues with AUSKEHRUNG_HEADER_CONTINUATION).
    fn has_standalone_auskehrung(state: &crate::FormState) -> bool {
        state.flattened.iter_nodes().any(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains(AUSKEHRUNG_TEXT)
                    && !content.contains(AUSKEHRUNG_HEADER_CONTINUATION)
            } else {
                false
            }
        })
    }

    fn has_company_field(state: &crate::FormState) -> bool {
        state
            .flattened
            .iter_nodes()
            .any(|n| matches!(&n.kind, FlattenedNodeKind::Field { name, .. } if name == "Company"))
    }

    fn get_fall_value(state: &crate::FormState) -> Option<String> {
        state.selections.iter().find_map(|sel| {
            if sel.som_path.as_str().ends_with(".Fall") {
                sel.values.first().cloned()
            } else {
                None
            }
        })
    }

    fn get_client_type_values(state: &crate::FormState) -> Vec<String> {
        state
            .selections
            .iter()
            .find_map(|sel| {
                if sel.som_path.as_str().ends_with(".CL_ClientType") {
                    Some(sel.values.clone())
                } else {
                    None
                }
            })
            .unwrap_or_default()
    }

    // ── load form and explore states ──────────────────────────────────────────
    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_EN.pdf")).unwrap();
    let states = bp.states().unwrap();

    assert_eq!(states.len(), 9, "AAIS_019 should have 9 states");

    for state in states.iter() {
        let fall = get_fall_value(&state);
        let client_types = get_client_type_values(&state);

        // ── 1. Always visible in every state ─────────────────────────────────
        assert!(
            has_text(&state, BENEFITS_TEXT),
            "State '{}': 'UBS Europe SE may receive benefits…' should be visible in all states",
            state.label
        );
        assert!(
            has_text(&state, SUCCESS_FEES_TEXT),
            "State '{}': 'UBS Europe SE may pay success fees…' should be visible in all states",
            state.label
        );

        // ── 2–4. Fall-specific visibility ────────────────────────────────────
        match fall.as_deref() {
            Some("Normalfall (Kunde akzeptiert Einbehalt der Vertriebsprovisionen)") => {
                assert!(
                    has_text(&state, WAIVER_TEXT),
                    "State '{}' (Normalfall): 'Waiver of Right to receive Commission' should be visible",
                    state.label
                );
                assert!(
                    !has_standalone_auskehrung(&state),
                    "State '{}' (Normalfall): standalone 'Auskehrung an Kunden setzt Approval…' should NOT be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, FULL_REFUND_TEXT),
                    "State '{}' (Normalfall): full-refund text should NOT be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, PARTIAL_REFUND_TEXT),
                    "State '{}' (Normalfall): partial-refund text should NOT be visible",
                    state.label
                );
            }
            Some("Komplette Auskehrung von Vertriebsprovisionen an Kunden") => {
                assert!(
                    has_text(&state, FULL_REFUND_TEXT),
                    "State '{}' (Komplette): full-refund text should be visible",
                    state.label
                );
                assert!(
                    has_standalone_auskehrung(&state),
                    "State '{}' (Komplette): standalone 'Auskehrung an Kunden setzt Approval…' should be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, WAIVER_TEXT),
                    "State '{}' (Komplette): 'Waiver of Right to receive Commission' should NOT be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, PARTIAL_REFUND_TEXT),
                    "State '{}' (Komplette): partial-refund text should NOT be visible",
                    state.label
                );
            }
            Some("Teilweise Auskehrung von Vertriebsprovisionen an Kunden") => {
                assert!(
                    has_text(&state, PARTIAL_REFUND_TEXT),
                    "State '{}' (Teilweise): partial-refund text should be visible",
                    state.label
                );
                assert!(
                    has_standalone_auskehrung(&state),
                    "State '{}' (Teilweise): standalone 'Auskehrung an Kunden setzt Approval…' should be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, WAIVER_TEXT),
                    "State '{}' (Teilweise): 'Waiver of Right to receive Commission' should NOT be visible",
                    state.label
                );
                assert!(
                    !has_text(&state, FULL_REFUND_TEXT),
                    "State '{}' (Teilweise): full-refund text should NOT be visible",
                    state.label
                );
            }
            other => panic!(
                "State '{}': unexpected Fall value: {:?}. Expected one of: \
                 'Normalfall (Kunde akzeptiert Einbehalt der Vertriebsprovisionen)', \
                 'Komplette Auskehrung von Vertriebsprovisionen an Kunden', or \
                 'Teilweise Auskehrung von Vertriebsprovisionen an Kunden'",
                state.label, other
            ),
        }

        // ── 5. Company field visibility based on form addressee ───────────────
        let company_visible = has_company_field(&state);
        let is_firma_or_gbr = client_types.iter().any(|ct| ct == "Firma" || ct == "GbR");
        let is_minor_or_private = client_types
            .iter()
            .any(|ct| ct == "Minderjährige" || ct == "Private Person");

        if is_firma_or_gbr {
            assert!(
                company_visible,
                "State '{}' (Firma/GbR): Company field should be visible",
                state.label
            );
        }
        if is_minor_or_private {
            assert!(
                !company_visible,
                "State '{}' (Minderjährige/Private Person): Company field should NOT be visible",
                state.label
            );
        }
    }
}

#[test]
fn test_radio_inherits_heading_label_when_directly_above() {
    // Radio button groups with no label inherit the heading text directly
    // above them (with nothing in between) as their label.
    // The heading itself must still be present in the output.
    use crate::run_exhaustive_to_merged;
    use crate::structured::StructuredNode;

    let structured = run_exhaustive_to_merged(input_path("AABK_019_DE.pdf"))
        .expect("Failed to process AABK PDF");

    let radio_fields = collect_radio_fields(&structured);

    // RB_Group_Periodische_Due_Diligence should have inherited its heading label
    let field = radio_fields
        .iter()
        .find(|f| {
            f.som_path_str()
                .contains("RB_Group_Periodische_Due_Diligence")
        })
        .expect("Expected to find RB_Group_Periodische_Due_Diligence radio field");

    assert!(
        field.label.is_some(),
        "Radio group should have inherited a heading label"
    );
    let label_text = field.label.as_ref().unwrap().as_plain_text();
    assert!(
        !label_text.trim().is_empty(),
        "Inherited heading label should not be empty"
    );

    // The heading that was used as label must still exist in the structured output
    let mut heading_found = false;
    helpers::walk_structured_nodes(&structured, &mut |node| {
        if let StructuredNode::Heading(h) = node {
            if h.content.as_plain_text().trim() == label_text.trim() {
                heading_found = true;
            }
        }
    });
    assert!(
        heading_found,
        "Heading '{}' should still be present in the output after being used as radio label",
        label_text.trim()
    );
}

#[test]
fn test_aais_019_no_missing_translation_list() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured;

    let de = run_exhaustive_to_envelope(input_path("AAIS_019_DE.pdf"), "de")
        .expect("Failed to process AAIS_019_DE");
    let en = run_exhaustive_to_envelope(input_path("AAIS_019_EN.pdf"), "en")
        .expect("Failed to process AAIS_019_EN");
    let sp = run_exhaustive_to_envelope(input_path("AAIS_019_SP.pdf"), "es")
        .expect("Failed to process AAIS_019_SP");

    let merged = structured::merge_translations(vec![de, en, sp], None)
        .expect("AAIS_019 three-language merge should succeed");

    let lists = helpers::collect_lists(&merged.content);

    // No individual list item should have MISSING TRANSLATION in every language,
    // since at least the source language should have real content.
    for (i, l) in lists.iter().enumerate() {
        for (j, item) in l.items.iter().enumerate() {
            let en = item.plain_text_in("en");
            let de = item.plain_text_in("de");
            let es = item.plain_text_in("es");
            let all_missing = en.trim().is_empty() && de.trim().is_empty() && es.trim().is_empty();
            assert!(
                !all_missing,
                "List {} item {} has missing translation in every language; \
                 this indicates an empty list item leaked through",
                i, j,
            );
        }
    }
}

