// Table Detection Tests
// ============================================================================
// Tests for table detection infrastructure. The actual detection algorithm
// is disabled pending refinement to avoid false positives.

#[test]
fn test_table_collection_infrastructure() {
    // Verify that the collect_tables helper works correctly
    use crate::structured::{
        ParagraphNode, StructuredNode, TableHeader, TableNode, TableRow, TranslatedText,
    };
    use helpers::collect_tables;

    // Create a test table
    let table = StructuredNode::Table(TableNode {
        header: Some(TableHeader {
            cells: vec![
                StructuredNode::Paragraph(ParagraphNode {
                    content: TranslatedText::plain("Col1"),
                    som_path: None,
                    source_name: None,
                }),
                StructuredNode::Paragraph(ParagraphNode {
                    content: TranslatedText::plain("Col2"),
                    som_path: None,
                    source_name: None,
                }),
            ],
        }),
        rows: vec![TableRow {
            cells: vec![
                StructuredNode::Paragraph(ParagraphNode {
                    content: TranslatedText::plain("A"),
                    som_path: None,
                    source_name: None,
                }),
                StructuredNode::Paragraph(ParagraphNode {
                    content: TranslatedText::plain("B"),
                    som_path: None,
                    source_name: None,
                }),
            ],
        }],
        caption: None,
    });

    let nodes = vec![table];
    let tables = collect_tables(&nodes);

    assert_eq!(tables.len(), 1, "Should collect exactly one table");
    assert!(tables[0].header.is_some(), "Table should have a header");
    assert_eq!(tables[0].rows.len(), 1, "Table should have one row");
}

#[test]
fn test_aais_019_aem_disclosure_texts_not_in_conditional() {
    // Both of these paragraphs appear identically in every form state of AAIS_019
    // and must therefore be "factored out" of conditionals in the merged output.
    // If either text ends up inside a ConditionalNode the AEM output will
    // incorrectly hide it for certain form states.
    use crate::run_exhaustive_to_merged;

    const BENEFITS_TEXT: &str = "UBS Europe SE may receive benefits from investment fund providers and issuers of structured products";

    const DETAILS_TEXT: &str =
        "Details of the sales compensation for a specific financial instrument";

    let merged = run_exhaustive_to_merged(input_path("AAIS_019_EN.pdf"))
        .expect("Failed to run exhaustive merge on AAIS_019_EN");

    assert!(
        helpers::has_text_outside_conditional(&merged, BENEFITS_TEXT),
        "'UBS Europe SE may receive benefits…' must NOT be inside a conditional – \
         it is common to all states and should be factored out"
    );

    assert!(
        helpers::has_text_outside_conditional(&merged, DETAILS_TEXT),
        "'Details of the sales compensation…' must NOT be inside a conditional – \
         it is common to all states and should be factored out"
    );
}

/// Diagnostic test: look for potential table structures in BAGO_019 by analyzing
/// horizontal lines (borders) and column alignment.
#[test]
fn test_bago_019_table_detection_diagnostic() {
    use crate::flattened::FlattenedNodeKind;
    use rust_decimal::Decimal;

    let mut bp = Blueprint::from_pdf(input_path("BAGO_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    println!("\n=== BAGO_019 Table Detection Diagnostic ===\n");

    // Look for text nodes with borders (potential table cells)
    let mut cells_with_borders: Vec<(Decimal, Decimal, Decimal, Decimal, String, String)> =
        Vec::new();

    for node in flattened.iter_nodes() {
        if let FlattenedNodeKind::Text { content, .. } = &node.kind {
            // Check if node has bottom border (horizontal line)
            let _has_bottom_border = node.style.border.as_ref().is_some_and(|b| {
                b.get_edge(2).is_some_and(|e| {
                    e.presence != "hidden" && e.thickness.is_some_and(|t| t > Decimal::ZERO)
                })
            });

            let border_info = if let Some(border) = &node.style.border {
                let mut edges = Vec::new();
                for (i, name) in [(0, "top"), (1, "right"), (2, "bottom"), (3, "left")].iter() {
                    if let Some(e) = border.get_edge(*i) {
                        if e.presence != "hidden" && e.thickness.is_some_and(|t| t > Decimal::ZERO)
                        {
                            edges.push(format!("{}:{:?}", name, e.thickness));
                        }
                    }
                }
                if edges.is_empty() {
                    "no-edges".to_string()
                } else {
                    edges.join(",")
                }
            } else {
                "no-border".to_string()
            };

            let preview: String = content.trim().chars().take(40).collect();
            if !preview.is_empty() && border_info != "no-border" && border_info != "no-edges" {
                cells_with_borders.push((
                    node.y,
                    node.x,
                    node.width,
                    node.height,
                    preview,
                    border_info,
                ));
            }
        }
    }

    cells_with_borders.sort_by(|a, b| a.0.cmp(&b.0).then_with(|| a.1.cmp(&b.1)));

    println!("Text nodes with borders ({}):", cells_with_borders.len());
    for (i, (y, x, w, h, text, borders)) in cells_with_borders.iter().enumerate() {
        println!(
            "  {:2}. y={:7.2}, x={:7.2}, w={:7.2}, h={:7.2}: '{}' [{:}]",
            i + 1,
            y,
            x,
            w,
            h,
            text,
            borders
        );
    }

    // Look at the table mentioned by user: "Destination area Currency Unique identifier"
    println!("\n\n=== Looking for 'Destination area' table ===");
    for node in flattened.iter_nodes() {
        if let FlattenedNodeKind::Text { content, .. } = &node.kind {
            let content_lower = content.to_lowercase();
            if content_lower.contains("destination")
                || content_lower.contains("zielgebiet")
                || content_lower.contains("currency")
                || content_lower.contains("währung")
                || content_lower.contains("iban")
                || content_lower.contains("bic")
                || content_lower.contains("germany")
                || content_lower.contains("deutschland")
            {
                let border_info = if let Some(border) = &node.style.border {
                    let mut edges = Vec::new();
                    for (i, name) in [(0, "top"), (1, "right"), (2, "bottom"), (3, "left")].iter() {
                        if let Some(e) = border.get_edge(*i) {
                            if e.presence != "hidden" {
                                edges.push(format!("{}:{:?}", name, e.thickness));
                            }
                        }
                    }
                    if edges.is_empty() {
                        "no-visible-edges".to_string()
                    } else {
                        edges.join(",")
                    }
                } else {
                    "no-border".to_string()
                };

                let preview: String = content.trim().chars().take(60).collect();
                println!(
                    "  y={:7.2}, x={:7.2}, w={:7.2}: '{}' [{}]",
                    node.y, node.x, node.width, preview, border_info
                );
            }
        }
    }

    // Look for ALL nodes around y=5078 (the country/currency table header row)
    println!("\n\n=== All text nodes at y≈5078 (country table header row) ===");
    for node in flattened.iter_nodes() {
        if let FlattenedNodeKind::Text { content, .. } = &node.kind {
            if node.y >= Decimal::from(5070) && node.y <= Decimal::from(5085) {
                let border_info = if let Some(border) = &node.style.border {
                    let mut edges = Vec::new();
                    for (i, name) in [(0, "top"), (1, "right"), (2, "bottom"), (3, "left")].iter() {
                        if let Some(e) = border.get_edge(*i) {
                            if e.presence != "hidden" {
                                edges.push(format!("{}:{:?}", name, e.thickness));
                            }
                        }
                    }
                    if edges.is_empty() {
                        "no-visible-edges".to_string()
                    } else {
                        edges.join(",")
                    }
                } else {
                    "no-border".to_string()
                };

                let preview: String = content.trim().chars().take(60).collect();
                println!(
                    "  y={:7.2}, x={:7.2}, w={:7.2}: '{}' [{}]",
                    node.y, node.x, node.width, preview, border_info
                );
            }
        }
    }

    // Look for ALL nodes around y=5090 (first data row)
    println!("\n=== All text nodes at y≈5090 (first data row - Belgien) ===");
    for node in flattened.iter_nodes() {
        if let FlattenedNodeKind::Text { content, .. } = &node.kind {
            if node.y >= Decimal::from(5085) && node.y <= Decimal::from(5100) {
                let border_info = if let Some(border) = &node.style.border {
                    let mut edges = Vec::new();
                    for (i, name) in [(0, "top"), (1, "right"), (2, "bottom"), (3, "left")].iter() {
                        if let Some(e) = border.get_edge(*i) {
                            if e.presence != "hidden" {
                                edges.push(format!("{}:{:?}", name, e.thickness));
                            }
                        }
                    }
                    if edges.is_empty() {
                        "no-visible-edges".to_string()
                    } else {
                        edges.join(",")
                    }
                } else {
                    "no-border".to_string()
                };

                let preview: String = content.trim().chars().take(60).collect();
                println!(
                    "  y={:7.2}, x={:7.2}, w={:7.2}: '{}' [{}]",
                    node.y, node.x, node.width, preview, border_info
                );
            }
        }
    }
}

