/// Test table detection for BAGO_019_DE.pdf
/// Expected: exactly 2 tables
/// Table 1: "Destination area / Currency / Unique identifier" table (3 columns, 5 rows)
/// Table 2: Country/Currency table (2 columns, 30+ rows)
#[test]
fn test_bago_019_table_detection() {
    use crate::document::Document;
    use crate::document::modules::run_analysis_pipeline;
    use crate::structured::{StructuredNode, TableNode};

    let mut bp = Blueprint::from_pdf(input_path("BAGO_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Run the analysis pipeline
    let mut doc = Document::from_flattened(flattened);
    run_analysis_pipeline(&mut doc);

    // Convert to structured nodes
    let structured = crate::structured::convert(&doc);

    // Collect all tables (owned)
    fn collect_tables(nodes: &[StructuredNode]) -> Vec<TableNode> {
        let mut tables = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::Table(t) => tables.push(t.clone()),
                StructuredNode::Group(g) => tables.extend(collect_tables(&g.children)),
                StructuredNode::Repeatable(r) => {
                    let items = vec![r.item.as_ref().clone()];
                    tables.extend(collect_tables(&items));
                }
                StructuredNode::Conditional(c) => {
                    let items = vec![c.content.as_ref().clone()];
                    tables.extend(collect_tables(&items));
                }
                StructuredNode::GridLayout(g) => {
                    let items: Vec<_> = g.elements.iter().map(|e| e.node.clone()).collect();
                    tables.extend(collect_tables(&items));
                }
                _ => {}
            }
        }
        tables
    }

    let tables = collect_tables(&structured);

    println!("\n=== BAGO_019 Table Detection Results ===");
    println!("Found {} tables", tables.len());
    for (i, table) in tables.iter().enumerate() {
        let num_cols = if let Some(header) = &table.header {
            header.cells.len()
        } else if !table.rows.is_empty() {
            table.rows[0].cells.len()
        } else {
            0
        };
        let num_rows = table.rows.len() + if table.header.is_some() { 1 } else { 0 };
        println!(
            "  Table {}: {} columns x {} rows",
            i + 1,
            num_cols,
            num_rows
        );
    }

    // Assert we found exactly 2 tables
    assert_eq!(
        tables.len(),
        2,
        "BAGO_019 should have exactly 2 tables detected. Found {}",
        tables.len()
    );

    // Check the expected content for Table 1 (destination area table)
    let table1_content: Vec<String> = tables[0]
        .rows
        .iter()
        .flat_map(|row| row.cells.iter())
        .chain(tables[0].header.iter().flat_map(|h| h.cells.iter()))
        .filter_map(|cell| {
            if let StructuredNode::Paragraph(p) = cell {
                Some(p.content.as_plain_text())
            } else {
                None
            }
        })
        .collect();

    // The first table should contain references to destination areas and payment identifiers
    let all_content = table1_content.join(" ");
    assert!(
        all_content.contains("Zielgebiet")
            || all_content.contains("IBAN")
            || all_content.contains("Währung"),
        "Table 1 should contain destination area/IBAN/currency content"
    );
}

/// Test table detection for AAIS_019_EN.pdf
/// Expected: exactly 1 table (fee structure table)
/// Table: 2 columns x 9 rows (fund type + fee percentage)
#[test]
fn test_aais_019_table_detection() {
    use crate::document::Document;
    use crate::document::modules::run_analysis_pipeline;
    use crate::structured::{StructuredNode, TableNode};

    let mut bp = Blueprint::from_pdf(input_path("AAIS_019_EN.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Run the analysis pipeline
    let mut doc = Document::from_flattened(flattened);
    run_analysis_pipeline(&mut doc);

    // Convert to structured nodes
    let structured = crate::structured::convert(&doc);

    // Collect all tables (owned)
    fn collect_tables(nodes: &[StructuredNode]) -> Vec<TableNode> {
        let mut tables = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::Table(t) => tables.push(t.clone()),
                StructuredNode::Group(g) => tables.extend(collect_tables(&g.children)),
                StructuredNode::Repeatable(r) => {
                    let items = vec![r.item.as_ref().clone()];
                    tables.extend(collect_tables(&items));
                }
                StructuredNode::Conditional(c) => {
                    let items = vec![c.content.as_ref().clone()];
                    tables.extend(collect_tables(&items));
                }
                StructuredNode::GridLayout(g) => {
                    let items: Vec<_> = g.elements.iter().map(|e| e.node.clone()).collect();
                    tables.extend(collect_tables(&items));
                }
                _ => {}
            }
        }
        tables
    }

    let tables = collect_tables(&structured);

    println!("\n=== AAIS_019 Table Detection Results ===");
    println!("Found {} tables", tables.len());
    for (i, table) in tables.iter().enumerate() {
        let num_cols = if let Some(header) = &table.header {
            header.cells.len()
        } else if !table.rows.is_empty() {
            table.rows[0].cells.len()
        } else {
            0
        };
        let num_rows = table.rows.len() + if table.header.is_some() { 1 } else { 0 };
        println!(
            "  Table {}: {} columns x {} rows",
            i + 1,
            num_cols,
            num_rows
        );

        // Print first few cells for debugging
        if !table.rows.is_empty() {
            for (row_idx, row) in table.rows.iter().take(3).enumerate() {
                for (col_idx, cell) in row.cells.iter().enumerate() {
                    if let StructuredNode::Paragraph(p) = cell {
                        let text: String = p.content.as_plain_text().chars().take(50).collect();
                        println!("    [{},{}]: '{}'", row_idx, col_idx, text);
                    }
                }
            }
        }
    }

    // Assert we found exactly 1 table
    assert_eq!(
        tables.len(),
        1,
        "AAIS_019 should have exactly 1 table detected. Found {}",
        tables.len()
    );

    // Check the table has 2 columns
    let table = &tables[0];
    let num_cols = if let Some(header) = &table.header {
        header.cells.len()
    } else if !table.rows.is_empty() {
        table.rows[0].cells.len()
    } else {
        0
    };
    assert_eq!(
        num_cols, 2,
        "AAIS_019 table should have 2 columns. Found {}",
        num_cols
    );

    // Check the table has 9 rows (as specified by user)
    let num_rows = table.rows.len() + if table.header.is_some() { 1 } else { 0 };
    assert_eq!(
        num_rows, 9,
        "AAIS_019 table should have 9 rows. Found {}",
        num_rows
    );

    // Verify content: should contain fund types and percentages
    let all_content: String = table
        .rows
        .iter()
        .flat_map(|row| row.cells.iter())
        .chain(table.header.iter().flat_map(|h| h.cells.iter()))
        .filter_map(|cell| {
            if let StructuredNode::Paragraph(p) = cell {
                Some(p.content.as_plain_text())
            } else {
                None
            }
        })
        .collect::<Vec<_>>()
        .join(" ");

    assert!(
        all_content.contains("money market"),
        "Table should contain 'money market funds'"
    );
    assert!(
        all_content.contains("equity fund"),
        "Table should contain 'equity funds'"
    );
    assert!(
        all_content.contains("p.a."),
        "Table should contain fee percentages (p.a.)"
    );
}

#[test]
fn test_bagq_exhaustive_discovers_checkbox_hidden_content() {
    // BAGQ has 8 currency checkboxes (CB_EUR, CB_USD, ...) that reveal hidden
    // content sections (EUR, USD, ...) via a calculate script on the parent
    // subform. The checkboxes themselves have no interactive scripts, but they
    // must still be explored because the parent subform's calculate script
    // reads their values and toggles section visibility.
    //
    // With all checkboxes unchecked (default), only the base form is visible.
    // Checking a checkbox reveals a currency section with additional content.
    // The exhaustive search must produce more than 1 state.
    let mut bp = Blueprint::from_pdf(input_path("BAGQ_019_DE.pdf"))
        .expect("Failed to create Blueprint from BAGQ PDF");
    let form_states = bp.states().expect("Failed to collect exhaustive states");

    assert!(
        form_states.len() > 1,
        "BAGQ should produce more than 1 exhaustive state (checkboxes reveal currency sections), got {}",
        form_states.len()
    );

    // Verify that at least one state has checkbox selections
    let has_checkbox_selection = form_states.iter().any(|s| {
        s.selections
            .iter()
            .any(|sel| sel.kind == SelectionKind::Checkbox)
    });
    assert!(
        has_checkbox_selection,
        "At least one BAGQ state should have checkbox selections"
    );
}

#[test]
fn test_bagq_debug_selectable_fields() {
    // Debug test — trace EUR visibility through the set_value + refresh flow
    let mut bp = Blueprint::from_pdf(input_path("BAGQ_019_DE.pdf"))
        .expect("Failed to create Blueprint from BAGQ PDF");
    let form = bp.form_mut().expect("should be XFA PDF");

    // Check initial state
    let initial_eur_vis = form.is_path_visible("UBSForms.Page.EUR");
    eprintln!("EUR initially visible: {}", initial_eur_vis);

    // Check EUR presence on the XFA node
    if let Some(eur_node) = form.resolve("UBSForms.Page.EUR") {
        eprintln!(
            "EUR XFA node presence: {:?}",
            eur_node.xfa_node().get_presence()
        );
    }

    // Check EUR initial presence in JS engine
    let eval_result = form.eval_js("return Page.EUR.presence");
    eprintln!("Page.EUR.presence in JS (initial): {:?}", eval_result);

    // Check flattened key before
    let flat_key_before = form.flattened_mut().flattened_key().clone();
    eprintln!("Flattened key count before: {}", flat_key_before.len());

    // Set CB_EUR=1 (check the checkbox)
    let cb_path = "UBSForms.Page.FormConfigurator_Currency.STP_Currencies.CB_EUR";
    let result = form.set_value_as_user(cb_path, "1");
    eprintln!("set_value_as_user result: {:?}", result);

    // Check JS presence after set_value_as_user (which now runs ancestor calculate)
    let eval_result = form.eval_js("return Page.EUR.presence");
    eprintln!(
        "Page.EUR.presence in JS (after set_value): {:?}",
        eval_result
    );

    // Check presence changes from JS engine
    let changes = form.get_presence_changes();
    eprintln!("Presence changes from JS engine: {:?}", changes);

    // Now refresh (which should sync JS presence to XFA nodes and reflatten)
    form.refresh().expect("refresh failed");

    // Check EUR visibility after refresh
    let eur_vis_after = form.is_path_visible("UBSForms.Page.EUR");
    eprintln!("EUR visible after refresh: {}", eur_vis_after);

    // Check flattened key after
    let flat_key_after = form.flattened_mut().flattened_key().clone();
    eprintln!("Flattened key count after: {}", flat_key_after.len());

    // The key: flattened output should be different when EUR is visible vs hidden
    eprintln!(
        "Flattened key changed: {}",
        flat_key_before != flat_key_after
    );
}

/// Regression test: German Umlauts (ü, ö, ä, ß) must be preserved
/// in AAIS_019_DE text output. A bug caused "ü" to appear as "u?"
/// in the rendered output (e.g. "Gebühr" → "Gebu?hr").
#[test]
fn test_aais_019_de_umlauts_preserved() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::StructuredNode;

    let envelope = run_exhaustive_to_envelope(input_path("AAIS_019_DE.pdf"), "de")
        .expect("Failed to process AAIS_019_DE");

    // Collect ALL plain text from the structured output
    let mut all_texts = Vec::new();
    helpers::walk_structured_nodes(&envelope.content, &mut |node| {
        let text = match node {
            StructuredNode::Paragraph(p) => p.content.as_plain_text(),
            StructuredNode::Heading(h) => h.content.as_plain_text(),
            StructuredNode::Field(f) => f
                .label
                .as_ref()
                .map_or(String::new(), |l| l.as_plain_text()),
            _ => return,
        };
        if !text.trim().is_empty() {
            all_texts.push(text);
        }
    });

    // 1. No text should contain the corruption pattern "u?" where "ü" is expected.
    //    Specifically, these German words must contain proper umlauts:
    let expected_umlaut_words = [
        "Gebühr",    // fee/charge
        "Vergütung", // compensation
        "für",       // for
        "vergüte",   // compensate (stem)
    ];

    for word in &expected_umlaut_words {
        let found = all_texts.iter().any(|t| t.contains(word));
        // Also check for the corrupted version
        let corrupted = word.replace('ü', "u?");
        let found_corrupted = all_texts.iter().any(|t| t.contains(&corrupted));

        assert!(
            found && !found_corrupted,
            "Expected to find '{}' in AAIS_019_DE text output. \
             Found correct: {}, Found corrupted '{}': {}",
            word,
            found,
            corrupted,
            found_corrupted,
        );
    }

    // 2. No text anywhere should contain the pattern of a base letter followed by "?"
    //    where an umlaut is expected. We check broadly: no "u?", "o?", "a?" patterns
    //    that look like corrupted umlauts (preceded by a lowercase letter and followed
    //    by a lowercase letter).
    for text in &all_texts {
        // Look for corruption pattern: lowercase letter + "?" + lowercase letter
        let chars: Vec<char> = text.chars().collect();
        for i in 0..chars.len().saturating_sub(2) {
            if chars[i + 1] == '?'
                && (chars[i] == 'u' || chars[i] == 'o' || chars[i] == 'a')
                && chars[i + 2].is_lowercase()
            {
                panic!(
                    "Found likely corrupted umlaut '{}{}{} ' in text: '{}'. \
                     This suggests '{}' should be '{}'.",
                    chars[i],
                    chars[i + 1],
                    chars[i + 2],
                    text,
                    &text[..],
                    text.replace("u?", "ü")
                        .replace("o?", "ö")
                        .replace("a?", "ä"),
                );
            }
        }
    }
}

/// Regression test: AEM form .content.xml must have an XML declaration with
/// encoding="UTF-8" so that AEM/CRX correctly interprets multi-byte UTF-8
/// characters (German umlauts, etc.). Without this declaration, some JCR
/// implementations fall back to ISO-8859-1, causing "ü" → "u?" corruption.
#[test]
fn test_aem_form_xml_has_utf8_declaration() {
    use crate::aem::{AemConfig, convert_to_aem, generate_aem_xml};

    let mut bp =
        Blueprint::from_pdf(input_path("AAIS_019_DE.pdf")).expect("Failed to load AAIS PDF");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to explore states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = load_ubs_profile();
    let config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("Failed to create AemConfig");
    let config = crate::resolve_aem_languages(&content, &config);

    let root = convert_to_aem(&content, &config);
    let form_xml = generate_aem_xml(&root, &config);

    // The form XML must start with the XML declaration
    assert!(
        form_xml.starts_with("<?xml"),
        "Form .content.xml must start with an XML declaration, got: '{}'",
        &form_xml[..form_xml.len().min(100)],
    );
    assert!(
        form_xml.contains("encoding=\"UTF-8\""),
        "Form .content.xml must declare encoding=\"UTF-8\"",
    );

    // Umlauts must appear correctly in the form XML
    assert!(
        form_xml.contains("Gebühr") || form_xml.contains("Vergütung") || form_xml.contains("für"),
        "Form XML should contain German umlauts (Gebühr, Vergütung, für)",
    );
}

#[test]
fn test_aari_has_list_with_expected_items() {
    use crate::Blueprint;

    let mut bp =
        Blueprint::from_pdf(input_path("AARI_033_IT.pdf")).expect("Failed to load AARI_033_IT.pdf");

    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let state = form_states.iter().next().unwrap();
    let envelope = state.structured(ctx);

    let lists = helpers::collect_lists(&envelope.content);

    // Find the list containing "cessione a titolo oneroso di partecipazioni"
    let target_list = lists.iter().find(|l| {
        l.items.iter().any(|item| {
            item.as_plain_text()
                .contains("cessione a titolo oneroso di partecipazioni")
        })
    });

    assert!(
        target_list.is_some(),
        "Expected a list containing 'cessione a titolo oneroso di partecipazioni'.\nFound lists: {:?}",
        lists
            .iter()
            .map(|l| l
                .items
                .iter()
                .map(|i| i.as_plain_text())
                .collect::<Vec<_>>())
            .collect::<Vec<_>>()
    );

    let target_list = target_list.unwrap();

    // The source list has four sequential letter markers a) b) c) d).  The
    // d) marker is a hanging-indent bullet (offset onto the second line of its
    // multi-line paragraph), so it is merged by the standalone marker merger's
    // containment rule alongside the same-line a)/b)/c) markers.
    assert_eq!(
        target_list.items.len(),
        4,
        "Expected 4 items in the list, got {}.\nItems: {:?}",
        target_list.items.len(),
        target_list
            .items
            .iter()
            .map(|i| i.as_plain_text())
            .collect::<Vec<_>>()
    );

    let texts: Vec<String> = target_list
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();

    assert!(
        texts.iter().any(|t| t
            .contains("cessione a titolo oneroso di partecipazioni qualificate e non qualificate")),
        "List should contain item about 'partecipazioni qualificate e non qualificate'.\nItems: {:?}",
        texts
    );
    assert!(
        texts.iter().any(|t| t.contains(
            "cessione a titolo oneroso ovvero rimborso di titoli non rappresentativi di merci"
        )),
        "List should contain item about 'rimborso di titoli non rappresentativi di merci'.\nItems: {:?}",
        texts
    );
    assert!(
        texts
            .iter()
            .any(|t| t.contains("rapporti da cui deriva il diritto o l")
                && t.contains("obbligo di cedere o acquistare a termine strumenti finanziari")),
        "List should contain item about 'rapporti da cui deriva il diritto o l'obbligo'.\nItems: {:?}",
        texts
    );
    assert!(
        texts.iter().any(
            |t| t.contains("cessione, a titolo oneroso ovvero chiusura di rapporti produttivi")
        ),
        "List should contain the d) item about 'chiusura di rapporti produttivi'.\nItems: {:?}",
        texts
    );
}

/// Regression test: BAGE headings like "1. Umfang der Verwaltungsvollmacht",
/// "8. Risikoaufklärung", "9. Eigene Aufträge" must not contain segments with
/// missing translations. Previously, whitespace-only inline segments between
/// a numbering prefix and the heading text were marked as missing translations.
#[test]
fn test_bage_headings_no_missing_translation() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::{self, StructuredNode, TranslatedText};

    let de = run_exhaustive_to_envelope(input_path("BAGE_019_DE.pdf"), "de")
        .expect("Failed to process BAGE_019_DE");
    let en = run_exhaustive_to_envelope(input_path("BAGE_019_EN.pdf"), "en")
        .expect("Failed to process BAGE_019_EN");

    let merged = structured::merge_translations(vec![de, en], None).unwrap();

    // Collect all headings from the merged tree.
    fn collect_headings(nodes: &[StructuredNode], out: &mut Vec<(u8, TranslatedText)>) {
        for node in nodes {
            match node {
                StructuredNode::Heading(h) => {
                    out.push((h.level.as_u8(), h.content.clone()));
                }
                StructuredNode::Group(g) => collect_headings(&g.children, out),
                StructuredNode::Conditional(c) => collect_headings(&[(*c.content).clone()], out),
                StructuredNode::Repeatable(r) => collect_headings(&[(*r.item).clone()], out),
                StructuredNode::GridLayout(g) => {
                    let children: Vec<_> = g.elements.iter().map(|e| e.node.clone()).collect();
                    collect_headings(&children, out);
                }
                _ => {}
            }
        }
    }

    let mut headings = Vec::new();
    collect_headings(&merged.content, &mut headings);

    // No heading should have any language with a missing/empty translation.
    for (level, tt) in &headings {
        for (lang, val) in &tt.0 {
            assert!(
                !val.as_plain_text().is_empty(),
                "H{} heading has missing translation for lang '{}': keys {:?}",
                level,
                lang,
                tt.0.keys().collect::<Vec<_>>()
            );
        }
    }
}

/// Regression test: BAGE numbered headings like "2. Ausführung von Wertpapier-Aufträgen"
/// must keep the number prefix with the heading text, not detach it into the
/// following paragraph.
#[test]
fn test_bage_numbered_headings_keep_number_prefix() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::StructuredNode;

    let de = run_exhaustive_to_envelope(input_path("BAGE_019_DE.pdf"), "de")
        .expect("Failed to process BAGE_019_DE");

    // Collect headings and paragraphs in order
    let mut headings: Vec<String> = Vec::new();
    let mut paragraphs: Vec<String> = Vec::new();
    helpers::walk_structured_nodes(&de.content, &mut |node| match node {
        StructuredNode::Heading(h) => {
            headings.push(h.content.as_plain_text());
        }
        StructuredNode::Paragraph(p) => {
            paragraphs.push(p.content.as_plain_text());
        }
        _ => {}
    });

    // The heading "Ausführung von Wertpapier-Aufträgen" must include the "2." prefix.
    assert!(
        headings
            .iter()
            .any(|h| h.contains("2.") && h.contains("Ausführung von Wertpapier")),
        "Heading '2. Ausführung von Wertpapier-Aufträgen' should have its number prefix.\nHeadings: {:?}",
        headings
    );

    // The heading "Kommunikation und Informationsbeschaffung" must include the "3." prefix.
    assert!(
        headings
            .iter()
            .any(|h| h.contains("3.") && h.contains("Kommunikation und Informationsbeschaffung")),
        "Heading '3. Kommunikation und Informationsbeschaffung' should have its number prefix.\nHeadings: {:?}",
        headings
    );

    // The paragraph "Die An- und Verkauforders..." must NOT start with "2."
    let bad_para_2 = paragraphs.iter().any(|p| {
        let t = p.trim();
        t.starts_with("2.") && t.contains("Verkauforders")
    });
    assert!(
        !bad_para_2,
        "Paragraph 'Die An- und Verkauforders...' should NOT start with '2.'\nParagraphs: {:?}",
        paragraphs
            .iter()
            .filter(|p| p.starts_with("2."))
            .collect::<Vec<_>>()
    );

    // The paragraph "Für die Kommunikation..." must NOT start with "3."
    let bad_para_3 = paragraphs.iter().any(|p| {
        let t = p.trim();
        t.starts_with("3.") && t.contains("Kommunikation zwischen UBS")
    });
    assert!(
        !bad_para_3,
        "Paragraph 'Für die Kommunikation...' should NOT start with '3.'\nParagraphs: {:?}",
        paragraphs
            .iter()
            .filter(|p| p.starts_with("3."))
            .collect::<Vec<_>>()
    );
}

/// Regression test: BAGE checkbox labeled "Sofern abweichend von obiger Regelung..."
/// must have the full label recognized.
/// The expected label is:
/// "Sofern abweichend von obiger Regelung der Schriftverkehr ausschließlich mit dem/der
/// Bevollmächtigten zu führen sein soll, ist hier gesondert anzukreuzen:"
#[test]
fn test_bage_checkbox_label_sofern_abweichend() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::FieldType;

    let doc = run_exhaustive_to_envelope(input_path("BAGE_019_DE.pdf"), "de")
        .expect("Failed to process BAGE_019_DE");

    // Collect all Bool (checkbox) fields
    let fields = collect_fields(&doc.content);
    let bool_fields: Vec<_> = fields
        .iter()
        .filter(|f| matches!(f.input_type, FieldType::Bool))
        .collect();

    // Print all checkbox labels to debug
    println!("=== BAGE Checkbox Fields ===");
    for (i, field) in bool_fields.iter().enumerate() {
        let label = field
            .label
            .as_ref()
            .map(|l| l.as_plain_text())
            .unwrap_or_default();
        println!("Checkbox {}: name={}, label={:?}", i, field.name, label);
    }

    // Find the checkbox that should have the "Sofern abweichend..." label
    let expected_label_fragment = "Sofern abweichend von obiger Regelung der Schriftverkehr ausschließlich mit dem/der Bevollmächtigten zu führen sein soll, ist hier gesondert anzukreuzen:";

    let matching_checkbox = bool_fields.iter().find(|f| {
        let label = f
            .label
            .as_ref()
            .map(|l| l.as_plain_text())
            .unwrap_or_default();
        label.contains("Sofern abweichend")
            || label.contains("Schriftverkehr")
            || label.contains("Bevollmächtigten zu führen")
    });

    assert!(
        matching_checkbox.is_some(),
        "Expected to find a checkbox with a label containing 'Sofern abweichend', 'Schriftverkehr', or 'Bevollmächtigten zu führen'.\nFound labels: {:?}",
        bool_fields
            .iter()
            .map(|f| f
                .label
                .as_ref()
                .map(|l| l.as_plain_text())
                .unwrap_or_default())
            .collect::<Vec<_>>()
    );

    let checkbox = matching_checkbox.unwrap();
    let label = checkbox
        .label
        .as_ref()
        .map(|l| l.as_plain_text())
        .unwrap_or_default();

    // Verify the label contains the expected text
    assert!(
        label.contains("Sofern abweichend von obiger Regelung"),
        "Checkbox label should start with 'Sofern abweichend von obiger Regelung'.\nActual label: {:?}\nExpected: {:?}",
        label,
        expected_label_fragment
    );

    assert!(
        label.contains("Bevollmächtigten zu führen"),
        "Checkbox label should contain 'Bevollmächtigten zu führen'.\nActual label: {:?}",
        label
    );
}

#[test]
fn test_baqn_parenthesized_roman_list() {
    // BAQN contains a list with parenthesized roman numeral markers:
    // (i) ai sensi dell'art. 67-duodecies, ...
    // (ii) ai sensi dell'art. 67-duodecies, ...
    // (iii) ai sensi dell'art. 67-terdecies, ...
    // This test verifies that these markers are detected and grouped as a list.
    use crate::document::ListStyleType;
    use crate::structured::{ListNode, StructuredNode};

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("BAQN_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on BAQN_033_IT.pdf");

    // Collect all lists from the structured output
    fn collect_lists(nodes: &[StructuredNode]) -> Vec<ListNode> {
        let mut lists = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::List(l) => lists.push(l.clone()),
                StructuredNode::Group(g) => lists.extend(collect_lists(&g.children)),
                StructuredNode::Repeatable(r) => {
                    lists.extend(collect_lists(&[(*r.item).clone()]));
                }
                StructuredNode::Conditional(c) => {
                    lists.extend(collect_lists(&[(*c.content).clone()]));
                }
                StructuredNode::GridLayout(gl) => {
                    let child_nodes: Vec<_> = gl.elements.iter().map(|e| e.node.clone()).collect();
                    lists.extend(collect_lists(&child_nodes));
                }
                _ => {}
            }
        }
        lists
    }

    let lists = collect_lists(&structured_nodes);

    // Find the list containing the article 67-duodecies references
    let art_67_list = lists.iter().find(|l| {
        l.items
            .iter()
            .any(|item| item.as_plain_text().contains("67-duodecies"))
    });

    assert!(
        art_67_list.is_some(),
        "Expected to find a list with items containing '67-duodecies'. Found {} total lists.",
        lists.len()
    );

    let list = art_67_list.unwrap();

    // Should be detected as a roman numeral list
    assert_eq!(
        list.list_style,
        ListStyleType::LowerRoman,
        "The (i), (ii), (iii) list should be detected as LowerRoman"
    );

    // Should have 3 items
    assert_eq!(
        list.items.len(),
        3,
        "Expected 3 list items for (i), (ii), (iii), found {}",
        list.items.len()
    );

    // Verify the content of each item mentions the expected article
    let item_texts: Vec<String> = list.items.iter().map(|i| i.as_plain_text()).collect();

    assert!(
        item_texts[0].contains("67-duodecies") && item_texts[0].contains("c. 1"),
        "First item should mention 'art. 67-duodecies, c. 1'. Found: {}",
        item_texts[0]
    );
    assert!(
        item_texts[1].contains("67-duodecies") && item_texts[1].contains("c. 4"),
        "Second item should mention 'art. 67-duodecies, c. 4'. Found: {}",
        item_texts[1]
    );
    assert!(
        item_texts[2].contains("67-terdecies"),
        "Third item should mention 'art. 67-terdecies'. Found: {}",
        item_texts[2]
    );
}

/// Test that BAGE unordered lists are correctly detected.
/// There are multiple unordered lists in BAGE:
/// 1. "Depotaufstellungen", "Rechnungsabschlüsse", "Mitteilungen nach Nr. 16...", "Sonstige Mitteilungen..."
/// 2. Items restricted for the authorized person (starting with "Dispositionen zu eigenen Gunsten...")
/// 3. Authorized actions (starting with "An- und Verkauf von Wertpapieren...")
#[test]
fn test_bage_unordered_lists() {
    use crate::run_exhaustive_to_envelope;

    let doc = run_exhaustive_to_envelope(input_path("BAGE_019_DE.pdf"), "de")
        .expect("Failed to process BAGE_019_DE");

    let lists = helpers::collect_lists(&doc.content);

    // Print all lists for debugging
    println!("=== BAGE Lists ({} total) ===", lists.len());
    for (i, list) in lists.iter().enumerate() {
        println!(
            "List {} ({:?}, {} items):",
            i,
            list.list_style,
            list.items.len()
        );
        for (j, item) in list.items.iter().enumerate() {
            println!("  {}: {}", j, item.as_plain_text());
        }
        println!();
    }

    // List 1: Communication types - should have 4 items
    // Expected items: Depotaufstellungen, Rechnungsabschlüsse, Mitteilungen nach Nr. 16..., Sonstige Mitteilungen...
    let comm_list = lists.iter().find(|l| {
        l.items
            .iter()
            .any(|item| item.as_plain_text().contains("Rechnungsabschlüsse"))
    });
    assert!(
        comm_list.is_some(),
        "Expected to find a list containing 'Rechnungsabschlüsse'"
    );
    let comm_list = comm_list.unwrap();
    let comm_texts: Vec<String> = comm_list.items.iter().map(|i| i.as_plain_text()).collect();
    // Verify all expected items are present
    assert!(
        comm_texts.iter().any(|t| t.contains("Depotaufstellungen")),
        "Communication types list should contain 'Depotaufstellungen'.\nActual items: {:?}",
        comm_texts
    );
    assert!(
        comm_texts.iter().any(|t| t.contains("Rechnungsabschlüsse")),
        "Communication types list should contain 'Rechnungsabschlüsse'.\nActual items: {:?}",
        comm_texts
    );
    assert!(
        comm_texts
            .iter()
            .any(|t| t.contains("Mitteilungen nach Nr. 16")),
        "Communication types list should contain 'Mitteilungen nach Nr. 16'.\nActual items: {:?}",
        comm_texts
    );
    assert!(
        comm_texts
            .iter()
            .any(|t| t.contains("Sonstige Mitteilungen")),
        "Communication types list should contain 'Sonstige Mitteilungen'.\nActual items: {:?}",
        comm_texts
    );

    // List 2: Restrictions (things the authorized person cannot do)
    // The first item "Dispositionen zu eigenen Gunsten..." should be separate from the heading
    // because it has different font style (normal vs bold heading)
    let restrictions_list = lists.iter().find(|l| {
        l.items
            .iter()
            .any(|item| item.as_plain_text().contains("Barabhebungen"))
    });
    assert!(
        restrictions_list.is_some(),
        "Expected to find a list containing 'Barabhebungen'"
    );
    let restrictions_list = restrictions_list.unwrap();
    let restrictions_texts: Vec<String> = restrictions_list
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();

    // BUG: "Dispositionen zu eigenen Gunsten..." is incorrectly merged with the heading
    // It should be a separate list item because the font style is different (bold heading vs normal text)
    assert!(
        restrictions_texts
            .iter()
            .any(|t| t.contains("Dispositionen zu eigenen Gunsten")),
        "Restrictions list should include 'Dispositionen zu eigenen Gunsten...' as a separate item (not merged with heading).\nActual items: {:?}",
        restrictions_texts
    );
    assert!(
        restrictions_texts
            .iter()
            .any(|t| t.contains("Untervollmachten")),
        "Restrictions list should contain 'Untervollmachten'.\nActual items: {:?}",
        restrictions_texts
    );
    assert!(
        restrictions_texts
            .iter()
            .any(|t| t.contains("Sicherheiten")),
        "Restrictions list should contain 'Sicherheiten'.\nActual items: {:?}",
        restrictions_texts
    );
    assert!(
        restrictions_texts
            .iter()
            .any(|t| t.contains("Auflösung von Konten")),
        "Restrictions list should contain 'Auflösung von Konten'.\nActual items: {:?}",
        restrictions_texts
    );
    // Should have 7 items total
    assert_eq!(
        restrictions_texts.len(),
        7,
        "Restrictions list should have 7 items.\nActual items: {:?}",
        restrictions_texts
    );

    // List 3: Permissions (authorized actions)
    let permissions_list = lists.iter().find(|l| {
        l.items.iter().any(|item| {
            item.as_plain_text()
                .contains("An- und Verkauf von Wertpapieren")
        })
    });
    assert!(
        permissions_list.is_some(),
        "Expected to find a list containing 'An- und Verkauf von Wertpapieren'"
    );
    let permissions_list = permissions_list.unwrap();
    let permissions_texts: Vec<String> = permissions_list
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();
    assert!(
        permissions_texts.iter().any(|t| t.contains("Edelmetallen")),
        "Permissions list should contain 'Edelmetallen'.\nActual items: {:?}",
        permissions_texts
    );
    assert!(
        permissions_texts
            .iter()
            .any(|t| t.contains("Überweisungen auf das Referenzkonto")),
        "Permissions list should contain 'Überweisungen auf das Referenzkonto'.\nActual items: {:?}",
        permissions_texts
    );
}

/// Debug test: inspect where "Depotaufstellungen" and "Dispositionen zu eigenen Gunsten" end up
/// after each pipeline stage to understand why they're not in the expected lists.
#[test]
fn debug_bage_list_detection() {
    use crate::document::modules::AnalysisModule;
    use crate::document::modules::{
        CheckboxContentDetector, CheckboxDetector, DateFieldDetector, FieldGrouper,
        FieldTableDetector, HeadingDetector, InlineFieldDatePicker, ListDetector,
        MasterPageDetector, NoPrintDetector, PlaceholderFilter, RadioButtonContentDetector,
        RadioButtonDetector, RadioButtonGrouper, SelectionInlineFieldDetector,
        StandaloneMarkerMerger, TableDetector, TextBlockGrouper, TextBlockMerger,
    };
    use crate::document::{Document, GroupKind};

    let mut bp = Blueprint::from_pdf(input_path("BAGE_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let first_state = states.iter().next().unwrap();
    let flattened = &first_state.flattened;

    let search_terms = [
        "Depotaufstellungen",
        "Rechnungsabschlüsse",
        "Dispositionen zu eigenen Gunsten",
        "Barabhebungen",
        "Ausführung von Wertpapier",
        "Kommunikation und Informationsbeschaffung",
        "Die Vollmacht berechtigt nicht",
    ];

    let mut doc = Document::from_flattened(flattened);

    // Helper to print text blocks containing our terms
    let print_relevant = |doc: &Document, stage: &str| {
        eprintln!("\n=== {} ===", stage);
        let roots = doc.roots();
        for &idx in &roots {
            let text = doc.get_text_content(idx);
            for term in &search_terms {
                if text.contains(*term) {
                    let kind = &doc.groups[idx].kind;
                    let bounds = doc.get_bounds(idx);
                    let is_bold = doc.is_bold_group(idx);
                    eprintln!("  [{idx}] kind={kind:?}, bold={is_bold}, bounds={bounds:?}");
                    let preview: String = text.chars().take(150).collect();
                    eprintln!("    text: \"{preview}...\"");
                    break;
                }
            }
        }
    };

    NoPrintDetector::new().process(&mut doc);
    MasterPageDetector::new().process(&mut doc);
    TextBlockGrouper::new().process(&mut doc);

    // After TextBlockGrouper: look for standalone dash markers near our search terms
    eprintln!("\n=== Standalone markers after TextBlockGrouper ===");
    let roots = doc.roots();
    for &idx in &roots {
        let text = doc.get_text_content(idx);
        let trimmed = text.trim();
        // Look for standalone markers (just "–" or "-" etc.)
        if trimmed.len() <= 3
            && (trimmed.contains('–') || trimmed.contains('-') || trimmed.contains('*'))
        {
            let bounds = doc.get_bounds(idx);
            eprintln!("  [{idx}] standalone marker: \"{trimmed}\" bounds={bounds:?}");
        }
    }

    // Also print all TextBlocks in the y-range of "Depotaufstellungen" (y ≈ 1279)
    eprintln!("\n=== TextBlocks near y=1279 (Depotaufstellungen area) ===");
    for &idx in &roots {
        if let Some(bounds) = doc.get_bounds(idx) {
            let y: f64 = bounds.y.try_into().unwrap_or(0.0);
            if y > 1270.0 && y < 1310.0 {
                let text = doc.get_text_content(idx);
                let kind = &doc.groups[idx].kind;
                eprintln!(
                    "  [{idx}] y={y:.1}, kind={kind:?}, text=\"{}\"",
                    text.chars().take(60).collect::<String>()
                );
            }
        }
    }

    // Print all TextBlocks near y=765 ("Dispositionen" area)
    eprintln!("\n=== TextBlocks near y=756-775 (Dispositionen area) ===");
    for &idx in &roots {
        if let Some(bounds) = doc.get_bounds(idx) {
            let y: f64 = bounds.y.try_into().unwrap_or(0.0);
            if y > 750.0 && y < 785.0 {
                let text = doc.get_text_content(idx);
                let kind = &doc.groups[idx].kind;
                let is_bold = doc.is_bold_group(idx);
                eprintln!(
                    "  [{idx}] y={y:.1}, kind={kind:?}, bold={is_bold}, text=\"{}\"",
                    text.chars().take(80).collect::<String>()
                );
            }
        }
    }

    print_relevant(&doc, "After TextBlockGrouper");

    PlaceholderFilter::new().process(&mut doc);
    FieldGrouper::new().process(&mut doc);
    DateFieldDetector::new().process(&mut doc);
    InlineFieldDatePicker::new().process(&mut doc);
    StandaloneMarkerMerger::new().process(&mut doc);
    print_relevant(&doc, "After StandaloneMarkerMerger");

    RadioButtonDetector::new().process(&mut doc);
    CheckboxDetector::new().process(&mut doc);

    // Debug state before ListDetector - print ALL roots in y range 600-850
    print_relevant(&doc, "Before ListDetector");
    eprintln!("\n=== ALL roots y=600-850 before ListDetector ===");
    {
        let roots = doc.roots();
        for &idx in &roots {
            if let Some(bounds) = doc.get_bounds(idx) {
                let y: f64 = bounds.y.try_into().unwrap_or(0.0);
                if y > 600.0 && y < 850.0 {
                    let text = doc.get_text_content(idx);
                    let kind = &doc.groups[idx].kind;
                    let is_bold = doc.is_bold_group(idx);
                    eprintln!(
                        "  [{idx}] y={y:.1}, h={:.1}, kind={kind:?}, bold={is_bold}, text=\"{}\"",
                        bounds.height.to_f64().unwrap_or(0.0),
                        text.chars().take(80).collect::<String>()
                    );
                }
            }
        }
    }

    ListDetector::new().process(&mut doc);
    print_relevant(&doc, "After ListDetector");

    // Print lists
    let roots = doc.roots();
    eprintln!("\n=== Lists after ListDetector ===");
    for &idx in &roots {
        if matches!(doc.groups[idx].kind, GroupKind::List { .. }) {
            let list_style = match &doc.groups[idx].kind {
                GroupKind::List { list_style } => list_style,
                _ => unreachable!(),
            };
            let items: Vec<_> = doc.groups[idx]
                .children
                .iter()
                .map(|&c| doc.get_text_content(c))
                .collect();
            eprintln!("  List [{idx}] style={list_style:?}, items={}", items.len());
            for (i, item) in items.iter().enumerate() {
                let preview: String = item.chars().take(80).collect();
                eprintln!("    {i}: \"{preview}\"");
            }
        }
    }

    RadioButtonGrouper::new().process(&mut doc);
    SelectionInlineFieldDetector::new().process(&mut doc);
    RadioButtonContentDetector::new().process(&mut doc);
    CheckboxContentDetector::new().process(&mut doc);
    TableDetector::new().process(&mut doc);
    TextBlockMerger::new().process(&mut doc);
    print_relevant(&doc, "After TextBlockMerger");

    FieldTableDetector::new().process(&mut doc);
    HeadingDetector::default().process(&mut doc);
    print_relevant(&doc, "After HeadingDetector");

    // Print headings to see if "Dispositionen" got merged
    eprintln!("\n=== Headings after HeadingDetector ===");
    let roots = doc.roots();
    for &idx in &roots {
        if matches!(doc.groups[idx].kind, GroupKind::Heading { .. }) {
            let text = doc.get_text_content(idx);
            if text.contains("Bevollmächtigte")
                || text.contains("Dispositionen")
                || text.contains("nicht berechtigt")
            {
                let level = match &doc.groups[idx].kind {
                    GroupKind::Heading { level } => level,
                    _ => unreachable!(),
                };
                let is_bold = doc.is_bold_group(idx);
                eprintln!("  Heading [{idx}] level={level}, bold={is_bold}");
                let preview: String = text.chars().take(200).collect();
                eprintln!("    text: \"{preview}\"");
            }
        }
    }
}

#[test]
fn test_bage_has_no_ordered_list_only_numbered_headings() {
    // BAGE document contains headings that start with numbers (e.g., "1. Vollmacht").
    // These should NOT be parsed as ordered list items - they are section headings.
    // There is also legal text that wrongly gets detected as an ordered list.
    use crate::structured::{ListNode, StructuredNode};

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("BAGE_019_DE.pdf"))
        .expect("Failed to run exhaustive merge on BAGE_019_DE.pdf");

    // Collect all lists from the structured output
    fn collect_lists(nodes: &[StructuredNode]) -> Vec<ListNode> {
        let mut lists = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::List(l) => lists.push(l.clone()),
                StructuredNode::Group(g) => lists.extend(collect_lists(&g.children)),
                StructuredNode::Repeatable(r) => {
                    lists.extend(collect_lists(&[(*r.item).clone()]));
                }
                StructuredNode::Conditional(c) => {
                    lists.extend(collect_lists(&[(*c.content).clone()]));
                }
                StructuredNode::GridLayout(gl) => {
                    let child_nodes: Vec<_> = gl.elements.iter().map(|e| e.node.clone()).collect();
                    lists.extend(collect_lists(&child_nodes));
                }
                _ => {}
            }
        }
        lists
    }

    let lists = collect_lists(&structured_nodes);

    // Check that there are no ordered lists
    let ordered_lists: Vec<_> = lists.iter().filter(|l| l.list_style.is_ordered()).collect();
    assert!(
        ordered_lists.is_empty(),
        "BAGE should have NO ordered lists, but found {} ordered list(s): {:?}",
        ordered_lists.len(),
        ordered_lists
            .iter()
            .map(|l| l
                .items
                .iter()
                .map(|i| i.as_plain_text())
                .collect::<Vec<_>>())
            .collect::<Vec<_>>()
    );

    // Verify there are headings that start with numbers (these should NOT be lists)
    let headings = collect_headings(&structured_nodes);
    let numbered_headings: Vec<_> = headings
        .iter()
        .filter(|(_, text)| {
            text.chars()
                .next()
                .map(|c| c.is_ascii_digit())
                .unwrap_or(false)
        })
        .collect();

    assert!(
        !numbered_headings.is_empty(),
        "BAGE should have headings that start with numbers"
    );

    println!(
        "\n✓ BAGE has no ordered lists, but has {} headings starting with numbers:",
        numbered_headings.len()
    );
    for (level, text) in &numbered_headings {
        println!("  H{}: {}", level, text);
    }
}

/// Regression test: In BAGE T_Indent draws, the "2.", "3.", etc. paragraphs have
/// CSS `margin-left:0pt` which should override the XFA default `marginLeft=14.173pt`.
/// The RichParagraph.margin_left must be `Some(0.0)` (not None) so the renderer
/// uses the CSS value instead of falling back to the XFA default.
#[test]
fn test_bage_tindent_numbers_have_explicit_zero_margin() {
    use crate::flattened::FlattenedNodeKind;

    let mut bp = Blueprint::from_pdf(input_path("BAGE_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states.iter().next().unwrap();
    let flattened = &default_state.flattened;

    // Find all T_Indent paragraph nodes containing "2.", "3.", etc.
    let targets = ["2.", "3.", "4.", "5."];
    let number_nodes: Vec<_> = flattened
        .iter_nodes()
        .filter(|n| {
            if let FlattenedNodeKind::Text {
                content,
                source_name: Some(name),
                ..
            } = &n.kind
            {
                name == "T_Indent" && targets.contains(&content.trim())
            } else {
                false
            }
        })
        .collect();

    assert!(
        !number_nodes.is_empty(),
        "Should find T_Indent nodes with numbered headings"
    );

    for node in &number_nodes {
        if let FlattenedNodeKind::Text { content, .. } = &node.kind {
            let trimmed = content.trim();
            let rt = node
                .rich_text()
                .unwrap_or_else(|| panic!("T_Indent '{}' should have rich text", trimmed));
            // Each split paragraph node should have exactly one paragraph in its rich_text
            assert_eq!(
                rt.paragraphs.len(),
                1,
                "Split node '{}' should have 1 paragraph",
                trimmed
            );
            let para = &rt.paragraphs[0];
            // The "2.", "3.", etc. paragraphs in the BAGE XFA have CSS
            // `margin-left:0pt`, which means RichParagraph.margin_left should
            // be Some(0.0), NOT None. This distinction is critical: Some(0.0)
            // tells the renderer to use 0 margin, while None would cause it to
            // fall back to the XFA default (14.173pt), shifting text to the right.
            assert_eq!(
                para.margin_left,
                Some(0.0),
                "T_Indent '{}' should have explicit CSS margin-left:0pt (Some(0.0)), not None",
                trimmed
            );
        }
    }
}

/// Diagnostic test: BAGE T_Indent first dash should be at the correct Y offset.
/// The draw has two empty `<p><br/></p>` paragraphs followed by dash `<p>–</p>`.
/// The first dash must align with the corresponding text in T_The_Authorized.
#[test]
fn test_bage_t_indent_first_dash_y_alignment() {
    use crate::flattened::FlattenedNodeKind;

    let mut bp = Blueprint::from_pdf(input_path("BAGE_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Find the T_The_Authorized nodes
    let t_auth_nodes: Vec<_> = flattened
        .iter_nodes()
        .filter(|n| {
            if let FlattenedNodeKind::Text { source_name, .. } = &n.kind {
                source_name
                    .as_ref()
                    .map(|s| s == "T_The_Authorized")
                    .unwrap_or(false)
            } else {
                false
            }
        })
        .collect();

    // Find the T_Indent nodes
    let t_indent_nodes: Vec<_> = flattened
        .iter_nodes()
        .filter(|n| {
            if let FlattenedNodeKind::Text { source_name, .. } = &n.kind {
                source_name
                    .as_ref()
                    .map(|s| s == "T_Indent")
                    .unwrap_or(false)
            } else {
                false
            }
        })
        .collect();

    // Look for the STP_Declaration3 section
    let vollmacht_node = t_auth_nodes.iter().find(|n| {
        if let FlattenedNodeKind::Text { content, .. } = &n.kind {
            content.contains("Die Vollmacht berechtigt nicht")
        } else {
            false
        }
    });

    if let Some(vn) = vollmacht_node {
        let vollmacht_y = vn.y.to_f32().unwrap_or(0.0);

        // Find T_The_Authorized paragraphs in this section
        let auth_section: Vec<_> = t_auth_nodes
            .iter()
            .filter(|n| {
                n.y.to_f32().unwrap_or(0.0) >= vollmacht_y - 1.0
                    && n.y.to_f32().unwrap_or(0.0) < vollmacht_y + 200.0
            })
            .collect();
        println!("\nT_The_Authorized section:");
        for (i, node) in auth_section.iter().enumerate() {
            if let FlattenedNodeKind::Text { content, .. } = &node.kind {
                let trimmed = content.trim();
                let display: String = trimmed.chars().take(70).collect();
                let display = if display.is_empty() {
                    "(empty)".to_string()
                } else {
                    display
                };
                println!(
                    "  auth[{}] y={:.3} '{}'",
                    i,
                    node.y.to_f32().unwrap_or(0.0),
                    display
                );
            }
        }

        // Find T_Indent paragraphs in same y range
        let indent_section: Vec<_> = t_indent_nodes
            .iter()
            .filter(|n| {
                n.y.to_f32().unwrap_or(0.0) >= vollmacht_y - 1.0
                    && n.y.to_f32().unwrap_or(0.0) < vollmacht_y + 200.0
            })
            .collect();
        println!("\nT_Indent section:");
        for (i, node) in indent_section.iter().enumerate() {
            if let FlattenedNodeKind::Text { content, .. } = &node.kind {
                let trimmed = content.trim();
                let display = if trimmed.is_empty() {
                    "(empty)"
                } else {
                    trimmed
                };
                let has_runs = node
                    .rich_text()
                    .map(|rt| rt.paragraphs.iter().any(|p| !p.runs.is_empty()))
                    .unwrap_or(false);
                println!(
                    "  indent[{}] y={:.3} '{}' runs_present={}",
                    i,
                    node.y.to_f32().unwrap_or(0.0),
                    display,
                    has_runs,
                );
            }
        }

        // Check alignment
        let dispositionen_node = auth_section.iter().find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("Dispositionen")
            } else {
                false
            }
        });
        let first_dash_node = indent_section.iter().find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.trim() == "–"
            } else {
                false
            }
        });

        if let (Some(disp_node), Some(dash_node)) = (dispositionen_node, first_dash_node) {
            let disp_y = disp_node.y.to_f32().unwrap_or(0.0);
            let dash_y = dash_node.y.to_f32().unwrap_or(0.0);
            println!("\n'Dispositionen...' y={:.3}", disp_y);
            println!("First dash '–'     y={:.3}", dash_y);
            println!("Difference: {:.3} (should be 0)", dash_y - disp_y);

            assert!(
                (dash_y - disp_y).abs() < 1.0,
                "First dash (y={:.3}) should align with 'Dispositionen...' (y={:.3}), off by {:.3}pt",
                dash_y,
                disp_y,
                dash_y - disp_y
            );
        }
    }
}

/// Regression test: In BAGE DE, the communication paragraph containing
/// "Kommunikationskanal" should wrap to two lines in Acrobat with a
/// hyphenated split ("Kommunikationska-" / "nal").
///
/// This test targets the XFA -> flattened text layout inputs by taking the
/// flattened rich text paragraph and running the same rich-text line layout.
#[test]
fn test_bage_communication_paragraph_wraps_to_two_lines_with_hyphenation() {
    use crate::flattened::{FlattenedNodeKind, RichText};
    use crate::xfa::text_metrics::TextMeasurer;
    use rust_decimal::prelude::ToPrimitive;

    let mut bp = Blueprint::from_pdf(input_path("BAGE_019_DE.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Locate the specific communication paragraph in flattened output.
    let target_node = flattened
        .iter_nodes()
        .find(|n| {
            if let FlattenedNodeKind::Text { content, .. } = &n.kind {
                content.contains("Kommunikation zwischen UBS und dem Bevoll")
                    && content.contains("Digital Banking")
                    && content.contains("unterzeichnen")
            } else {
                false
            }
        })
        .expect("Should find BAGE communication paragraph text node");

    let rich = target_node
        .rich_text()
        .expect("Target node should carry rich text");
    let target_para = rich
        .paragraphs
        .iter()
        .find(|p| {
            let text = p
                .runs
                .iter()
                .map(|r| r.text.as_str())
                .collect::<Vec<_>>()
                .join("");
            text.contains("Kommunikation zwischen UBS und dem Bevoll")
                && text.contains("Digital Banking")
                && text.contains("unterzeichnen")
        })
        .cloned()
        .expect("Target paragraph should exist in rich text");

    let single_para = RichText {
        paragraphs: vec![target_para],
    };

    let xfa_font = target_node.style.font.clone().unwrap_or_default();
    let font_size = if let FlattenedNodeKind::Text { font_size, .. } = &target_node.kind {
        font_size.to_f32().unwrap_or(10.0)
    } else {
        10.0
    };

    // Match flattened renderer content width handling (border margins).
    let border_left = target_node
        .style
        .border
        .as_ref()
        .and_then(|b| b.margin_left)
        .and_then(|v| v.to_f32())
        .unwrap_or(0.0);
    let border_right = target_node
        .style
        .border
        .as_ref()
        .and_then(|b| b.margin_right)
        .and_then(|v| v.to_f32())
        .unwrap_or(0.0);
    let content_w =
        (target_node.width.to_f32().unwrap_or(0.0) - border_left - border_right).max(0.0);
    assert!(
        content_w > 0.0,
        "Target node content width must be positive, got {}",
        content_w
    );

    let letter_spacing = xfa_font
        .letter_spacing
        .and_then(|ls| ls.to_f32())
        .unwrap_or(0.0);

    let mut measurer = TextMeasurer::new();
    let font = measurer
        .get_font_for_style(&xfa_font)
        .expect("Should resolve font for target paragraph")
        .clone();

    let hyph_settings = target_node
        .style
        .para
        .as_ref()
        .and_then(|p| p.hyphenation.as_ref());

    // Use the German hyphenation dictionary, matching the pipeline's
    // split_draw_into_paragraph_nodes which calls dict_for_language(language).
    let hyph_dict = crate::xfa::hyphenation::dict_for_language("de");

    let rendered_lines = crate::flattened::Flattened::layout_rich_text(
        &single_para,
        content_w,
        font_size,
        &font,
        1.0,
        letter_spacing,
        hyph_settings,
        hyph_dict,
    );

    let line_texts: Vec<String> = rendered_lines
        .iter()
        .filter(|l| !l.words.is_empty())
        .map(|l| {
            l.words
                .iter()
                .map(|w| w.text.as_str())
                .collect::<Vec<_>>()
                .join(" ")
        })
        .collect();

    assert_eq!(
        line_texts.len(),
        2,
        "Expected Acrobat-like two-line wrap for BAGE communication paragraph, got {} lines: {:?}",
        line_texts.len(),
        line_texts
    );

    assert!(
        line_texts.iter().any(|l| l.contains("Kommunikationska-")),
        "Expected hyphenated split 'Kommunikationska-' in first/second line, got: {:?}",
        line_texts
    );
    assert!(
        line_texts.iter().any(|l| l.contains("nal")),
        "Expected continuation 'nal' after hyphen split, got: {:?}",
        line_texts
    );
}

/// Regression test: In BAGE DE, the two communication paragraphs in the
/// "Kommunikation und Informationsbeschaffung" section must be detected as
/// separate paragraphs (separated by one line-height gap in the XFA layout).
///
/// Paragraph 1: "Für die Kommunikation zwischen UBS und dem Bevollmächtigten ..."
/// Paragraph 2: "Als Kommunikationskanäle stehen unter anderem ..."
///
/// They must NOT be merged into a single paragraph.
#[test]
fn test_bage_communication_two_paragraphs_are_separate() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::StructuredNode;

    let doc = run_exhaustive_to_envelope(input_path("BAGE_019_DE.pdf"), "de")
        .expect("Failed to process BAGE_019_DE");

    // Collect all paragraph texts
    let mut paragraphs: Vec<String> = Vec::new();
    helpers::walk_structured_nodes(&doc.content, &mut |node| {
        if let StructuredNode::Paragraph(p) = node {
            paragraphs.push(p.content.as_plain_text());
        }
    });

    // Find the paragraph starting with "Für die Kommunikation zwischen UBS"
    let para1 = paragraphs.iter().find(|p| {
        p.contains("Kommunikation zwischen UBS und dem Bevollmächtigten")
            && p.contains("Digital Banking")
            && p.contains("unterzeichnen")
    });
    assert!(
        para1.is_some(),
        "Should find paragraph containing 'Für die Kommunikation zwischen UBS und dem \
         Bevollmächtigten ... unterzeichnen.'\nAll paragraphs: {:?}",
        paragraphs
            .iter()
            .filter(|p| p.contains("Kommunikation") || p.contains("Kommunikationskan"))
            .collect::<Vec<_>>()
    );

    // Find the paragraph starting with "Als Kommunikationskanäle"
    let para2 = paragraphs.iter().find(|p| {
        p.contains("Als Kommunikationskanäle stehen unter anderem")
            && p.contains("Telefax")
            && p.contains("gewahrt werden kann")
    });
    assert!(
        para2.is_some(),
        "Should find paragraph containing 'Als Kommunikationskanäle stehen unter anderem ... \
         gewahrt werden kann.'\nAll paragraphs: {:?}",
        paragraphs
            .iter()
            .filter(|p| p.contains("Kommunikation") || p.contains("Kommunikationskan"))
            .collect::<Vec<_>>()
    );

    // They must be separate paragraphs (not merged into one)
    let merged_exists = paragraphs.iter().any(|p| {
        p.contains("Kommunikation zwischen UBS und dem Bevollmächtigten")
            && p.contains("Als Kommunikationskanäle stehen unter anderem")
    });
    assert!(
        !merged_exists,
        "The two communication paragraphs must NOT be merged into a single paragraph. \
         They are separated by a one-line-height gap in the XFA layout.\n\
         Found merged paragraph: {:?}",
        paragraphs
            .iter()
            .find(|p| p.contains("Kommunikation zwischen UBS")
                && p.contains("Als Kommunikationskanäle"))
    );
}

#[test]
fn test_aari_has_radio_button_with_fiscal_regime_options() {
    use crate::Blueprint;
    use crate::structured::FieldType;

    let mut bp =
        Blueprint::from_pdf(input_path("AARI_033_IT.pdf")).expect("Failed to load AARI_033_IT.pdf");

    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let state = form_states.iter().next().unwrap();
    let envelope = state.structured(ctx);

    let radio_fields = collect_radio_fields(&envelope.content);

    println!("\n=== Radio fields in AARI ===");
    for field in &radio_fields {
        if let FieldType::Radio { options } = &field.input_type {
            println!("  Field: {} ({} options)", field.name, options.len());
            for opt in options {
                println!("    - {}", opt.name);
            }
        }
    }

    // Find a radio button group with 2 options about the fiscal regime
    let fiscal_radio = radio_fields.iter().find(|field| {
        if let FieldType::Radio { options } = &field.input_type {
            options.len() == 2
                && options.iter().any(|opt| {
                    let text = opt.name.to_string();
                    text.contains("voler optare per l")
                        && text.contains("imposizione sostitutiva")
                        && text.contains("Regime Fiscale Amministrato")
                })
                && options.iter().any(|opt| {
                    let text = opt.name.to_string();
                    text.contains("non voler optare per il Regime Fiscale Amministrato")
                })
        } else {
            false
        }
    });

    assert!(
        fiscal_radio.is_some(),
        "Expected a radio button with 2 fiscal regime options:\n\
         1) 'Di voler optare per l'applicazione dell'imposizione sostitutiva ... (Regime Fiscale Amministrato)'\n\
         2) 'Di non voler optare per il Regime Fiscale Amministrato ...'\n\
         Found radio fields: {:#?}",
        radio_fields
            .iter()
            .filter_map(|f| {
                if let FieldType::Radio { options } = &f.input_type {
                    Some(
                        options
                            .iter()
                            .map(|o| o.name.to_string())
                            .collect::<Vec<_>>(),
                    )
                } else {
                    None
                }
            })
            .collect::<Vec<_>>()
    );
}

#[test]
fn test_aaor_has_unordered_list_with_declarations() {
    let structured_nodes = crate::run_exhaustive_to_merged(input_path("AAOR_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on AAOR_033_IT.pdf");

    let lists = helpers::collect_lists(&structured_nodes);

    let expected_items = &[
        // Item 0 has a sublist — its (i)-(v) sub-items are separate TextBlocks
        "di avere ricevuto in tempo utile prima della sottoscrizione del Contratto il documento denominato «Informativa Precontrattuale di UBS Europe SE, Succursale Italia» e un esemplare del Contratto e di aver letto attentamente e di avere già aderito e di aderire nuovamente per iscritto – in segno di integrale accettazione – alle Condizioni Generali di Contratto di cui al «Contratto Unico per la Prestazione di Servizi di Investimento» ed in particolare di accettare le disposizioni contrattuali di cui alle seguenti Sezioni delle Condizioni Generali di Contratto:",
        "di essere consapevole che la presente richiesta di attivazione con i relativi allegati congiuntamente alle Condizioni Generali di Contratto di cui al «Contratto Unico per la Prestazione di Servizi di Investimento» con i relativi allegati costituiscono il Contratto;",
        "di avere letto attentamente e di avere preso atto delle caratteristiche della/e Linea/e di Gestione prescelta/e (sub Allegato 1) ed in particolare di essere stato informato: (i) sul metodo e frequenza della valutazione degli strumenti e/o prodotti finanziari contenuti nel portafoglio del Cliente; (ii) sul parametro di riferimento con il quale verrà raffrontato il rendimento del portafoglio del Cliente; (iii) sui tipi di strumenti finanziari che possono essere inclusi nel portafoglio ed i tipi di operazioni che possono essere realizzate; (iv) sugli obiettivi della gestione, il livello di rischio entro il quale il gestore può esercitare la propria discrezionalità, ed eventuali restrizioni a tale discrezionalità;",
        "di avere letto attentamente e di avere preso atto delle modalità e delle caratteristiche della Delega di Gestione (sub Allegato 1);",
        "di avere letto e accettare le condizioni economiche relative ai servizi richiesti, contenute nel documento «Commissioni e Spese» allegato alla presente richiesta di attivazione (sub Allegato 2);",
        "di avere letto attentamente e di accettare la Strategia di Esecuzione e Trasmissione degli Ordini adottata dalla Banca e contenuta nella sopra menzionata «Informativa Precontrattuale di UBS Europe SE, Succursale Italia», che è stata consegnata al Cliente medesimo prima della firma del Contratto. Il Cliente dichiara, altresì, di essere stato compiutamente informato che eventuali proprie istruzioni specifiche potrebbero comprometterne i risultati;",
        "di avere preso atto e di essere consapevole che in caso di conclusione del presente Contratto fuori sede, l'efficacia dello stesso è sospesa per un periodo di 7 (sette) giorni, decorrenti dalla data di sottoscrizione da parte del Cliente. Entro detto termine, il Cliente può recedere dal Contratto, senza spese e penalità e senza giustificarne il motivo, facendo pervenire alla Banca o al consulente abilitato all'offerta fuori sede (i.e. Client Advisor) una apposita comunicazione scritta;",
        // Item 7 has a sublist — its (i)-(iv) sub-items are separate TextBlocks
        "di essere consapevole del fatto che la presente Richiesta di Attivazione può essere sottoscritta, se tale possibilità è resa disponibile per il Cliente da UBS, mediante tecniche di comunicazione a distanza, quale il servizio E-Signature e che, in tal caso, la Banca utilizza una apposita sezione del servizio Mailbox per la consegna dei seguenti documenti:",
        "di essere altresì consapevole del fatto che la presente richiesta di attivazione può essere sottoscritta, se tale possibilità è resa disponibile per il Cliente da UBS, (i) mediante firma elettronica qualificata (o altra tipologia di firma idonea a integrare il requisito della forma scritta ai sensi della normativa tempo per tempo applicabile) fornita da un provider terzo qualificato ai sensi del Regolamento EIDAS oppure (ii) mediante firma digitale, firma elettronica qualificata, firma elettronica avanzata o altra tipologia di firma idonea a integrare il requisito della forma scritta ai sensi della normativa tempo per tempo applicabile messa a disposizione del Cliente da UBS, anche tramite provider terzi, secondo le modalità e la procedura tempo per tempo comunicate dalla Banca;",
        "di essere stato informato, in conformità con il disposto dell'art. 67-duodecies del Codice del Consumo, del diritto di recedere dal presente Contratto qualora sottoscritto mediante il servizio E-Signature o altra modalità alternativa di sottoscrizione della documentazione, senza penali e senza dover indicare il motivo del recesso, entro il termine di 14 giorni dalla data di conclusione del Contratto stesso;",
        "di essere stato informato, in conformità con il disposto dell'art. 67-terdecies del Codice del Consumo e durante la pendenza del termine per l'esercizio del diritto di recesso, della possibilità di richiedere alla Banca l'avvio immediato del Contratto: in tal caso, il diritto di recesso non si applica qualora gli investimenti siano avviati;",
        "di avere personalmente compilato la presente Richiesta di Attivazione, esprimendo la propria scelta anche con riferimento al \"Regime Fiscale\" e alle \"Operazioni Fuori Mercato\", nonché di aver espresso la propria scelta e consenso attraverso un diverso modulo in relazione a: (i) \"Regime di Cointestazione\"; (ii) \"Consenso al trattamento dei dati personali relativi ai servizi di pagamento\"; (iii) \"Indirizzo di Corrispondenza\"; (iv)\"Eventuali richieste del Cliente e personalizzazioni della Linea di Gestione\".",
    ];

    // Find the unordered list that contains the declaration items
    let declaration_list = lists
        .iter()
        .find(|l| !l.list_style.is_ordered() && l.items.len() == expected_items.len());
    assert!(
        declaration_list.is_some(),
        "AAOR should have an unordered list with {} items, found lists with sizes: {:?}",
        expected_items.len(),
        lists.iter().map(|l| l.items.len()).collect::<Vec<_>>()
    );

    let list = declaration_list.unwrap();
    for (i, expected) in expected_items.iter().enumerate() {
        let actual = list.items[i].as_plain_text();
        assert_eq!(actual.trim(), *expected, "List item {} mismatch", i);
    }

    // Item 7 should have a LowerRoman sublist with 4 items
    let item7 = &list.items[7];
    assert!(
        item7.sublist.is_some(),
        "Item 7 should have a sublist with (i)-(iv) sub-items"
    );
    let sublist = item7.sublist.as_ref().unwrap();
    assert_eq!(
        sublist.list_style,
        crate::document::ListStyleType::LowerRoman,
        "Sublist should be LowerRoman"
    );
    assert_eq!(sublist.items.len(), 4, "Sublist should have 4 items");
    assert!(
        sublist.items[0]
            .as_plain_text()
            .contains("documentazione informativa")
    );
}

#[test]
fn test_abfh_regime_fiscale_radio_button() {
    use crate::run_exhaustive_to_merged;
    use crate::structured::FieldType;

    let structured = run_exhaustive_to_merged(input_path("ABFH_033_IT.pdf"))
        .expect("Failed to run exhaustive merge for ABFH");

    let radios = collect_radio_fields(&structured);
    assert!(
        !radios.is_empty(),
        "ABFH should have at least one radio field"
    );

    let regime_radio = radios
        .iter()
        .find(|f| {
            if let FieldType::Radio { options } = &f.input_type {
                options
                    .iter()
                    .any(|o| o.name.contains("Regime Fiscale Amministrato"))
            } else {
                false
            }
        })
        .expect("Expected to find a radio field with 'Regime Fiscale Amministrato' option");

    let options = match &regime_radio.input_type {
        FieldType::Radio { options } => options,
        other => panic!("Field should be of type 'radio', got {:?}", other),
    };

    assert_eq!(
        options.len(),
        2,
        "Expected 2 radio button options, found {}",
        options.len()
    );

    let option_names: Vec<&str> = options.iter().map(|o| o.name.as_str()).collect();

    let expected_options = [
        "di voler optare per l'applicazione dell'imposizione sostitutiva nella misura prevista dalla normativa pro-tempore vigente su ciascuna plusvalenza o altro reddito diverso realizzato (Regime Fiscale Amministrato);",
        "di non voler optare per il Regime Fiscale Amministrato. Il Cliente dichiara, altres\u{ec}, di essere a conoscenza che, in tal caso, sar\u{e0} tenuto al regime ordinario di tassazione e quindi a dover ottemperare individualmente a tutti gli obblighi impositivi.",
    ];

    for expected in &expected_options {
        let found = option_names.iter().any(|name| name.contains(expected));
        assert!(
            found,
            "Expected to find radio option containing '{}'\nFound options: {:?}",
            expected, option_names
        );
    }
}

#[test]
fn test_abfh_has_two_lists_roman_and_alpha() {
    use crate::document::ListStyleType;

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("ABFH_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on ABFH_033_IT.pdf");

    let lists = helpers::collect_lists(&structured_nodes);

    // --- Roman numeral list: (i) through (iv) ---
    let roman_list = lists.iter().find(|l| {
        l.items
            .iter()
            .any(|item| item.as_plain_text().contains("Servizi Amministrati"))
    });

    assert!(
        roman_list.is_some(),
        "Expected a roman numeral list containing 'Servizi Amministrati'.\nFound lists: {:?}",
        lists
            .iter()
            .map(|l| l
                .items
                .iter()
                .map(|i| i.as_plain_text())
                .collect::<Vec<_>>())
            .collect::<Vec<_>>()
    );

    let roman_list = roman_list.unwrap();

    assert_eq!(
        roman_list.list_style,
        ListStyleType::LowerRoman,
        "The (i)–(iv) list should be detected as LowerRoman"
    );

    assert_eq!(
        roman_list.items.len(),
        4,
        "Expected 4 items in roman numeral list, got {}.\nItems: {:?}",
        roman_list.items.len(),
        roman_list
            .items
            .iter()
            .map(|i| i.as_plain_text())
            .collect::<Vec<_>>()
    );

    let roman_texts: Vec<String> = roman_list.items.iter().map(|i| i.as_plain_text()).collect();

    // Verify that the parenthesized roman numeral prefix is stripped from each item.
    for (idx, text) in roman_texts.iter().enumerate() {
        let trimmed = text.trim();
        assert!(
            !trimmed.starts_with("(i)")
                && !trimmed.starts_with("(ii)")
                && !trimmed.starts_with("(iii)")
                && !trimmed.starts_with("(iv)"),
            "Roman numeral prefix was not stripped from item {}.\nFound: {}",
            idx,
            text
        );
    }

    assert!(
        roman_texts[0].contains("Servizi Amministrati")
            && roman_texts[0].contains("ricezione e trasmissione ordini"),
        "First item should mention 'Servizi Amministrati' and 'ricezione e trasmissione ordini'.\nFound: {}",
        roman_texts[0]
    );
    assert!(
        roman_texts[1].contains("intermediazione assicurativa"),
        "Second item should mention 'intermediazione assicurativa'.\nFound: {}",
        roman_texts[1]
    );
    assert!(
        roman_texts[2].contains("Servizi Bancari accessori"),
        "Third item should mention 'Servizi Bancari accessori'.\nFound: {}",
        roman_texts[2]
    );
    assert!(
        roman_texts[3].contains("Servizi di Pagamento accessori"),
        "Fourth item should mention 'Servizi di Pagamento accessori'.\nFound: {}",
        roman_texts[3]
    );

    // --- Alpha list: a)–d) cessione / rapporti items ---
    let alpha_list = lists.iter().find(|l| {
        l.items.iter().any(|item| {
            item.as_plain_text()
                .contains("cessione a titolo oneroso di partecipazioni")
        })
    });

    assert!(
        alpha_list.is_some(),
        "Expected an alpha list containing 'cessione a titolo oneroso di partecipazioni'.\nFound lists: {:?}",
        lists
            .iter()
            .map(|l| l
                .items
                .iter()
                .map(|i| i.as_plain_text())
                .collect::<Vec<_>>())
            .collect::<Vec<_>>()
    );

    let alpha_list = alpha_list.unwrap();

    assert_eq!(
        alpha_list.list_style,
        ListStyleType::LowerAlpha,
        "The a)–d) list should be detected as LowerAlpha"
    );

    assert_eq!(
        alpha_list.items.len(),
        4,
        "Expected 4 items in alpha list, got {}.\nItems: {:?}",
        alpha_list.items.len(),
        alpha_list
            .items
            .iter()
            .map(|i| i.as_plain_text())
            .collect::<Vec<_>>()
    );

    let alpha_texts: Vec<String> = alpha_list.items.iter().map(|i| i.as_plain_text()).collect();

    assert!(
        alpha_texts.iter().any(|t| t
            .contains("cessione a titolo oneroso di partecipazioni qualificate e non qualificate")),
        "List should contain item about 'partecipazioni qualificate e non qualificate'.\nItems: {:?}",
        alpha_texts
    );
    assert!(
        alpha_texts.iter().any(|t| t.contains(
            "cessione a titolo oneroso ovvero rimborso di titoli non rappresentativi di merci"
        )),
        "List should contain item about 'rimborso di titoli non rappresentativi di merci'.\nItems: {:?}",
        alpha_texts
    );
    assert!(
        alpha_texts
            .iter()
            .any(|t| t.contains("rapporti da cui deriva il diritto o l")
                && t.contains("obbligo di cedere o acquistare a termine strumenti finanziari")),
        "List should contain item about 'rapporti da cui deriva il diritto o l'obbligo'.\nItems: {:?}",
        alpha_texts
    );
    assert!(
        alpha_texts.iter().any(|t| t.contains("cessione, a titolo oneroso ovvero chiusura di rapporti produttivi di redditi di capitale")),
        "List should contain item about 'chiusura di rapporti produttivi di redditi di capitale'.\nItems: {:?}",
        alpha_texts
    );
}

#[test]
fn test_aacx_nested_lists_structure() {
    // AACX_033_IT has a deeply nested list structure:
    //
    //   – «Legge» ...
    //   – «FINRA» ...
    //   – «SEC» ...
    //   – «Consulenza relativa a titoli» indica:
    //       a) la fornitura di servizi discrezionali di asset management;
    //       b) comunicazioni in merito a
    //           (i) l'opportunità di acquistare ...
    //           ...
    //           (vi) selezione o mantenimento di altri consulenti di investimento; e
    //       c) la fornitura di strumenti elettronici ...
    //   – «Stati Uniti» o «USA» indicano ...   ← same dash list, after the sublist
    //   – «Categorie di US Person» indica ...
    //       (i) qualsiasi persona fisica ...
    //       ...
    //
    // The test verifies:
    //   1) The dash list includes items both before and after the alpha sublist
    //   2) «Consulenza» has a lower-alpha sublist
    //   3) Alpha item b) has a lower-roman sublist
    //   4) List continuity: «Stati Uniti» appears in the same dash list as
    //      «Consulenza», proving the dash list resumes after the alpha sublist
    use crate::document::ListStyleType;
    use crate::structured::{ListNode, StructuredNode};

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("AACX_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on AACX_033_IT.pdf");

    fn collect_lists(nodes: &[StructuredNode]) -> Vec<ListNode> {
        let mut lists = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::List(l) => lists.push(l.clone()),
                StructuredNode::Group(g) => lists.extend(collect_lists(&g.children)),
                StructuredNode::Repeatable(r) => {
                    lists.extend(collect_lists(&[(*r.item).clone()]));
                }
                StructuredNode::Conditional(c) => {
                    lists.extend(collect_lists(&[(*c.content).clone()]));
                }
                StructuredNode::GridLayout(gl) => {
                    let child_nodes: Vec<_> = gl.elements.iter().map(|e| e.node.clone()).collect();
                    lists.extend(collect_lists(&child_nodes));
                }
                _ => {}
            }
        }
        lists
    }

    let lists = collect_lists(&structured_nodes);

    // ── 1. Dash (unordered) definitions list ──────────────────────────
    // Find the dash list that contains the «Consulenza» item.
    let dash_list = lists
        .iter()
        .find(|l| {
            !l.list_style.is_ordered()
                && l.items.iter().any(|i| {
                    i.as_plain_text()
                        .contains("Consulenza relativa a titoli\u{bb} indica")
                })
        })
        .expect(
            "Expected an unordered list containing the 'Consulenza relativa a titoli' definition",
        );

    let dash_texts: Vec<String> = dash_list.items.iter().map(|i| i.as_plain_text()).collect();

    // Well-known items that appear before «Consulenza»
    assert!(
        dash_texts.iter().any(|t| t.contains("FINRA")),
        "Dash list should contain «FINRA».\nItems: {:?}",
        dash_texts
    );
    assert!(
        dash_texts.iter().any(|t| t.contains("SEC")),
        "Dash list should contain «SEC».\nItems: {:?}",
        dash_texts
    );

    // «Stati Uniti» must appear in the SAME dash list, after the alpha sublist
    assert!(
        dash_texts
            .iter()
            .any(|t| t.contains("Stati Uniti") && t.contains("USA")),
        "Dash list should contain «Stati Uniti» o «USA» — the dash list must \
         resume after the alpha sublist of «Consulenza».\nItems: {:?}",
        dash_texts
    );

    // ── 2. «Consulenza» → alpha sublist ───────────────────────────────
    let consulenza_item = dash_list
        .items
        .iter()
        .find(|i| {
            i.as_plain_text()
                .contains("Consulenza relativa a titoli\u{bb} indica")
        })
        .expect("Dash list must contain the 'Consulenza relativa a titoli' definition item");

    let alpha_sublist = consulenza_item
        .sublist
        .as_ref()
        .expect("'Consulenza relativa a titoli' should have a lower-alpha sublist");

    assert_eq!(
        alpha_sublist.list_style,
        ListStyleType::LowerAlpha,
        "Sublist of 'Consulenza' should be LowerAlpha, got {:?}",
        alpha_sublist.list_style
    );
    assert!(
        alpha_sublist.items.len() >= 3,
        "Alpha sublist should have at least 3 items (a, b, c), found {}",
        alpha_sublist.items.len()
    );

    let alpha_texts: Vec<String> = alpha_sublist
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();

    // a) is about discretionary asset management
    assert!(
        alpha_texts
            .first()
            .is_some_and(|t| t.contains("fornitura di servizi discrezionali di asset management")),
        "Alpha a) should be about discretionary asset management.\nItems: {:?}",
        alpha_texts
    );
    // c) is about electronic tools — must stay in the alpha list even though
    // there is a nested roman sublist between b) and c).
    assert!(
        alpha_texts
            .last()
            .is_some_and(|t| t.contains("fornitura di strumenti elettronici")),
        "Alpha c) should be about electronic tools.\nItems: {:?}",
        alpha_texts
    );

    // ── 3. Alpha b) → roman sublist ──────────────────────────────────
    let comunicazioni_item = alpha_sublist
        .items
        .iter()
        .find(|i| i.as_plain_text().contains("comunicazioni in merito"))
        .expect("Alpha sublist should contain b) 'comunicazioni in merito a'");

    let roman_sublist = comunicazioni_item
        .sublist
        .as_ref()
        .expect("Alpha b) 'comunicazioni in merito a' should have a roman sublist");

    assert_eq!(
        roman_sublist.list_style,
        ListStyleType::LowerRoman,
        "Sublist of b) should be LowerRoman, got {:?}",
        roman_sublist.list_style
    );
    assert!(
        roman_sublist.items.len() >= 5,
        "Roman sublist should have at least 5 items (i–vi), found {}",
        roman_sublist.items.len()
    );

    let roman_texts: Vec<String> = roman_sublist
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();

    assert!(
        roman_texts
            .first()
            .is_some_and(|t| t.contains("opportunit")),
        "Roman (i) should mention 'opportunità'.\nRoman items: {:?}",
        roman_texts
    );
    assert!(
        roman_texts
            .last()
            .is_some_and(|t| t.contains("selezione o mantenimento di altri consulenti")),
        "Roman (vi) should be about selecting/maintaining other advisors.\nRoman items: {:?}",
        roman_texts
    );

    // ── 4. «Categorie di US Person» → roman sublist ──────────────────
    // «Categorie di US Person» should have a lower-roman sublist starting
    // with "qualsiasi persona fisica domiciliata negli USA;"
    let categorie_dash_list = lists
        .iter()
        .find(|l| {
            !l.list_style.is_ordered()
                && l.items.iter().any(|i| {
                    i.as_plain_text()
                        .contains("Categorie di US Person\u{bb} indica")
                })
        })
        .expect("Expected an unordered list containing the 'Categorie di US Person' definition");

    let categorie_item = categorie_dash_list
        .items
        .iter()
        .find(|i| {
            i.as_plain_text()
                .contains("Categorie di US Person\u{bb} indica")
        })
        .expect("Dash list must contain the 'Categorie di US Person' definition item");

    let categorie_sublist = categorie_item
        .sublist
        .as_ref()
        .expect("'Categorie di US Person' should have a lower-roman sublist");

    assert_eq!(
        categorie_sublist.list_style,
        ListStyleType::LowerRoman,
        "Sublist of 'Categorie di US Person' should be LowerRoman, got {:?}",
        categorie_sublist.list_style
    );

    let categorie_roman_texts: Vec<String> = categorie_sublist
        .items
        .iter()
        .map(|i| i.as_plain_text())
        .collect();

    assert!(
        categorie_roman_texts
            .first()
            .is_some_and(|t| t.contains("qualsiasi persona fisica domiciliata negli USA")),
        "'Categorie di US Person' roman (i) should be 'qualsiasi persona fisica domiciliata negli USA'.\nItems: {:?}",
        categorie_roman_texts
    );
}

/// Verify that the font weight selection for mixed bold/normal paragraphs
/// uses the dominant weight. This prevents a short bold prefix from inflating
/// text width measurements, which would cause incorrect wrapping and
/// misalignment in overlapping Draw columns (AACX STP_Definitions_1).
#[test]
fn test_aacx_overlapping_draw_paragraph_alignment() {
    let mut bp = Blueprint::from_pdf(input_path("AACX_033_IT.pdf")).unwrap();
    let states = bp.states().unwrap();
    let default_state = states
        .iter()
        .next()
        .expect("should have at least one state");
    let flattened = &default_state.flattened;

    // Collect Text and Indent columns from STP_Definitions_1
    let mut text_col: Vec<(f32, f32, String)> = Vec::new(); // (y, h, content)
    let mut indent_col: Vec<(f32, f32, String)> = Vec::new();

    for node in flattened.iter_nodes() {
        if let crate::FlattenedNodeKind::Text { content, .. } = &node.kind {
            let som = node
                .som_path()
                .map(|p| p.as_str().to_string())
                .unwrap_or_default();
            if !som.contains("STP_Definitions_1") {
                continue;
            }
            let y = node.y.to_f32().unwrap_or(0.0);
            let h = node.height.to_f32().unwrap_or(0.0);
            let entry = (y, h, content.clone());
            if som.contains(".Text") {
                text_col.push(entry);
            } else if som.contains("T_Indent") || som.contains(".Indent") {
                indent_col.push(entry);
            }
        }
    }

    text_col.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());
    indent_col.sort_by(|a, b| a.0.partial_cmp(&b.0).unwrap());

    assert!(
        text_col.len() >= 10,
        "Expected at least 10 text paragraphs, got {}",
        text_col.len()
    );
    assert!(
        indent_col.len() >= 10,
        "Expected at least 10 indent markers, got {}",
        indent_col.len()
    );

    // The first 3 paragraphs (before any wrapping) must be aligned.
    for i in 0..3 {
        let (ty, _, ref tc) = text_col[i];
        let (iy, _, ref ic) = indent_col[i];
        assert!(
            (ty - iy).abs() < 0.5,
            "Paragraph {}: text y={:.1} ({:?}) != indent y={:.1} ({:?})",
            i,
            ty,
            &tc[..tc.len().min(40)],
            iy,
            &ic[..ic.len().min(20)]
        );
    }

    // text[3] is the «Servizi di esecuzione titoli» paragraph — it wraps
    // but with correct font weight selection it should wrap to at most 2 lines
    // (h ≤ 18pt), not 3 lines (h=27pt) which was the bug.
    let (_, th3, ref tc3) = text_col[3];
    assert!(
        tc3.contains("Servizi di esecuzione titoli"),
        "text[3] should be the 'Servizi' paragraph, got {:?}",
        &tc3[..tc3.len().min(60)]
    );
    assert!(
        th3 <= 19.0,
        "text[3] ('Servizi...') should wrap to at most 2 lines (h≤18pt), got h={:.1}pt. \
         If h=27, the bold font is being used for measurement instead of the dominant normal font.",
        th3
    );
}

