#[test]
fn test_aacx_zip_structured_output() {
    use crate::structured::StructuredNode;

    let zip_bytes = std::fs::read(input_path("AACX.zip")).expect("Failed to read AACX.zip");
    let bp = Blueprint::from_aem_zip(&zip_bytes).expect("Failed to parse AACX.zip");
    let envelope = bp
        .aem_structured()
        .expect("Failed to get AEM structured output");
    let nodes = &envelope.content;

    // Collect all field labels
    let fields = collect_fields(nodes);
    let labels: Vec<String> = fields
        .iter()
        .filter_map(|f| f.label.as_ref().map(|l| l.as_plain_text()))
        .collect();

    // 1) Must contain a field with label "Tipo"
    let tipo_field = fields.iter().find(|f| {
        f.label
            .as_ref()
            .map(|l| l.as_plain_text().contains("Tipo"))
            .unwrap_or(false)
    });
    assert!(
        tipo_field.is_some(),
        "Expected a field with label 'Tipo', but none found.\nAll labels: {:?}",
        labels
    );

    // 2) Must contain a field "Nome della società"
    let nome_societa = fields.iter().find(|f| {
        f.label
            .as_ref()
            .map(|l| l.as_plain_text().contains("Nome della societ"))
            .unwrap_or(false)
    });
    assert!(
        nome_societa.is_some(),
        "Expected a field with label containing 'Nome della società', but none found.\nAll labels: {:?}",
        labels
    );

    // 3) Must contain a Repeatable that includes fields "Cognome" and "Nome/i"
    let mut repeatables = Vec::new();
    walk_structured_nodes(nodes, &mut |node| {
        if let StructuredNode::Repeatable(rep) = node {
            repeatables.push(rep.clone());
        }
    });

    assert!(
        !repeatables.is_empty(),
        "Expected at least one Repeatable node in AACX, but found none"
    );

    // Check that some repeatable contains both "Cognome" and "Nome/i" (Italian translations)
    let has_matching_repeatable = repeatables.iter().any(|rep| {
        let rep_fields = collect_fields(std::slice::from_ref(&StructuredNode::Repeatable(
            rep.clone(),
        )));

        let has_cognome = rep_fields.iter().any(|f| {
            f.label.as_ref().is_some_and(|l| {
                l.as_plain_text().contains("Cognome")
                    || l.plain_text_in("it").contains("Cognome")
                    || l.plain_text_in("it-ch").contains("Cognome")
            })
        });
        let has_nomi = rep_fields.iter().any(|f| {
            f.label.as_ref().is_some_and(|l| {
                let plain = l.as_plain_text();
                let it = l.plain_text_in("it");
                let it_ch = l.plain_text_in("it-ch");
                plain.contains("Nome")
                    || it.contains("Nome")
                    || it_ch.contains("Nome")
                    || plain.contains("First name")
                    || it.contains("First name")
            })
        });
        has_cognome && has_nomi
    });

    assert!(
        has_matching_repeatable,
        "Expected a Repeatable containing fields 'Cognome' and 'Nome/i', but none found.\n\
         Repeatables found: {}",
        repeatables.len()
    );
}

#[test]
fn test_aaox_zip_structured_output() {
    use crate::structured::{ConditionalNode, InputValue, StructuredNode};

    let zip_bytes = std::fs::read(input_path("AAOX.zip")).expect("Failed to read AAOX.zip");
    let bp = Blueprint::from_aem_zip(&zip_bytes).expect("Failed to parse AAOX.zip");
    let envelope = bp
        .aem_structured()
        .expect("Failed to get AEM structured output");
    let nodes = &envelope.content;

    // Helper: check if a label matches text in any Italian variant
    let label_contains = |label: &crate::structured::TranslatedText, text: &str| -> bool {
        label.as_plain_text().contains(text)
            || label
                .get("it")
                .is_some_and(|t| t.as_plain_text().contains(text))
            || label
                .get("it-ch")
                .is_some_and(|t| t.as_plain_text().contains(text))
    };

    let field_has_label = |f: &crate::structured::FieldNode, text: &str| -> bool {
        f.label.as_ref().is_some_and(|l| label_contains(l, text))
    };

    // Helper: check if nodes contain a repeatable with Cognome and Nome/i
    let has_repeatable_with_cognome_nomi = |nodes: &[StructuredNode]| -> bool {
        let mut found = false;
        walk_structured_nodes(nodes, &mut |node| {
            if let StructuredNode::Repeatable(rep) = node {
                let rep_fields = collect_fields(std::slice::from_ref(&StructuredNode::Repeatable(
                    rep.clone(),
                )));
                let has_cognome = rep_fields.iter().any(|f| field_has_label(f, "Cognome"));
                let has_nomi = rep_fields
                    .iter()
                    .any(|f| field_has_label(f, "Nome/i") || field_has_label(f, "First name"));
                if has_cognome && has_nomi {
                    found = true;
                }
            }
        });
        found
    };

    // 1) Must contain a dropdown "Tipo"
    let fields = collect_fields(nodes);
    let all_labels: Vec<String> = fields
        .iter()
        .filter_map(|f| f.label.as_ref().map(|l| l.as_plain_text()))
        .collect();

    let tipo_field = fields.iter().find(|f| field_has_label(f, "Tipo"));
    assert!(
        tipo_field.is_some(),
        "Expected a field with label 'Tipo', but none found.\nAll labels: {:?}",
        all_labels
    );

    // 2) Collect all Conditional nodes
    let mut conditionals: Vec<ConditionalNode> = Vec::new();
    walk_structured_nodes(nodes, &mut |node| {
        if let StructuredNode::Conditional(cond) = node {
            conditionals.push(cond.clone());
        }
    });

    assert!(
        conditionals.len() >= 2,
        "Expected at least 2 Conditional nodes, found {}",
        conditionals.len()
    );

    // 3) Conditional with value "Legal Entity": contains "Nome della società" and a repeatable
    let legal_entity_cond = conditionals
        .iter()
        .find(|c| matches!(&c.condition.value, InputValue::Text(v) if v == "Legal Entity"));
    assert!(
        legal_entity_cond.is_some(),
        "Expected a Conditional with value 'Legal Entity', but none found.\n\
         Conditional values: {:?}",
        conditionals
            .iter()
            .map(|c| &c.condition.value)
            .collect::<Vec<_>>()
    );

    let legal_entity_nodes = std::slice::from_ref(legal_entity_cond.unwrap().content.as_ref());
    let le_fields = collect_fields(legal_entity_nodes);

    let has_nome_societa = le_fields
        .iter()
        .any(|f| field_has_label(f, "Nome della societ"));
    assert!(
        has_nome_societa,
        "Legal Entity conditional should contain 'Nome della società'.\n\
         Fields: {:?}",
        le_fields
            .iter()
            .filter_map(|f| f.label.as_ref().map(|l| l.as_plain_text()))
            .collect::<Vec<_>>()
    );

    assert!(
        has_repeatable_with_cognome_nomi(legal_entity_nodes),
        "Legal Entity conditional should contain a Repeatable with 'Cognome' and 'Nome/i'"
    );

    // 4) Conditional with value "Individual": contains only the repeatable
    let individual_cond = conditionals
        .iter()
        .find(|c| matches!(&c.condition.value, InputValue::Text(v) if v == "Individual"));
    assert!(
        individual_cond.is_some(),
        "Expected a Conditional with value 'Individual', but none found.\n\
         Conditional values: {:?}",
        conditionals
            .iter()
            .map(|c| &c.condition.value)
            .collect::<Vec<_>>()
    );

    let individual_nodes = std::slice::from_ref(individual_cond.unwrap().content.as_ref());

    assert!(
        has_repeatable_with_cognome_nomi(individual_nodes),
        "Individual conditional should contain a Repeatable with 'Cognome' and 'Nome/i'"
    );

    // 5) Must contain fields "Luogo", "Data", "Nome del Cliente"
    for expected_label in &["Luogo", "Data", "Nome del cliente"] {
        let found = fields.iter().any(|f| field_has_label(f, expected_label));
        assert!(
            found,
            "Expected a field with label '{}', but none found.\nAll labels: {:?}",
            expected_label, all_labels
        );
    }
}

#[test]
fn test_aaow_zip_structured_output() {
    use crate::structured::FieldType;

    let zip_bytes = std::fs::read(input_path("AAOW.zip")).expect("Failed to read AAOW.zip");
    let bp = Blueprint::from_aem_zip(&zip_bytes).expect("Failed to parse AAOW.zip");
    let envelope = bp
        .aem_structured()
        .expect("Failed to get AEM structured output");
    let nodes = &envelope.content;

    // Collect all radio button fields
    let radios = collect_radio_fields(nodes);

    // Find a radio button whose options contain both "Congiunto" and "Disgiunto"
    let option_name_contains = |name: &crate::structured::TranslatableString, text: &str| -> bool {
        name.as_str().contains(text)
            || name.get("it").is_some_and(|s| s.contains(text))
            || name.get("it-ch").is_some_and(|s| s.contains(text))
    };

    let matching_radio = radios.iter().find(|f| {
        if let FieldType::Radio { options } = &f.input_type {
            let has_congiunto = options
                .iter()
                .any(|o| option_name_contains(&o.name, "Congiunto"));
            let has_disgiunto = options
                .iter()
                .any(|o| option_name_contains(&o.name, "Disgiunto"));
            has_congiunto && has_disgiunto
        } else {
            false
        }
    });

    let all_radio_options: Vec<Vec<String>> = radios
        .iter()
        .filter_map(|f| {
            if let FieldType::Radio { options } = &f.input_type {
                Some(
                    options
                        .iter()
                        .map(|o| o.name.as_str().to_string())
                        .collect(),
                )
            } else {
                None
            }
        })
        .collect();

    assert!(
        matching_radio.is_some(),
        "Expected a radio button with options 'Congiunto' and 'Disgiunto', but none found.\n\
         All radio option sets: {:?}",
        all_radio_options
    );
}

#[test]
fn test_bavx_has_two_date_inputs_with_caption_labels() {
    use crate::structured::{FieldNode, FieldType};

    // BAVX puts the two date inputs' labels in separate non-interactive caption
    // fields placed directly below each input. Regression test: the date inputs
    // must end up labelled with those captions (not with an unrelated paragraph
    // above the section), and the captions must not surface as editable inputs.
    let envelope = crate::run_exhaustive_to_envelope(input_path("BAVX_019_EN.pdf"), "en")
        .expect("Failed to process BAVX_019_EN.pdf");
    let nodes = &envelope.content;

    let date_fields: Vec<(FieldNode, String)> = collect_fields(nodes)
        .into_iter()
        .filter(|f| matches!(f.input_type, FieldType::Date))
        .map(|f| {
            let label = f
                .label
                .as_ref()
                .map(|l| l.as_plain_text())
                .unwrap_or_default();
            (f, label)
        })
        .collect();

    let labels: Vec<String> = date_fields.iter().map(|(_, label)| label.clone()).collect();

    for expected_label in [
        "Date of the month-end balance statement",
        "Expiry of the month-end balance statement",
    ] {
        assert!(
            labels.iter().any(|l| l.contains(expected_label)),
            "Expected a date input labelled '{}', but none found.\nAll date input labels: {:?}",
            expected_label,
            labels
        );
    }

    // The caption text must not leak through as the value of any field.
    let all_fields = collect_fields(nodes);
    for f in &all_fields {
        let value_text = match &f.value {
            Some(crate::structured::InputValue::Text(t)) => t.clone(),
            _ => String::new(),
        };
        assert!(
            !value_text.contains("month-end balance statement"),
            "Caption text leaked into a field value: {:?}",
            f.som_path_str()
        );
    }
}

#[test]
fn test_aacx_no_duplicate_headings() {
    // AACX has a heading "Titolare del conto (di seguito il Cliente)" that should
    // appear exactly once. Previously it appeared three times because hidden panels
    // (with visible=false and no visibility condition) still contributed headings.
    let zip_bytes = std::fs::read(input_path("AACX.zip")).expect("Failed to read AACX.zip");
    let bp = Blueprint::from_aem_zip(&zip_bytes).expect("Failed to parse AACX.zip");
    let envelope = bp
        .aem_structured()
        .expect("Failed to get AEM structured output");

    let headings = collect_headings(&envelope.content);
    let titolare_count = headings
        .iter()
        .filter(|(_, text)| text.contains("Titolare del conto"))
        .count();

    assert_eq!(
        titolare_count, 1,
        "Expected heading 'Titolare del conto (di seguito il Cliente)' exactly once, \
         but found it {} times.\nAll headings: {:?}",
        titolare_count, headings
    );
}

#[test]
fn test_aari_normativa_citata_radio_has_label_and_options() {
    // Test that AARI_033_IT.pdf has a radio button group with label
    // "Ai sensi della normativa citata il Cliente dichiara:" and two options about
    // the fiscal regime (Amministrato).
    use crate::Blueprint;
    use crate::structured::FieldType;

    let mut bp =
        Blueprint::from_pdf(input_path("AARI_033_IT.pdf")).expect("Failed to load AARI_033_IT.pdf");

    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let state = form_states.iter().next().unwrap();
    let envelope = state.structured(ctx);

    let radio_fields = collect_radio_fields(&envelope.content);

    // Find the radio button group with the two fiscal regime options
    let group = radio_fields.iter().find(|field| {
        if let FieldType::Radio { options } = &field.input_type {
            options.len() == 2
                && options.iter().any(|opt| {
                    let text = opt.name.to_string();
                    text.contains("voler optare per l")
                        && text.contains("imposizione sostitutiva")
                        && text.contains("Regime Fiscale Amministrato")
                })
                && options.iter().any(|opt| {
                    let text = opt.name.to_string();
                    text.contains("non voler optare per il Regime Fiscale Amministrato")
                })
        } else {
            false
        }
    });

    assert!(
        group.is_some(),
        "Expected a radio button group with 2 fiscal regime options"
    );

    let group = group.unwrap();

    // Assert that the radio group has the expected label
    let label_text = group
        .label
        .as_ref()
        .expect("Radio button group should have a label attached")
        .as_plain_text();
    assert!(
        label_text.contains("Ai sensi della normativa citata il Cliente dichiara"),
        "Expected label to contain 'Ai sensi della normativa citata il Cliente dichiara', got: '{}'",
        label_text
    );
}

#[test]
fn test_bagy_paragraphs_merged_de_en() {
    // The BAGY form has corresponding paragraphs across DE and EN that describe
    // the risk information overview. They should be merged into a single
    // TranslatedText node during multilingual merge.
    use crate::run_exhaustive_to_envelope;
    use crate::structured::{self, StructuredNode};

    let de_envelope = run_exhaustive_to_envelope(input_path("BAGY_019_DE.pdf"), "de")
        .expect("Failed to process BAGY_019_DE");
    let en_envelope = run_exhaustive_to_envelope(input_path("BAGY_019_EN.pdf"), "en")
        .expect("Failed to process BAGY_019_EN");

    #[cfg(feature = "semantic-matching")]
    let semantic =
        crate::semantic::SemanticMatcher::new().expect("Failed to load semantic matcher");
    #[cfg(feature = "semantic-matching")]
    let semantic_ref = Some(&semantic as &crate::structured::SemanticCtx);
    #[cfg(not(feature = "semantic-matching"))]
    let semantic_ref: Option<&crate::structured::SemanticCtx> = None;

    let merged =
        structured::merge_translations(vec![de_envelope, en_envelope], semantic_ref).unwrap();

    let de_fragment = "Die Übersicht ist nicht vollständig, sondern konzentriert sich auf die wesentlichen Unterschiede des Kundenschutzes.";
    let en_fragment =
        "The overview is not exhaustive, but focuses on the differences in client protection.";

    let mut found = false;
    walk_structured_nodes(&merged.content, &mut |node| {
        if let StructuredNode::Paragraph(p) = node {
            let has_de = p
                .content
                .get("de")
                .is_some_and(|t| t.as_plain_text().contains(de_fragment));
            let has_en = p
                .content
                .get("en")
                .is_some_and(|t| t.as_plain_text().contains(en_fragment));
            if has_de && has_en {
                found = true;
            }
        }
    });

    assert!(
        found,
        "Expected the DE paragraph ('Die Übersicht ist nicht vollständig...') and EN paragraph \
         ('The overview is not exhaustive...') to be merged into the same TranslatedText node in BAGY"
    );
}

#[test]
fn test_aaij_multilingual_merge_content() {
    use crate::run_exhaustive_to_envelope;
    use crate::structured::{self, StructuredNode};
    use helpers::walk_structured_nodes;

    let de_envelope = run_exhaustive_to_envelope(input_path("AAIJ_019_DE.pdf"), "de")
        .expect("Failed to process AAIJ_019_DE");
    let en_envelope = run_exhaustive_to_envelope(input_path("AAIJ_019_EN.pdf"), "en")
        .expect("Failed to process AAIJ_019_EN");
    let it_envelope = run_exhaustive_to_envelope(input_path("AAIJ_033_IT.pdf"), "it")
        .expect("Failed to process AAIJ_033_IT");

    // AAIJ 033 IT may diverge structurally from 019 DE/EN due to different form
    // versions having different CSS font-weight patterns.  Try the 3-way merge;
    // if structural similarity is insufficient, fall back to DE+EN only.
    let (merged, has_it) = match structured::merge_translations(
        vec![de_envelope.clone(), en_envelope.clone(), it_envelope],
        None,
    ) {
        Ok(m) => (m, true),
        Err(_) => {
            let m = structured::merge_translations(vec![de_envelope, en_envelope], None)
                .expect("Failed to merge AAIJ DE/EN");
            (m, false)
        }
    };

    let de_fragment = "Einstufung als Professioneller Kunde kraft Gesetz";
    let en_fragment = "Classification as Per Se Professional";
    let it_fragment = "Classificazione come cliente professionale di diritto";

    let mut found_de = false;
    let mut found_en = false;
    let mut found_it = false;

    walk_structured_nodes(&merged.content, &mut |node| {
        let tt = match node {
            StructuredNode::Heading(h) => &h.content,
            StructuredNode::Paragraph(p) => &p.content,
            _ => return,
        };
        if tt
            .get("de")
            .is_some_and(|t| t.as_plain_text().contains(de_fragment))
        {
            found_de = true;
        }
        if tt
            .get("en")
            .is_some_and(|t| t.as_plain_text().contains(en_fragment))
        {
            found_en = true;
        }
        if tt
            .get("it")
            .is_some_and(|t| t.as_plain_text().contains(it_fragment))
        {
            found_it = true;
        }
    });

    assert!(
        found_de,
        "Expected DE content '{}' to be present in merged AAIJ",
        de_fragment
    );
    assert!(
        found_en,
        "Expected EN content '{}' to be present in merged AAIJ",
        en_fragment
    );
    assert!(
        !has_it || found_it,
        "Expected IT content '{}' to be present in merged AAIJ",
        it_fragment
    );
}

#[test]
fn test_aaij_pipeline_multilingual_state_signature_mismatch() {
    use crate::pipeline::{PipelineConfig, run_pipeline};

    let files = vec![
        (
            "AAIJ_019_DE.pdf".to_string(),
            std::fs::read(input_path("AAIJ_019_DE.pdf")).expect("Failed to read AAIJ DE PDF"),
        ),
        (
            "AAIJ_019_EN.pdf".to_string(),
            std::fs::read(input_path("AAIJ_019_EN.pdf")).expect("Failed to read AAIJ EN PDF"),
        ),
        (
            "AAIJ_033_IT.pdf".to_string(),
            std::fs::read(input_path("AAIJ_033_IT.pdf")).expect("Failed to read AAIJ IT PDF"),
        ),
    ];

    let config = PipelineConfig {
        scale: 1.0,
        render_plain: false,
        render_annotated: false,
        render_labelled: false,
    };

    let result = run_pipeline(&files, &config, |_| {});

    let err = match result {
        Err(e) => e,
        Ok(_) => panic!(
            "AAIJ pipeline should fail with state signature mismatch for DE/EN (019) vs IT (033)"
        ),
    };
    let msg = err.to_string();
    assert!(
        msg.contains("State signature mismatch"),
        "Expected state signature mismatch error, got: {msg}"
    );
    assert!(
        msg.contains("dropdown|0"),
        "Expected dropdown|0 in mismatch error, got: {msg}"
    );
}

#[test]
fn test_adcl_repeatable_contains_cognome_and_nomi() {
    use crate::structured::StructuredNode;

    let merged = crate::run_exhaustive_to_merged(input_path("ADCL_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on ADCL_033_IT.pdf");

    fn contains_field_label(nodes: &[StructuredNode], label_fragment: &str) -> bool {
        for node in nodes {
            match node {
                StructuredNode::Field(field) => {
                    if field
                        .label
                        .as_ref()
                        .map(|l| l.as_plain_text().contains(label_fragment))
                        .unwrap_or(false)
                    {
                        return true;
                    }
                }
                StructuredNode::Group(g) => {
                    if contains_field_label(&g.children, label_fragment) {
                        return true;
                    }
                }
                StructuredNode::Conditional(c) => {
                    if contains_field_label(
                        std::slice::from_ref(c.content.as_ref()),
                        label_fragment,
                    ) {
                        return true;
                    }
                }
                StructuredNode::Repeatable(rep) => {
                    if contains_field_label(std::slice::from_ref(rep.item.as_ref()), label_fragment)
                    {
                        return true;
                    }
                }
                StructuredNode::GridLayout(grid) => {
                    for element in &grid.elements {
                        if contains_field_label(std::slice::from_ref(&element.node), label_fragment)
                        {
                            return true;
                        }
                    }
                }
                StructuredNode::Table(table) => {
                    if let Some(header) = &table.header {
                        if contains_field_label(&header.cells, label_fragment) {
                            return true;
                        }
                    }
                    for row in &table.rows {
                        if contains_field_label(&row.cells, label_fragment) {
                            return true;
                        }
                    }
                }
                _ => {}
            }
        }
        false
    }

    fn has_repeatable_with_fields(nodes: &[StructuredNode], labels: &[&str]) -> bool {
        for node in nodes {
            match node {
                StructuredNode::Repeatable(rep) => {
                    let item = std::slice::from_ref(rep.item.as_ref());
                    if labels.iter().all(|l| contains_field_label(item, l)) {
                        return true;
                    }
                }
                StructuredNode::Group(g) => {
                    if has_repeatable_with_fields(&g.children, labels) {
                        return true;
                    }
                }
                StructuredNode::Conditional(c) => {
                    if has_repeatable_with_fields(std::slice::from_ref(c.content.as_ref()), labels)
                    {
                        return true;
                    }
                }
                _ => {}
            }
        }
        false
    }

    assert!(
        has_repeatable_with_fields(&merged, &["Cognome", "Nome"]),
        "Expected a Repeatable containing fields 'Cognome' and 'Nome/i' in ADCL_033_IT"
    );
}

#[test]
fn test_adcl_contains_roman_numeral_list() {
    use crate::document::ListStyleType;
    use crate::structured::{ListNode, StructuredNode};

    let merged = crate::run_exhaustive_to_merged(input_path("ADCL_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on ADCL_033_IT.pdf");

    fn collect_lists(nodes: &[StructuredNode]) -> Vec<ListNode> {
        let mut lists = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::List(l) => lists.push(l.clone()),
                StructuredNode::Group(g) => lists.extend(collect_lists(&g.children)),
                StructuredNode::Repeatable(r) => {
                    lists.extend(collect_lists(&[(*r.item).clone()]));
                }
                StructuredNode::Conditional(c) => {
                    lists.extend(collect_lists(&[(*c.content).clone()]));
                }
                StructuredNode::GridLayout(gl) => {
                    let child_nodes: Vec<_> = gl.elements.iter().map(|e| e.node.clone()).collect();
                    lists.extend(collect_lists(&child_nodes));
                }
                _ => {}
            }
        }
        lists
    }

    let lists = collect_lists(&merged);

    // Find a roman numeral list
    let roman_lists: Vec<_> = lists
        .iter()
        .filter(|l| {
            matches!(
                l.list_style,
                ListStyleType::LowerRoman | ListStyleType::UpperRoman
            )
        })
        .collect();

    assert!(
        !roman_lists.is_empty(),
        "Expected at least one roman numeral list in ADCL_033_IT, found none.\n\
         All list styles: {:?}",
        lists.iter().map(|l| &l.list_style).collect::<Vec<_>>()
    );

    // Check that one of the roman numeral lists contains the expected items
    let expected_fragment_1 = "avr\u{00e0} il potere e il diritto di sottoscrivere";
    let expected_fragment_2 = "autorizza la Banca, le societ\u{00e0} emittenti";

    let has_matching_list = roman_lists.iter().any(|l| {
        let has_item1 = l
            .items
            .iter()
            .any(|item| item.as_plain_text().contains(expected_fragment_1));
        let has_item2 = l
            .items
            .iter()
            .any(|item| item.as_plain_text().contains(expected_fragment_2));
        has_item1 && has_item2
    });

    assert!(
        has_matching_list,
        "Expected a roman numeral list containing both expected items in ADCL_033_IT.\n\
         Roman numeral list items: {:?}",
        roman_lists
            .iter()
            .flat_map(|l| l.items.iter().map(|i| i.as_plain_text()))
            .collect::<Vec<_>>()
    );
}

#[test]
fn test_adcl_contains_alpha_list() {
    use crate::document::ListStyleType;
    use crate::structured::{ListNode, StructuredNode};

    let merged = crate::run_exhaustive_to_merged(input_path("ADCL_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on ADCL_033_IT.pdf");

    fn collect_lists(nodes: &[StructuredNode]) -> Vec<ListNode> {
        let mut lists = Vec::new();
        for node in nodes {
            match node {
                StructuredNode::List(l) => lists.push(l.clone()),
                StructuredNode::Group(g) => lists.extend(collect_lists(&g.children)),
                StructuredNode::Repeatable(r) => {
                    lists.extend(collect_lists(&[(*r.item).clone()]));
                }
                StructuredNode::Conditional(c) => {
                    lists.extend(collect_lists(&[(*c.content).clone()]));
                }
                StructuredNode::GridLayout(gl) => {
                    let child_nodes: Vec<_> = gl.elements.iter().map(|e| e.node.clone()).collect();
                    lists.extend(collect_lists(&child_nodes));
                }
                _ => {}
            }
        }
        lists
    }

    let lists = collect_lists(&merged);

    // Find alpha (letter) lists
    let alpha_lists: Vec<_> = lists
        .iter()
        .filter(|l| {
            matches!(
                l.list_style,
                ListStyleType::LowerAlpha | ListStyleType::UpperAlpha
            )
        })
        .collect();

    assert!(
        !alpha_lists.is_empty(),
        "Expected at least one alpha list in ADCL_033_IT, found none.\n\
         All list styles: {:?}",
        lists.iter().map(|l| &l.list_style).collect::<Vec<_>>()
    );

    // Expected fragments from the 7 items (a-g)
    let expected_fragments = [
        "la Banca non \u{00e8} tenuta a comunicare agli altri cointestatari",
        "rimossa sin d'ora ogni eccezione anche ai sensi",
        "la presente procura sar\u{00e0} valida ed efficace sino al ricevimento",
        "in ogni caso, la presente procura sar\u{00e0} valida ed efficace sino al recesso",
        "nelle ipotesi di cui alle precedenti lettere c) e d)",
        "la modifica dei poteri conferiti con la presente procura",
        "i sottoscritti cointestatari rimangono pienamente responsabili",
    ];

    // Collect all items across alpha lists (currently detected as two separate lists)
    let all_alpha_items: Vec<String> = alpha_lists
        .iter()
        .flat_map(|l| l.items.iter().map(|i| i.as_plain_text()))
        .collect();

    for fragment in &expected_fragments {
        assert!(
            all_alpha_items.iter().any(|item| item.contains(fragment)),
            "Expected an alpha list item containing '{}' in ADCL_033_IT.\n\
             All alpha list items: {:?}",
            fragment,
            all_alpha_items
        );
    }

    // Should be a single alpha list with 7 items (a-g)
    assert_eq!(
        alpha_lists.len(),
        1,
        "Expected 1 alpha list in ADCL_033_IT, found {}",
        alpha_lists.len()
    );

    assert_eq!(
        alpha_lists[0].items.len(),
        7,
        "Expected 7 items (a-g) in the alpha list, found {}",
        alpha_lists[0].items.len()
    );
}

/// Verify that radio button labels containing commas are properly escaped in AEM output.
///
/// AATO has radio buttons with labels like "Si, ..." that contain commas.
/// AEM uses comma-separated lists for option serialization, so unescaped commas
/// in labels would corrupt the option list.
#[test]
fn test_aato_radio_options_with_commas_escaped_in_aem() {
    use crate::structured::FieldType;

    let structured_nodes = crate::run_exhaustive_to_merged(input_path("AATO_033_IT.pdf"))
        .expect("Failed to run exhaustive merge on AATO_033_IT.pdf");

    let radio_fields = collect_radio_fields(&structured_nodes);
    // Collect radio options whose labels contain commas
    let mut found_comma_label = false;
    for field in &radio_fields {
        if let FieldType::Radio { options } = &field.input_type {
            for opt in options {
                if opt.name.as_str().contains(',') {
                    found_comma_label = true;
                }
            }
        }
    }
    assert!(
        found_comma_label,
        "AATO should have at least one radio option label containing a comma. \
         Radio fields found: {:?}",
        radio_fields
            .iter()
            .filter_map(|f| if let FieldType::Radio { options } = &f.input_type {
                Some(
                    options
                        .iter()
                        .map(|o| o.name.as_str().to_string())
                        .collect::<Vec<_>>(),
                )
            } else {
                None
            })
            .collect::<Vec<_>>()
    );

    // Generate AEM XML and verify comma labels are escaped
    assert_aem_xml_valid_for(&[("AATO_033_IT.pdf", "AATO")]);
}

#[test]
fn test_fragment_bind_refs_use_configured_prefix() {
    // Fragment bindRef paths should use the configured fragmentBindRefPrefix.
    // The profile sets `fragmentBindRefPrefix = "UBSAF_{{ form_code }}"`, which
    // expands to the form-specific root (e.g. "/UBSAF_AAAI/...") so fragment
    // bindRefs stay consistent with the generated XSD root element.
    use crate::Blueprint;
    use crate::aem::{AemConfig, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAAI_019_EN.pdf")).expect("Failed to load AAAI_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    // Configure with a form-specific root and a fragment prefix that expands
    // to the same root. The profile has rootElementName = "UBSAF_{{ form_code }}"
    // and fragmentBindRefPrefix = "UBSAF_{{ form_code }}" from the TOML.
    let mut xsd_config = helpers::load_ubs_xsd_config().with_master_language("en");
    xsd_config.form_code = Some("AAAI".to_string());

    config.bind_to_xsd = true;
    config.use_fragments = true;
    config.xsd_config = Some(xsd_config);

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    // All fragment bindRefs should start with the form-specific root
    // "/UBSAF_AAAI/" so they match the generated XSD root element.
    let fragment_refs = helpers::collect_aem_fragment_refs(&root);
    assert!(
        !fragment_refs.is_empty(),
        "Expected at least one fragment node"
    );
    // A fragment inside a *collapsed* repeatable is deliberately unbound: the
    // repeatable and its single child are one XSD element, and the repeat panel
    // owns the path because that is the node AEM instantiates per row. Every
    // other fragment carries the form-specific root.
    let mut bound_fragments = 0;
    for (frag_ref, bind_ref) in &fragment_refs {
        let Some(br) = bind_ref.as_deref() else {
            continue;
        };
        bound_fragments += 1;
        assert!(
            br.starts_with("/UBSAF_AAAI/"),
            "Fragment '{}' bindRef should start with the form root '/UBSAF_AAAI/', got: {}",
            frag_ref,
            br
        );
    }
    assert!(
        bound_fragments > 0,
        "Expected at least one fragment bound under the form root"
    );

    // Every other bound node uses the same form root. Note that a *non-repeating*
    // grouping panel is deliberately left unbound: it is a schema convenience
    // with no data of its own, which is how UBS's own forms are bound.
    let mut found_form_root = false;
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let Some(br) = helpers::node_bind_ref(node) {
            assert!(
                br.starts_with("/UBSAF_AAAI/"),
                "bindRef {br} should start with the form root '/UBSAF_AAAI/'"
            );
            found_form_root = true;
        }
    });
    assert!(
        found_form_root,
        "Expected at least one node bound under '/UBSAF_AAAI/'"
    );
}

#[test]
fn test_repeatable_panels_have_bind_ref() {
    // Repeatable inner panels should receive a bindRef attribute derived from
    // the XSD structure (e.g. the bind path of their inner section).
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAAI_019_EN.pdf")).expect("Failed to load AAAI_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    config.bind_to_xsd = true;
    config.xsd_config = Some(helpers::load_ubs_xsd_config().with_master_language("en"));

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    // Collect all Repeatable nodes
    let mut repeatables: Vec<(String, Option<String>)> = Vec::new();
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let AemNode::Repeatable { name, bind_ref, .. } = node {
            repeatables.push((name.clone(), bind_ref.clone()));
        }
    });

    assert!(
        !repeatables.is_empty(),
        "AAAI should have at least one Repeatable panel"
    );

    // Every Repeatable whose inner section has a heading (and therefore a
    // bind_ref) should have a non-empty bind_ref.
    let with_bind_ref: Vec<_> = repeatables.iter().filter(|(_, br)| br.is_some()).collect();
    assert!(
        !with_bind_ref.is_empty(),
        "At least one Repeatable should have a bind_ref.\nAll repeatables: {:?}",
        repeatables
    );

    // The bind_ref should be a valid XSD-style path starting with "/"
    for (name, bind_ref) in &with_bind_ref {
        let br = bind_ref.as_deref().unwrap();
        assert!(
            br.starts_with('/'),
            "Repeatable '{}' bind_ref should start with '/', got: {}",
            name,
            br
        );
    }
}

#[test]
fn test_repeatable_bind_ref_stripped_when_bind_to_xsd_disabled() {
    // When bind_to_xsd=false, Repeatable nodes should have their bind_ref
    // cleared, just like Panel nodes.
    use crate::Blueprint;
    use crate::aem::{AemConfig, AemNode, convert_to_aem};

    let mut bp =
        Blueprint::from_pdf(input_path("AAAI_019_EN.pdf")).expect("Failed to load AAAI_019_EN.pdf");
    let ctx = bp.context();
    let form_states = bp.states().expect("Failed to get form states");
    let content = crate::merge_form_states(&form_states, ctx.clone()).0;

    let (profile, templates, custom_templates) = helpers::load_ubs_profile();
    let mut config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("AemConfig from profile");

    config.bind_to_xsd = false;
    config.use_fragments = true;
    config.xsd_config = Some(helpers::load_ubs_xsd_config().with_master_language("en"));

    let fragments_path = helpers::profiles_path("ubs/aem/fragments/afforms_ubs_fragmentlib");
    let fragments_dir = std::path::Path::new(&fragments_path);
    config.fragments = crate::scan_fragments(fragments_dir, &config.fragment_ref_prefix);

    let config = crate::resolve_aem_languages(&content, &config);
    let root = convert_to_aem(&content, &config);

    // No Repeatable should have a bind_ref when bind_to_xsd is disabled
    helpers::walk_aem_nodes(&root, &mut |node| {
        if let AemNode::Repeatable { name, bind_ref, .. } = node {
            assert!(
                bind_ref.is_none(),
                "Repeatable '{}' should have no bind_ref when bind_to_xsd=false, got: {:?}",
                name,
                bind_ref
            );
        }
    });
}

/// Regression test: In BAGE, the long sentence "Dies gilt insbesondere für die
/// Aufklärung und Information über Chancen und Risiken jeder Art von Finanztermin-
/// und Devisentermingeschäften." should be a paragraph, not a heading.
/// It's a full sentence that happens to be bold but is clearly body text.
#[test]
fn test_bage_long_bold_sentence_is_not_heading() {
    use crate::run_exhaustive_to_merged;

    let structured = run_exhaustive_to_merged(helpers::input_path("BAGE_019_DE.pdf"))
        .expect("Failed to run exhaustive merge for BAGE");

    let target_text = "Dies gilt insbesondere für die Aufklärung und Information über Chancen und Risiken jeder Art von Finanztermin- und Devisentermingeschäften.";

    let headings = helpers::collect_headings(&structured);
    let found_as_heading = headings.iter().any(|(_, h)| h.contains(target_text));
    assert!(
        !found_as_heading,
        "The sentence '{}' should NOT be classified as a heading. It is a normal paragraph.\nHeadings found: {:?}",
        target_text,
        headings
            .iter()
            .filter(|(_, h)| h.contains("Dies gilt"))
            .collect::<Vec<_>>()
    );
}

