    assert_eq!(dump.ownerships[1].owner_type, OwnerType::Document);
    assert_eq!(dump.ownerships[1].ownership_type, OwnershipType::Origin);
    assert_eq!(dump.ownerships[1].object_type, ObjectType::Text);
