// ============================================================================
// PROBLEM-configurator-reset-on-change (feedback #107)
//
// The configurator asks what the form is for and each option reveals a different
// panel. The visibility rule only shows and hides, so nothing is ever cleared:
// fill the form in as one option, switch to another and come back, and the first
// option returns with every field filled and every repeatable row still added.
// The submission then carries one option's data under another, invisibly.
// ============================================================================

/// A form whose `choice` (radio) reveals one of two panels, the second holding a
/// repeatable. Returns the rendered XML.
#[cfg(test)]
fn render_configurator(option_labels: &[&str]) -> String {
    use crate::aem::{
        AemConfig, AemNode, AemOption, ConditionRule, OptionAlignment, generate_aem_xml,
    };
    use crate::structured::InputValue;
    use uuid::Uuid;

    let (profile, templates, custom_templates) = load_ubs_profile();
    let mut vars = std::collections::HashMap::new();
    vars.insert("formrange_code".into(), "AAEI".into());
    vars.insert("formrange_entity".into(), "019".into());
    let ctx = crate::Context::new("de".to_string(), vars);
    let config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("build AemConfig from the UBS profile");

    let uid = |s: &str| Uuid::new_v5(&Uuid::NAMESPACE_URL, s.as_bytes());
    let panel = |name: &str, children: Vec<AemNode>| AemNode::Panel {
        uuid: uid(name),
        name: name.into(),
        title: name.into(),
        children,
        is_page: false,
        attrs: crate::AemAttrs::default(),
        visible: true,
        is_conditional: true,
        dor_num_cols: None,
        colspan: 12,
        dor_colspan: None,
        bind_ref: None,
        frag_ref: None,
    };
    let repeatable = AemNode::Repeatable {
        attrs: crate::AemAttrs::default(),
        visible: true,
        uuid: uid("RCP_Reps"),
        name: "RCP_Reps".into(),
        title: "Reps".into(),
        children: vec![text_field("TXT_InRow")],
        min_occur: 1,
        max_occur: 5,
        bind_ref: None,
        frag_ref: None,
    };

    let choice = AemNode::RadioButton {
        attrs: crate::AemAttrs::default(),
        uuid: uid("RB_Kind"),
        name: "RB_Kind".into(),
        label: "Art".into(),
        options: option_labels
            .iter()
            .enumerate()
            .map(|(i, l)| AemOption {
                label: (*l).into(),
                value: (i + 1).to_string(),
            })
            .collect(),
        alignment: OptionAlignment::Vertical,
        mandatory: true,
        visible: true,
        colspan: 12,
        dor_colspan: None,
        field_id: None,
        conditions: option_labels
            .iter()
            .enumerate()
            .map(|(i, _)| ConditionRule {
                value: InputValue::Text((i + 1).to_string()),
                target_panel_name: format!("PN_Option{}", i + 1),
                show: true,
            })
            .collect(),
        bind_ref: None,
    };

    let mut children = vec![choice];
    for (i, _) in option_labels.iter().enumerate() {
        let name = format!("PN_Option{}", i + 1);
        // Only the second option's panel holds a repeatable, so the test can tell
        // the two reset calls apart.
        let inner = if i == 1 {
            vec![text_field(&format!("TXT_In{}", i + 1)), repeatable.clone()]
        } else {
            vec![text_field(&format!("TXT_In{}", i + 1))]
        };
        children.push(panel(&name, inner));
    }

    let root = AemNode::Root {
        title: "Form".into(),
        children,
    };
    generate_aem_xml(&root, &config)
}

#[test]
fn an_approved_configurator_choice_empties_every_panel_it_decides() {
    let xml = render_configurator(&["Individual", "Legal Entity"]);

    assert!(
        xml.contains("fd:valueCommit="),
        "the reset runs on Value Commit:\n{xml}"
    );
    for panel in ["PN_Option1", "PN_Option2"] {
        assert!(
            xml.contains(&format!("{panel}.resetData();")),
            "{panel} is decided by the choice and must be emptied:\n{xml}"
        );
    }
    // A repeatable has to DROP its rows, not just blank them — a blanked row
    // still counts against the row total the reader sees.
    assert!(
        xml.contains("resetAllPanelInstances(RCP_Reps_repeat);"),
        "the repeatable inside a decided panel must drop its rows:\n{xml}"
    );
    // Rows first, then the panel's remaining fields.
    let rows = xml.find("resetAllPanelInstances(RCP_Reps_repeat)").unwrap();
    let fields = xml.find("PN_Option2.resetData()").unwrap();
    assert!(
        rows < fields,
        "the row count must be back to its minimum before the fields are cleared"
    );
}

/// The narrowing that keeps this off ordinary questions. Structurally an order
/// type or an occupation has the same defect, but whether clearing is wanted
/// there is a judgement about that form — so only reviewed wordings get a reset.
#[test]
fn an_unreviewed_choice_gets_no_reset() {
    let xml = render_configurator(&["Standing order", "Single payment"]);
    assert!(
        !xml.contains("resetData();"),
        "an unreviewed wording must be left alone:\n{xml}"
    );
}

/// One panel means there is no other option whose data could resurface.
#[test]
fn a_choice_deciding_a_single_panel_gets_no_reset() {
    let xml = render_configurator(&["Individual"]);
    assert!(!xml.contains("resetData();"), "{xml}");
}

/// The form configurator opens on the individual option whichever path emitted
/// the radio: the custom template (deterministic conversion) and the ordinary
/// radiobutton template (an agent-authored tree, which never goes through custom
/// element replacement).
///
/// Recognised by its option labels, not by one field name, and written as that
/// option's own key — `Private Person` on a German form, `Individuo` on an
/// Italian one, and the key differs per form (PROBLEM-formconfig-private-person-
/// default, widened beyond Germany 2026-09-01).
#[test]
fn an_authored_configurator_radio_also_preselects_private_person() {
    use crate::aem::{AemConfig, AemNode, AemOption, generate_aem_xml};

    let (profile, templates, custom_templates) = load_ubs_profile();
    let mut vars = std::collections::HashMap::new();
    vars.insert("formrange_code".into(), "TEST".into());
    vars.insert("formrange_entity".into(), "019".into());
    let ctx = crate::Context::new("de".to_string(), vars);
    let config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("profile config");

    let choice = |name: &str, labels: &[&str], first_key: usize| AemNode::RadioButton {
        attrs: crate::AemAttrs::default(),
        uuid: uuid::Uuid::from_u128(1),
        name: name.into(),
        label: "Formular Adressat".into(),
        options: labels
            .iter()
            .enumerate()
            .map(|(i, label)| AemOption {
                label: (*label).into(),
                value: (i + first_key).to_string(),
            })
            .collect(),
        alignment: crate::aem::OptionAlignment::Horizontal,
        mandatory: true,
        visible: true,
        colspan: 12,
        dor_colspan: None,
        field_id: None,
        conditions: vec![],
        bind_ref: None,
    };
    let radio = |name: &str| {
        choice(
            name,
            &["Private Person", "Minderjährige", "Firma", "GbR"],
            1,
        )
    };
    let render = |node: AemNode| {
        generate_aem_xml(
            &AemNode::Root {
                title: "TEST".into(),
                children: vec![node],
            },
            &config,
        )
    };

    // The form carries `_value` attributes of its own (the metadata control, text
    // draws), so read the radio's own tag rather than the whole document.
    let tag_of = |node: AemNode, name: &str| {
        let xml = render(node);
        let at = xml
            .find(&format!("name=\"{name}\""))
            .unwrap_or_else(|| panic!("the radio must be emitted:\n{xml}"));
        let start = xml[..at].rfind('<').expect("inside a tag");
        let end = start + xml[start..].find('>').expect("the tag must close");
        xml[start..end].to_string()
    };
    let radio_tag = |name: &str| tag_of(radio(name), name);

    assert!(
        radio_tag("RB_FormularAdressat").contains(r#"_value="1""#),
        "the configurator radio must open preselected:\n{}",
        radio_tag("RB_FormularAdressat")
    );
    // Every other radio is a question the reader has to answer themselves. What
    // makes it ordinary is its wording, not its name: the reviewed label sets are
    // what identify the configurator.
    let ordinary = choice("RB_Something_Else", &["Yes", "No"], 1);
    let tag = tag_of(ordinary, "RB_Something_Else");
    assert!(
        !tag.contains("_value="),
        "an ordinary radio must not be preselected:\n{tag}"
    );

    // An Italian configurator, whose individual option is neither called
    // "Private Person" nor keyed `1` — the key is the option's own, because it
    // differs per form. Which label counts as the individual is unit-tested on
    // `individual_option` itself.
    let italian = choice("RB_Tipo", &["Individuo", "Entità giuridica"], 3);
    let tag = tag_of(italian, "RB_Tipo");
    assert!(
        tag.contains(r#"_value="3""#),
        "the individual option's own key must be written:\n{tag}"
    );
}

/// The form configurator opens on "Private Person": the radio ships with option
/// `1` already selected.
///
/// UBS asked for the preselection (feedback PROBLEM-formconfig-private-person-
/// default) and the mechanism is the component's `_value`, not a `default`
/// attribute -- the widget renders an option checked by comparing its key to
/// `_value`, so a `default` deploys cleanly and preselects nothing.
#[test]
fn the_form_configurator_preselects_private_person() {
    let xml = std::fs::read_to_string(helpers::profiles_path(
        "ubs/aem/custom/formular_adressat_radio.xml",
    ))
    .expect("read formular_adressat_radio.xml");

    assert!(
        xml.contains(r#"_value="1""#),
        "the configurator radio must preselect option 1:\n{xml}"
    );
    assert!(
        xml.contains("options=\"[1="),
        "option 1 must be the Private Person key the preselection points at:\n{xml}"
    );
    assert!(
        !xml.contains(r#"default="1""#),
        "`default` does not preselect anything -- use `_value`:\n{xml}"
    );
}

/// The UBS configurator itself goes through the `formular_adressat_radio` /
/// `tipo_radio` custom templates, whose panels live in the `account_holder` and
/// `signatures` templates they depend on. Those cannot be derived from the node
/// tree, so the script is written out in the template — and has to stay in step
/// with the panels those templates actually define.
#[test]
fn the_custom_configurator_radios_reset_the_panels_their_templates_define() {
    use std::collections::HashSet;

    let read = |name: &str| {
        std::fs::read_to_string(helpers::profiles_path(&format!(
            "ubs/aem/custom/{name}.xml"
        )))
        .unwrap_or_else(|e| panic!("read {name}.xml: {e}"))
    };

    for (radio, panel_sources, expected_panels) in [
        (
            "formular_adressat_radio",
            vec!["account_holder", "signatures"],
            vec![
                "PN_IndividualContainer",
                "PN_LegalGuardianContainer",
                "PN_LegalEntityContainer",
                "PN_165356b3",
                "PN_165356b3_copy_1",
                "PN_204491df",
            ],
        ),
        (
            "tipo_radio",
            vec!["account_holder_it", "signatures_it"],
            vec![
                "PN_IndividualContainer",
                "PN_LegalEntityContainer",
                "PN_165356b3",
                "PN_204491df",
            ],
        ),
    ] {
        let script = read(radio);
        assert!(
            script.contains("fd:valueCommit="),
            "{radio} must carry the reset"
        );
        for panel in &expected_panels {
            assert!(
                script.contains(&format!("{panel}.resetData();")),
                "{radio} must empty {panel}"
            );
        }
        // Every panel the reset names must really exist in the templates this
        // radio depends on — otherwise the script silently throws at runtime.
        let defined: HashSet<String> = panel_sources
            .iter()
            .flat_map(|src| {
                let body = read(src);
                body.match_indices("name=\"PN_")
                    .map(|(i, _)| {
                        let rest = &body[i + "name=\"".len()..];
                        rest[..rest.find('"').unwrap()].to_string()
                    })
                    .collect::<Vec<_>>()
            })
            .collect();
        for panel in &expected_panels {
            assert!(
                defined.contains(*panel),
                "{radio} resets {panel}, which {panel_sources:?} does not define"
            );
        }
    }
}

/// On the from-XFA path the banking-relationship panel is not a `Fragment` node
/// at all — `preface.xml` writes it, as `PN_BankingRelationship` inside the
/// `PN_BR` wrapper. That is the node the Germany default has to land on, so it is
/// asserted separately from the fragment-node path.
#[test]
fn the_preface_banking_panel_carries_the_germany_default() {
    use crate::aem::{AemConfig, AemNode, generate_aem_xml};
    use uuid::Uuid;

    let render = |entity: &str| {
        let (profile, templates, custom_templates) = load_ubs_profile();
        let mut vars = std::collections::HashMap::new();
        vars.insert("formrange_code".into(), "AAEI".into());
        vars.insert("formrange_entity".into(), entity.into());
        let ctx = crate::Context::new("de".to_string(), vars);
        let config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
            .expect("build AemConfig from the UBS profile");
        let root = AemNode::Root {
            title: "Form".into(),
            children: vec![AemNode::Preface {
                uuid: Uuid::new_v5(&Uuid::NAMESPACE_URL, b"preface"),
                name: "PN_BR".into(),
            }],
        };
        generate_aem_xml(&root, &config)
    };

    let germany = render("019");
    assert!(
        germany.contains("name=\"PN_BankingRelationship\""),
        "the preface writes the banking panel:\n{germany}"
    );
    assert!(
        germany.contains("TXT_BankingRelationship1.value = '0319';")
            && germany.contains("TXT_BankingRelationship1.enabled = false;"),
        "a Germany form's banking field must default to 0319 and be disabled:\n{germany}"
    );
    // Count within the panel's own `fd:init` — the document as a whole carries
    // the toolbar's SCRIPTMODELs too.
    let init_start = germany
        .find("fd:init=\"")
        .expect("no fd:init on the banking panel");
    let init = &germany[init_start..];
    let init = &init[..init[9..].find('"').unwrap() + 9];
    assert_eq!(
        init.matches("SCRIPTMODEL").count(),
        1,
        "one SCRIPTMODEL for the panel's Initialize slot:\n{init}"
    );

    for entity in ["033", "001"] {
        let other = render(entity);
        assert!(
            other.contains("name=\"PN_BankingRelationship\"") && !other.contains("0319"),
            "entity {entity} shares the fragment but keeps its own value:\n{other}"
        );
    }
}

/// A profile that ships no `email`/`telephone` template must still emit the
/// field. Dropping it is the failure mode this guards: `render_node` returns an
/// empty string for a missing template, so without the fallback an email field
/// would vanish from the package with nothing but a log line to show for it.
#[test]
fn a_profile_without_contact_templates_falls_back_to_the_text_box() {
    use crate::aem::{AemConfig, AemNode, TextFieldKind, generate_aem_xml};
    use uuid::Uuid;

    let (profile, mut templates, custom_templates) = load_ubs_profile();
    templates.remove("email");
    templates.remove("telephone");
    let mut vars = std::collections::HashMap::new();
    vars.insert("formrange_code".into(), "AAEI".into());
    vars.insert("formrange_entity".into(), "019".into());
    let ctx = crate::Context::new("de".to_string(), vars);
    let config = AemConfig::from_profile(&profile, templates, custom_templates, &ctx)
        .expect("build AemConfig from the UBS profile");

    let root = AemNode::Root {
        title: "Contact".into(),
        children: vec![AemNode::TextField {
            attrs: crate::AemAttrs::default(),
            uuid: Uuid::new_v5(&Uuid::NAMESPACE_URL, b"EML_Email"),
            name: "EML_Email".into(),
            label: "E-Mail".into(),
            mandatory: false,
            visible: true,
            max_chars: None,
            colspan: 6,
            dor_colspan: None,
            bind_ref: None,
            kind: TextFieldKind::Email,
        }],
    };
    let xml = generate_aem_xml(&root, &config);
    assert!(
        xml.contains("name=\"EML_Email\"") && xml.contains("controls/textbox"),
        "the field must survive as a plain text box:\n{xml}"
    );
}

// ============================================================================
// The AEM HTML component (`controls/htmlDisplayer`)
// ============================================================================
// AEM used to have no table component, so the engine flattened every source
// table into a `TBL_` panel of loose draws. It has one now: an HTML component
// carrying markup per locale on its own `localeContent` children rather than
// through the Sling i18n dictionary. These tests pin both directions -- a table
// converts into one, and one already present in a package survives a load.

/// A form carrying the HTML component in exactly the shape AEM's own authoring
/// UI writes it (taken from `AAOV_033.zip`): positional `item{N}` children,
/// regional UBS locales, markup XML-escaped into the `html` attribute.
#[cfg(test)]
const HTML_COMPONENT_FORM_XML: &str = r##"<?xml version="1.0" encoding="UTF-8"?>
<jcr:root xmlns:sling="http://sling.apache.org/jcr/sling/1.0" xmlns:fd="http://www.adobe.com/aemfd/fd/1.0"
    xmlns:cq="http://www.day.com/jcr/cq/1.0" xmlns:jcr="http://www.jcp.org/jcr/1.0"
    xmlns:nt="http://www.jcp.org/jcr/nt/1.0" jcr:primaryType="cq:Page">
    <jcr:content jcr:primaryType="cq:PageContent" jcr:language="it" jcr:title="AAOV"
        sling:resourceType="/apps/ajila-forms-customers/ajila-forms-ubs/components/pages/aftemplatedpage">
        <guideContainer jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/components/guideContainer"
            guideNodeClass="guideContainerNode" name="guide1">
            <rootPanel jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/components/rootPanel"
                guideNodeClass="rootPanelNode" name="guideRootPanel">
                <items jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/layouts/gridFluidLayout2">
                    <panel_step jcr:primaryType="nt:unstructured"
                        sling:resourceType="ajila-forms-customers/ajila-forms-ubs/components/controls/panel"
                        guideNodeClass="guidePanel" name="PN_Step" textIsRich="true">
                        <items jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/layouts/gridFluidLayout2">
                            <htmldisplayer jcr:primaryType="nt:unstructured"
                                sling:resourceType="ajila-forms-customers/ajila-forms-ubs/components/controls/htmlDisplayer"
                                autofillFieldKeyword="name" css="widget_ajila_forms_htmlViewer"
                                guideNodeClass="guideTextBox"
                                initScript="window.forms.ubs.control.htmlviewer.initialize(this)"
                                name="TBL_Plans" textIsRich="[true,true,true,true]">
                                <localeContent jcr:primaryType="nt:unstructured">
                                    <item0 jcr:primaryType="nt:unstructured" locale="en-us"
                                        html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;Plan 1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>
                                    <item1 jcr:primaryType="nt:unstructured" locale="it-ch"
                                        html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;Piano 1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>
                                </localeContent>
                            </htmldisplayer>
                        </items>
                    </panel_step>
                </items>
            </rootPanel>
        </guideContainer>
    </jcr:content>
</jcr:root>
"##;

/// Find the single [`crate::aem::AemNode::HtmlDisplayer`] in a tree.
#[cfg(test)]
fn only_html_displayer(root: &crate::aem::AemNode) -> crate::aem::AemI18nText {
    let mut found = Vec::new();
    helpers::walk_aem_nodes(root, &mut |node| {
        if let crate::aem::AemNode::HtmlDisplayer { content, .. } = node {
            found.push(content.clone());
        }
    });
    assert_eq!(found.len(), 1, "expected exactly one HTML component");
    found.remove(0)
}

/// The regression this component was silently failing: an `htmlDisplayer` has
/// no `items` child and no `fragRef`, so before it was recognised it fell into
/// the parser's unknown-component arm and the whole block -- a table, a chart,
/// an image someone authored by hand -- was dropped from a loaded package
/// without a word.
#[test]
fn the_html_component_survives_a_load() {
    let zip = helpers::aem_zip_from_form_xml("AAOV", HTML_COMPONENT_FORM_XML);
    let package = crate::aem::parse_aem_zip(&zip).expect("parse the HTML-component fixture");

    let content = only_html_displayer(&package.root);

    // The AEM authoring UI writes the regional UBS locales; the engine keys text
    // by language, so `en-us` folds onto `en` and `it-ch` onto `it`.
    assert_eq!(
        content.languages().collect::<Vec<_>>(),
        vec!["en", "it"],
        "regional locales fold onto the engine's language codes"
    );
    assert!(
        content
            .get("en")
            .is_some_and(|m| m.contains("<table>") && m.contains("Plan 1")),
        "the English markup arrives decoded: {:?}",
        content.get("en")
    );
    assert!(
        content.get("it").is_some_and(|m| m.contains("Piano 1")),
        "and each locale keeps its OWN markup, not a copy of the first"
    );
}

/// Load -> save -> load must be a fixpoint for the component, or a review run
/// over a package that carries one degrades it a little every time. Goes the
/// long way round, through the multilingual working tree the agent edits, so
/// the lower/lift pair is covered too: the markup must NOT be folded into the
/// master-text-keyed translation dictionary, because the component reads its own
/// `localeContent` instead.
#[test]
fn the_html_component_survives_a_load_save_load_round_trip() {
    use crate::aem::xml_validation::validate_aem_form_xml;
    use crate::aem::{generate_aem_xml_with_passthrough, parse_aem_zip};

    let zip = helpers::aem_zip_from_form_xml("AAOV", HTML_COMPONENT_FORM_XML);
    let package = parse_aem_zip(&zip).expect("parse the HTML-component fixture");
    let before = only_html_displayer(&package.root);

    let languages = vec!["en".to_string(), "it".to_string()];
    let lifted = lift_package(&package);
    let (lowered, dict) = lifted.lower(&package.language, &languages);
    assert!(
        !dict.keys().any(|k| k.contains("<table>")),
        "the markup must not become a translation-dictionary key: {:?}",
        dict.keys().collect::<Vec<_>>()
    );

    let config = ubs_config_for(&package.language, &languages, "AAOV");
    let regen = generate_aem_xml_with_passthrough(&lowered, &config, &lifted.passthrough_map());
    if let Err(violations) = validate_aem_form_xml(&regen) {
        panic!(
            "the re-rendered form is invalid AEM XML:\n{}",
            violations.join("\n")
        );
    }

    let reparsed = parse_aem_zip(&helpers::aem_zip_from_form_xml("AAOV", &regen))
        .expect("reparse the re-rendered form");
    let after = only_html_displayer(&reparsed.root);

    assert_eq!(
        before.0, after.0,
        "the per-locale markup must come back byte-identical"
    );
}

/// A package carrying BOTH a bare language code and a regional one that folds
/// onto it keeps the bare one's markup, whichever order the items appear in.
/// Otherwise a German form's table would silently become the Swiss-German
/// variant (or not) depending on how AEM happened to order the children.
#[test]
fn an_exact_html_locale_wins_over_a_regional_one() {
    for (first, second) in [("de", "de-ch"), ("de-ch", "de")] {
        let items = format!(
            r#"<item0 jcr:primaryType="nt:unstructured" locale="{first}"
                   html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;{first}&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>
               <item1 jcr:primaryType="nt:unstructured" locale="{second}"
                   html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;{second}&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>"#
        );
        let xml = HTML_COMPONENT_FORM_XML.replace(
            r#"<item0 jcr:primaryType="nt:unstructured" locale="en-us"
                                        html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;Plan 1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>
                                    <item1 jcr:primaryType="nt:unstructured" locale="it-ch"
                                        html="&lt;table&gt;&lt;tr&gt;&lt;td&gt;Piano 1&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;"/>"#,
            &items,
        );
        assert!(xml.contains(&items), "the fixture substitution must have applied");

        let zip = helpers::aem_zip_from_form_xml("AAOV", &xml);
        let package = crate::aem::parse_aem_zip(&zip).expect("parse the two-locale fixture");
        let content = only_html_displayer(&package.root);

        assert_eq!(
            content.languages().collect::<Vec<_>>(),
            vec!["de"],
            "both items fold onto one language (order: {first}, {second})"
        );
        assert!(
            content.get("de").is_some_and(|m| m.contains("<td>de</td>")),
            "the bare `de` markup wins (order: {first}, {second}): {:?}",
            content.get("de")
        );
    }
}

/// A table cell whose text exists in both languages.
#[cfg(test)]
fn bilingual_cell(en: &str, it: &str) -> crate::structured::StructuredNode {
    use crate::structured::{InlineText, ParagraphNode, StructuredNode, TranslatedText};
    StructuredNode::Paragraph(ParagraphNode {
        content: TranslatedText(std::collections::HashMap::from([
            ("en".to_string(), InlineText::plain(en)),
            ("it".to_string(), InlineText::plain(it)),
        ])),
        som_path: None,
        source_name: None,
    })
}

/// A two-column, one-row table with a header, in English and Italian.
#[cfg(test)]
fn bilingual_table(
    body: Vec<crate::structured::StructuredNode>,
) -> crate::structured::StructuredNode {
    use crate::structured::{StructuredNode, TableHeader, TableNode, TableRow};
    StructuredNode::Table(TableNode {
        header: Some(TableHeader {
            cells: vec![
                bilingual_cell("Plan", "Piano"),
                bilingual_cell("Share", "Quota"),
            ],
        }),
        rows: vec![TableRow { cells: body }],
        caption: None,
    })
}

/// A source table becomes ONE HTML component carrying a real `<table>` in every
/// language -- not a `TBL_` panel of loose draws, which is what the engine had
/// to emit while AEM had no table component.
#[test]
fn a_static_table_becomes_one_html_component() {
    use crate::aem::{AemNode, convert_to_aem};

    let content = vec![bilingual_table(vec![
        bilingual_cell("Strategy A", "Strategia A"),
        bilingual_cell("50%", "50%"),
    ])];
    let config = ubs_config_for("en", &["en".to_string(), "it".to_string()], "TEST");
    let root = convert_to_aem(&content, &config);

    let mut found = Vec::new();
    let mut panels = Vec::new();
    helpers::walk_aem_nodes(&root, &mut |node| match node {
        AemNode::HtmlDisplayer { name, content, .. } => found.push((name.clone(), content.clone())),
        AemNode::Panel { name, .. } if name.starts_with("TBL_") => panels.push(name.clone()),
        _ => {}
    });

    assert!(
        panels.is_empty(),
        "no linear TBL_ panel survives: {panels:?}"
    );
    assert_eq!(found.len(), 1, "one table, one component");
    let (name, markup) = &found[0];
    assert!(name.starts_with("TBL_"), "named as a table: {name}");

    let en = markup.get("en").expect("English markup");
    assert!(
        en.contains("<table>") && en.contains("<thead>") && en.contains("<th>Plan</th>"),
        "the header row is a real header row: {en}"
    );
    assert!(
        en.contains("<td>Strategy A</td>") && en.contains("<td>50%</td>"),
        "and the body cells are real cells: {en}"
    );
    let it = markup.get("it").expect("Italian markup");
    assert!(
        it.contains("<th>Piano</th>") && it.contains("<td>Strategia A</td>"),
        "each language gets its own markup, rendered from its own cells: {it}"
    );
}

/// A table whose cells hold an input field keeps the older linear `TBL_` panel.
/// The HTML component is static markup, so routing such a table through it would
/// drop the field without a trace -- far worse than losing the grid.
#[test]
fn a_table_holding_an_input_field_keeps_the_linear_panel() {
    use crate::aem::{AemNode, convert_to_aem};
    use crate::structured::StructuredNode;

    let field = StructuredNode::Field(make_field("Share", "Share"));
    let content = vec![bilingual_table(vec![
        bilingual_cell("Strategy A", "Strategia A"),
        field,
    ])];
    let config = ubs_config_for("en", &["en".to_string(), "it".to_string()], "TEST");
    let root = convert_to_aem(&content, &config);

    let mut html = 0usize;
    let mut table_panels = Vec::new();
    let mut fields = Vec::new();
    helpers::walk_aem_nodes(&root, &mut |node| match node {
        AemNode::HtmlDisplayer { .. } => html += 1,
        AemNode::Panel { name, .. } if name.starts_with("TBL_") => table_panels.push(name.clone()),
        AemNode::TextField { name, .. } => fields.push(name.clone()),
        _ => {}
    });

    assert_eq!(html, 0, "a table with an input does NOT become markup");
    assert_eq!(
        table_panels.len(),
        1,
        "it keeps its TBL_ panel: {table_panels:?}"
    );
    assert_eq!(
        fields.len(),
        1,
        "and the field survives as a real component: {fields:?}"
    );
}


/// A form whose repeating panel carries the archetype attributes
/// `repeatable.xml` writes, plus an ordinary panel carrying an
/// `accessibilityLabel` a person authored.
#[cfg(test)]
const ARCHETYPE_ATTRS_FORM_XML: &str = r##"<?xml version="1.0" encoding="UTF-8"?>
<jcr:root xmlns:sling="http://sling.apache.org/jcr/sling/1.0" xmlns:fd="http://www.adobe.com/aemfd/fd/1.0"
    xmlns:cq="http://www.day.com/jcr/cq/1.0" xmlns:jcr="http://www.jcp.org/jcr/1.0"
    xmlns:nt="http://www.jcp.org/jcr/nt/1.0" jcr:primaryType="cq:Page">
    <jcr:content jcr:primaryType="cq:PageContent" jcr:language="de" jcr:title="ARCH"
        sling:resourceType="/apps/ajila-forms-customers/ajila-forms-ubs/components/pages/aftemplatedpage">
        <guideContainer jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/components/guideContainer"
            guideNodeClass="guideContainerNode" name="guide1">
            <rootPanel jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/components/rootPanel"
                guideNodeClass="rootPanelNode" name="guideRootPanel">
                <items jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/layouts/gridFluidLayout2">
                    <panel_plain jcr:primaryType="nt:unstructured"
                        sling:resourceType="ajila-forms-customers/ajila-forms-ubs/components/controls/panel"
                        accessibilityLabel="Hand-authored label" guideNodeClass="guidePanel"
                        name="PN_Plain" textIsRich="true">
                        <items jcr:primaryType="nt:unstructured" sling:resourceType="fd/af/layouts/gridFluidLayout2">
                            <repeatableInner jcr:primaryType="nt:unstructured" jcr:title="Client"
                                sling:resourceType="ajila-forms-customers/ajila-forms-ubs/components/controls/panel"
                                accessibilityLabel="Client" addButton="BT_Add" ajilaPanelSubject="Client"
                                dorFieldStyling="Repeating Panel Numbering" guideNodeClass="guidePanel"
                                headingLevel="3" maxOccur="4" minOccur="1" name="RCP_Client_repeat"
                                removeButton="BT_Remove" summaryHeadingLevel="4" textIsRich="true">
                                <items jcr:primaryType="nt:unstructured"/>
                            </repeatableInner>
                        </items>
                    </panel_plain>
                </items>
            </rootPanel>
        </guideContainer>
    </jcr:content>
</jcr:root>
"##;

/// The repeating-panel archetype is engine-owned: `repeatable.xml` writes
/// `accessibilityLabel`, `addButton`, `ajilaPanelSubject`, `removeButton` and
/// `summaryHeadingLevel` itself, so a loaded value must NOT be kept as
/// unmodeled passthrough. Keeping it carried a stale value forward and made
/// load -> save -> load stop being a fixpoint on every deployed package that
/// predates the archetype (the regression `b15ff20` introduced on
/// `Germany_AACR.zip`).
///
/// An ordinary panel's `accessibilityLabel` is a different thing entirely -- a
/// person authored it and no template regenerates it -- so it is kept.
#[test]
fn the_repeating_panel_archetype_attributes_are_not_passthrough() {
    use crate::aem::{AemNode, parse_aem_zip};

    let zip = helpers::aem_zip_from_form_xml("ARCH", ARCHETYPE_ATTRS_FORM_XML);
    let package = parse_aem_zip(&zip).expect("parse the archetype fixture");

    let mut repeatable_uuid = None;
    let mut panel_uuid = None;
    helpers::walk_aem_nodes(&package.root, &mut |node| match node {
        AemNode::Repeatable { uuid, name, .. } if name == "RCP_Client_repeat" => {
            repeatable_uuid = Some(*uuid);
        }
        AemNode::Panel { uuid, name, .. } if name == "PN_Plain" => panel_uuid = Some(*uuid),
        _ => {}
    });

    let repeatable = package.raw_by_uuid[&repeatable_uuid.expect("the repeating panel")].clone();
    for owned in [
        "accessibilityLabel",
        "addButton",
        "ajilaPanelSubject",
        "removeButton",
        "summaryHeadingLevel",
    ] {
        assert!(
            !repeatable.raw_attributes.contains_key(owned),
            "`{owned}` is the template's to write, so it must not be captured: {:?}",
            repeatable.raw_attributes.keys().collect::<Vec<_>>()
        );
    }
    assert!(
        repeatable.raw_attributes.contains_key("dorFieldStyling"),
        "an attribute the archetype does NOT cover is still captured: {:?}",
        repeatable.raw_attributes.keys().collect::<Vec<_>>()
    );

    let panel = package.raw_by_uuid[&panel_uuid.expect("the plain panel")].clone();
    assert_eq!(
        panel.raw_attributes.get("accessibilityLabel").map(String::as_str),
        Some("Hand-authored label"),
        "an ordinary panel's own label survives: {:?}",
        panel.raw_attributes
    );
}
